export default [{"id":730,"question":"ما حكم حلق اللحية أو جزء منها؟ مع ذكر حدِّ شعر اللحية.وما رأيكم سماحة الشيخ فيمَن يحلق لحيته أو يُقصّر منها بحجّة أنَّ مصلحة الدَّعوة تقتضي ذلك، أو حتى يتقبّل الناسُ مني ولا يشعرون أني مُتشدد؟","title":"حكم حلق اللحية أو بعضها أو بحجة الدعوة","answer":"الجواب: يقول الرسول ﷺ في الحديث الصَّحيح في \"الصحيحين\" من حديث ابن عمر: قصُّوا الشَّوارب، وأعفوا اللِّحَى، خالفوا المجوس، وفي اللفظ الآخر: قصُّوا الشَّوارب، ووفِّروا اللِّحَى، خالفوا المشركين، وفي اللفظ الآخر: جزُّوا الشَّوارب، وأرخوا اللِّحَى، خالفوا المجوس.\nفالنبي ﷺ أمر بقصِّ الشوارب، وإعفاء اللحى وتوفيرها وإرخائها، فلا يجوز للمسلم أخذها، ولا قصها، ولا حلقها، والواجب عليه أيضًا قصّ الشوارب وإحفاؤها كما أمر النبيُّ ﷺ بذلك. ولا يجوز أن يقول: إنَّ هذا لأجل الدعوة، فالدعوة لا يُتقرب إليها بالمعاصي، ولا يُتقرب إلى المدعوين بالمعاصي، بل تقربه إليهم بإظهار المعصية مما يُنفّر من دعوته عند أهل الحقِّ، ومما يُشكك في إيمانه ودعوته عند أهل الحقِّ.\nفالواجب عليه أن يتحلَّى بالشرع، كما أنه لا يجوز له أن يدع الصلاة إذا كان يدعو ناسًا لا يُصلون، لا يقول: أنا أترك الصلاةَ حتى أُشابههم؛ حتى لا ينفروا مني، يُصلي ولا عليه منهم، يُصلي ويدعوهم إلى الصلاة، يصوم ويدعوهم إلى الصيام، ويُوفّر لحيته ويدعوهم إلى توفير اللِّحَى، وإلى غير ذلك مما شرع الله، ولا يجعل حلقها وسيلةً إلى دعوتهم بزعمه إلى طاعة الله ورسوله، ولا يتقرب إلى الله بالمعاصي، ولا يتقرب إلى المدعوين بمخالفة أمر الله.\nحدُّ اللحية: ما نبت على الخدين والذقن، هذا يُقال له: لحية، قاله في \"القاموس\" وفي \"لسان العرب\"، أما ما ينبت على الحلق فليس من اللحية، وهكذا ما فوق الخدِّ، ما فوق العظم الذي يلي الأذن، ما فوقه من تبع الرأس، الصّدغين من تبع الرأس، وإنما اللحية: ما نبت على الخدين، وهذا العظم الذي يلي الأذن هذا حدُّ ما بين اللحية والرأس، وهو الفاصل الذي يُوازي الأذن، وهو على حدِّ الأذن، والحلق كذلك، الحلق ليس من اللحية، إنما هو العظم هذا وما ينبت عليه أو فوقه، فوقه تحت الشّفة السُّفلى، كل هذا من اللحية، وهكذا الخدَّان.","link":"https://binbaz.org.sa/fatwas/20623/حكم-حلق-اللحية-او-بعضها-او-بحجة-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0554ما حكم حلق اللحية أو جزء منها وما رأيكم فيما يحلق لحيته أو يقصر منها بحجة الدعوة.mp3","categories":["سنن الفطرة"]},{"id":761,"question":"السلام عليكم ورحمة الله وبركاته، وبعد: نريد من سعادتكم أن تُخبرونا بأحكام الأمور الآتية:أولًا: إسبال الثياب.ثانيًا: حلق اللِّحى.ثالثًا: إطالة الشَّوارب.جزاكم الله عنا خيرًا.","title":"حكم الإسبال وحلق اللحى وإطالة الشوارب","answer":"الجواب: ثبت عن رسول الله ﷺ في هذه المسائل الثلاث ما يدل على تحريمها والتَّحذير منها: فقال عليه الصلاة والسلام: ثلاثةٌ لا يُكلِّمهم الله، ولا ينظر إليهم يوم القيامة، ولا يُزَكِّيهم، ولهم عذابٌ أليمٌ: المسبل إزاره، والمنَّان بما أعطى، والمُنَفِّق سلعته بالحلف الكاذب، وقال عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في \"الصحيح\".\nفهذا يُبين لنا أن الإسبال محرَّمٌ، وأنَّ فيه الوعيد، وما ذاك إلا لأنه وسيلة للتَّكبر والتَّعاظم، ولأنه إضاعة للمال، وإفساد له، وإسراف، ولأنه وسيلةٌ إلى تلطخه بالنَّجاسات والأوساخ، فهو محرَّمٌ من وجوهٍ كثيرةٍ:\nمنها: أنَّ الله جلَّ وعلا بيَّن تحريمه على لسان نبيه عليه الصلاة والسلام.\nومنها: أنه من الإسراف، والله حرَّم الإسراف.\nومنها: أنه وسيلةٌ إلى التَّكبر والتَّعاظم لمن جرَّه لغير هذا القصد، فإنه وسيلةٌ إلى تعاظمه وتكبُّره على إخوانه، والغالب على مَن جرَّ ثوبه التَّكبر، ولهذا قال عليه الصلاة والسلام: مَن جرَّ ثوبَه خُيلاء لم ينظر الله إليه يوم القيامة، فمع الخُيلاء صار أعظم وأكبر.\nأما ما قد يقع من انفلات الثوب وانطلاق خمنته وهو لا يُريد التَّكبر ولا يرضى بالإسبال، بل يتعاهد ثوبه ويرفعه، ولكن قد ينحلّ في بعض الأحيان، ثم يتعاهده ويرفعه؛ ما يضرُّه هذا، لكن مَن يُطلقه عمدًا ويسحبه عمدًا فهذا قد تعمَّد الإسبال، فقد تعرض لغضب الله في هذا ووعيده، ولهذا قال عليه الصلاة والسلام: إياك والإسبال، فإنه من المخيلة، سماه \"مخيلةً\" يعني: أنه من الكبر، وإن زعم صاحبُه أنه ما أراد الكبر، مع ما فيه من إضاعة المال، وإفساد الملابس بالوسخ والنَّجاسة، ومع ما فيه من الإسراف.\nوأما قصّ اللِّحى وحلقها وإطالة السّبالات -وهي الشَّوارب- فقد نبَّه النبيُّ على هذا عليه الصلاة والسلام، وبيَّن حُرمة ذلك، فقال عليه الصلاة والسلام: قصُّوا الشَّوارب، وأعفوا اللِّحَى، خالفوا المشركين متفق عليه في \"الصحيحين\"، وقال عليه الصلاة والسلام: قصُّوا الشوارب، ووفروا اللِّحَى رواه البخاري في \"صحيحه\"، وقال: جزوا الشَّوارب، وأرخوا اللِّحى، خالفوا المجوس رواه مسلم في \"صحيحه\"، وقد جمع ﷺ بين جزِّ الشَّوارب وقصّها، وبين إكرام اللِّحى وإرخائها وتوفيرها، هذا هو الواجب.\nولا ينبغي لعاقلٍ أن يغترَّ بالناس ويقول: الناس فعلوا! فإنَّ مَن قلَّد الناس وقع في المعاطب، فالناس فيهم المشرك والكافر، وفيهم الفاسق، وفيهم الظالم، وفيهم العاقّ لوالديه، وفيهم المرابي، إلى غير هذا، فمَن قلَّد الناسَ وتابعهم هلك.\nفالواجب الحذر، الواجب أن يحذر، وألا يتأسَّى بالناس في الباطل، إذا كنتَ مُتأسيًا فعليك بالتأسي بأهل الحقِّ والاستقامة، لا بأهل الباطل، الرسول ﷺ هو أولى بالتأسي، قال الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، وقال ﷺ: مَن رغب عن سُنتي فليس مني، وهكذا أصحابه بعده  وأرضاهم هم قدوة المؤمنين وأسوتهم، فلا يجوز للمؤمن أن يحيد عن سبيل الاستقامة إلى سبيل النَّدامة والانحراف، والله المستعان.","link":"https://binbaz.org.sa/fatwas/20683/حكم-الاسبال-وحلق-اللحى-واطالة-الشوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0584حكم اسبال الثياب وحلق اللحى واطالة الشوارب؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة","سنن الفطرة"]},{"id":791,"question":"ما حكم تطويل الأظفار ولبس الثوب نصف الكمّ للمرأة؟ وما حكم قصّ الشعر؟","title":"حكم تطويل الأظفار ونصف الكم للمرأة","answer":"الجواب: الرسول ﷺ أمر في قصِّ الشارب وفي الإبط والأظفار والعانة: ألا يُترك ذلك أكثر من أربعين ليلة، قال أنس: \"وقَّت لنا في قصِّ الشارب وقلم الأظفار ونتف الإبط وحلق العانة ألا نترك ذلك أكثر من أربعين ليلة\"، فإذا بقي الظفرُ أقلَّ من أربعين، أو الشَّارب، أو العانة، أو الإبط، فلا حرج، ولا يجوز أن يبقى أكثر من ذلك.\nوإن طوّلت أظفارها بقصد التَّشبه بالكفرة صار محرَّمًا بهذا القصد، إذا طوّلت أظفارها أو فعلت شيئًا لقصد التَّشبه بالكافرات هذا لا يجوز: مَن تشبَّه بقومٍ فهو منهم.\nوأما لبس الكم القصير بين النساء فلا بأس، لكن بين الرجال الأجانب لا، أما عند النساء فلا بأس، لكن ينبغي لها أن تعتاد الطويل، حتى لا تعتاد القصير؛ لأنها إذا اعتادت القصيرَ قد تبرز به عند أخي زوجها، أو عند خادمها، أو عند سائقها، قد تتساهل، فالأولى بها أن تعتاد الكم الطويل والثياب الطويلة، حتى إذا خرجت إلى هنا أو هنا فإذا هي في ملابس ضافية وكافية.\nوالسنة للمُؤمنة أن تكون ثيابُها طويلةً، تُغطي أقدامَها شبرًا إلى ذراعٍ، أو عليها جوارب في رجليها تسترها، والكمّ يكون طويلًا يُغطي ساعدها كله إلى رسغها، وإذا كان عندها أجنبيٌّ سترت كفَّيها، كما تستر وجهها أو بدنها. أما بين النِّساء فالأمر في هذا واسعٌ، لكنه يُخشى أن تعتاده، فلهذا قلنا: إنَّ الأولى بها ألا تعتاد ذلك ولو عند النساء، حتى لا تفعله عند غيرهن.","link":"https://binbaz.org.sa/fatwas/20784/حكم-تطويل-الاظفار-ونصف-الكم-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0615حكم تطويل الأظفار ولبس الثوب نصف الكم للمرأة؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":879,"question":"ما حكم قصّ السّبالين؟","title":"ما حكم قصّ السّبالين (طرفي الشوارب)؟","answer":"الجواب:\n\nواجب، الرسول عليه الصلاة والسلام قال: قصّوا الشوارب، قصّوا السبالات، وهي أطراف الشَّوارب، لا يفتلها ليطولها، لكن يجوز تركها أقلّ من أربعين ليلة، قال أنسٌ : \"وقَّت لنا في قصّ الشارب وقلم الظفر ونتف الإبط وحلق العانة ألا نترك ذلك أكثر من أربعين ليلةً\" رواه مسلم في \"صحيحه\"، فإذا تركها إلى هذه المدة فلا حرج، ولكن الأفضل أن يتعاهده قبلها، فإذا تمت المدةُ وجب عليه القصّ.\nوهكذا حلق العانة، ونتف الإبط، وقلم الأظفار، لا يزيد على أربعين ليلةً، بل يُلاحظ ذلك، ويعتني به قبل الأربعين.\nوهذا في الرجل والمرأة جميعًا، عامٌّ للرجال والنساء: نتف الإبط، وحلق العانة، وقلم الأظفار للجميع، أما قصّ الشارب فمعلومٌ أنه تبع الرجال.\nأما اللحية فالواجب إكرامها وإعفاؤها وتوفيرها وإرخاؤها، كما أمر به النبيُّ ﷺ، وليس لأحدٍ أخذها، لا جندي، ولا غير جندي، الواجب إعفاؤها، كما قال ﷺ: قصُّوا الشوارب، وأعفوا اللحى، قصُّوا الشوارب، ووفِّروا اللِّحى، قصوا الشَّوارب، وأرخوا اللحى، خالفوا المجوس، خالفوا المشركين، هكذا ثبت عنه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/20922/ما-حكم-قص-السبالين-طرفي-الشوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0717ما حكم قص السبالين؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1003,"question":"إني أحبُّكم في الله، كثيرٌ من الناس يتهاونون في السنة: كحلق اللحية، وتطويل الثياب، نطلب التَّوجيه، جزاكم الله خيرًا.","title":"ما النصيحة تجاه التهاون بالإسبال واللحية؟","answer":"الجواب: أولًا: أحبَّك الله الذي أحببتنا له، والتَّحابُّ في الله من أفضل القربات، بل من الواجبات، وقد قال عليه الصلاة والسلام في الحديث الصحيح: سبعة يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجلٌ دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله ومثله امرأةٌ دعاها ذو منصبٍ وجمالٍ فقالت: إني أخاف الله، والسادس: رجلٌ تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شمالُه ما تُنْفِق يمينه، والسابع: رجلٌ ذكر الله خاليًا –يعني: ما عنده أحدٌ- ففاضت عيناه بكاءً من خشية الله عزَّ وجل.\nوقال أيضًا عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظلَّ إلا ظلي، والتَّحاب في الله يقتضي التَّعاون على البر والتقوى، ويقتضي التَّناصح والأمر بالمعروف والنَّهي عن المنكر، هكذا يكون المتحابُّون في الله.\nأما ما يتعلق بإعفاء اللِّحى وإسبال الثياب: فهذه أمورٌ واجبة، ليست مجرد سنةٍ في اصطلاح مَن يرى أنَّ السنة يُثاب فاعلها ولا يُعاقَب تاركها، بل إعفاء اللحية من الواجبات، وأخذها من المحرَّمات، والإسبال من المحرمات، فلا يجوز للمؤمن حلق لحيته ولا قصّها، بل يجب إعفاؤها وإكرامها وتوفيرها، قال عليه الصلاة والسلام: قصُّوا الشَّوارب، وأعفوا اللحى، خالفوا المشركين، وقال عليه الصلاة والسلام: قصُّوا الشوارب، ووفروا اللِّحى، خالفوا المشركين، وقال عليه الصلاة والسلام: جزُّوا الشَّوارب، وأرخوا اللِّحى، خالفوا المجوس، فالواجب إعفاؤها وإكرامها وإرخاؤها، وإن قصَّها الناسُ لا تكن مع الناس، كن مع الحقِّ، ولو كنتَ وحدك، لو كان أهلُ قريةٍ أو قبيلةٍ قد قصُّوا أو حلقوا لا تكن معهم، الزم الحقَّ ولو كنتَ وحدك.\nوهكذا جرُّ الملابس، الملابس حدُّها الكعب للرجل، فما أسفل من الكعبين يجب تركه، ويحرم فعله، يقول عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في \"الصحيح\"، ويقول ﷺ: إياك والإسبالَ، فإنه من المخيلة، ويقول عليه الصلاة والسلام: ثلاثةٌ لا يُكلِّمهم الله ولا ينظر إليهم يوم القيامة ولا يُزكّيهم، ولهم عذابٌ أليم: المسبل إزاره، والمنَّان بما أعطى، والمُنَفِّق سلعتَه بالحلف الكاذب رواه مسلم، وما ذاك إلا لأنَّ الإسبال يُعطي دلالةً على التَّكبر والتَّعاظم، مع ما في ذلك من الإسراف وإفساد الثياب بالأوساخ والنَّجاسات.\nومَن زعم أنه يجوز إذا كان على غير تكبرٍ؛ فقد غلط، فالرسول نهى وعمَّم عليه الصلاة والسلام، وتوعَّد على ذلك، وجعل الإسبالَ من المخيلة، ثم القلوب لا يعلمها إلا الله، مَن أسبل فقد تظاهر بظاهر الكِبر؛ فوجب منعه والإنكار عليه.\nوأما ما جاء في حديث ابن عمر: أنَّ الصديق  لما سمع قوله ﷺ: مَن جرَّ ثوبه خُيلاء لم ينظر الله إليه يوم القيامة، قال: يا رسول الله، إنَّ إزاري يسترخي إلا أن أتعاهده، فقال له رسولُ الله ﷺ: لستَ ممن يفعله للكبر، فهذه شهادةٌ من النبي ﷺ للصديق أنه لا يفعله للكبر، وإنما قد يرتخي إزاره من غير قصدٍ منه، فيتعاهده، أما هؤلاء فيجرونها تعمُّدًا، ولا يتعاهدونها، ومَن يعلم قلوبهم إلا الله ؟ فظاهرهم الإسبال والخيلاء والتَّكبر، وإن زعموا خلاف ذلك.\nثم إنهم قد تظاهروا بمخالفة شرع الله، وبما نهى الله عنه، فوجب عليهم ترك ذلك، والإنكار عليهم، أما المرأةُ فلها إرخاء الثياب، يُشرع لها إرخاء الثياب؛ لأنها عورةٌ تستر أقدامها.","link":"https://binbaz.org.sa/fatwas/21050/ما-النصيحة-تجاه-التهاون-بالاسبال-واللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0846كثير من الناس يتهاونون في تطبيق السنة فما نصيحتكم؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1019,"question":"لقد وُلد لي مولودٌ ذكرٌ، وهو مختونٌ، هل يجوز أن أختنه مرةً أخرى؟","title":"حكم من وُلِد له مولودٌ مختون؟","answer":"الجواب: إذا كان مختونًا فالحمد لله، كفاك الله مُؤنته، فليس عليك ختانٌ، ماذا يُختن منه ما دامت القلفة قد ذهبت ولم يكن له قلفة؟ هذا يقع في كثيرٍ من الأحيان، بعض الذكور يقع ليس له قلفة، فأنت كُفيت المؤنة، فاحمد ربَّك، واشكر الله، وليس عليك شيءٌ.","link":"https://binbaz.org.sa/fatwas/21057/حكم-من-ولد-له-مولود-مختون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0853يقول السائل لقد ولد لي مولود ذكر وهو مختون فهل أختنه مرة أخرى؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1824,"question":"حلق اللحية هل يكون من التَّخنُّث في شيءٍ؟","title":"هل يُعَدُّ حلق اللحية من التَّخنُّث؟","answer":"الجواب:\nهو محرَّم، وفيه تشبُّه بالنساء؛ لأنَّ النساء ليس لهنَّ لحًى.\nس: لكن بعض الفقهاء يُدخِل حالقَ اللحية تحت حكم التَّخنُّث؟\nج: حكاه ابنُ عبدالبر عن بعض أهل العلم؛ لأنَّ وجود لحيةٍ بدون شعرٍ فيه تشبُّه بالنساء.","link":"https://binbaz.org.sa/fatwas/21932/هل-يعد-حلق-اللحية-من-التخنث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حلق اللحية هل يكون من التَّخنُّث.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1837,"question":"هل الأَوْلَى الخِضَاب (في اللحية)؟","title":"حكم تخضيب اللحية بالحُمرة والصُّفرة","answer":"الجواب:\nالأفضل الخِضَاب، يخضبها بالحمرة، بالصفرة، لا بالسواد، أو بالسواد مع الحمرة فيصير مخلوطًا بين السواد والحمرة، أما الأسود الخالص فلا، يقول النبيُّ ﷺ: غيِّروا هذا الشَّيبَ، واجتنبوا السَّواد.","link":"https://binbaz.org.sa/fatwas/21946/حكم-تخضيب-اللحية-بالحمرة-والصفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تغيير اللحية وتخضيبها.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1840,"question":"بالنسبة لكدَّ اللحية مثلًا للتَّجمل وما شابهه، هل فيه شيء؟","title":"حكم كَدِّ اللحية للتَّجَمُّل وما شابهه","answer":"الجواب:\nما أعرف الكدَّ، لكن الكدَّ يقطعها.\nس: بالنسبة للذي يحلق لحيته أو يأخذ منها شيئًا هل يأثم؟\nج: نعم، يأثم، لا شكّ، فهذه معصية، يقول النبي ﷺ: قصُّوا الشَّوارب، ووفِّروا اللِّحَى، خالفوا المشركين، ومخالفة الأوامر معصية.","link":"https://binbaz.org.sa/fatwas/21949/حكم-كد-اللحية-للتجمل-وما-شابهه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كد اللحية للتجمل أو أخذ شيء منها.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1841,"question":"بعض الإخوان إذا سُئِل: لماذا تصبغ لحيتك بالسَّواد؟ يقول: أنا أحسن ممن يحلقها؟","title":"حكم صبغ اللحية بالسواد والأخذ منها","answer":"الجواب:\nيُداوي معصيةً بمعصية! هذا ما يصح.\nس: أيهم أفضل: الأخذ منها أو حلقها؟\nج: لا يجوز: لا حلقها، ولا الأخذ منها، قال الرسول ﷺ وفِّروها، أمر بالتَّوفير.","link":"https://binbaz.org.sa/fatwas/21950/حكم-صبغ-اللحية-بالسواد-والاخذ-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في اللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1843,"question":"بعض الذين يأخذون من لحاهم يحتجُّون بحديث ابن عمر ويقولون: كان يأخذ كذا وكذا؟","title":"حكم الاحتجاج بحديث ابن عمر في اللحية","answer":"الجواب:\nابن عمر ما هو معصوم.\nس: حجتهم باطلة؟\nج: ما هو معصوم ابن عمر، المعصوم الرسول ﷺ، هو المُبَلِّغ عن الله، الله يقول: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ [الحشر:7]، أو قال: وما آتاكم ابنُ عمر فخذوه؟!\nس: حجتهم باطلة؟\nج: ما في شك، الله يهدي الجميع، كل واحدٍ قد يغلط.","link":"https://binbaz.org.sa/fatwas/21952/حكم-الاحتجاج-بحديث-ابن-عمر-في-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاحتجاج بحديث بن عمر في جواز الأخذ من اللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1858,"question":"هل يُفْصَل بين الشارب واللحية؟","title":"ما حكم الفصل بين الشارب واللحية؟","answer":"الجواب:\nالحدّ معروف.\nس: يعني: يُفْصَل؟\nج: نعم، حتى يتبين الشارب من اللحية، الشارب يقصه ويحفه واللحية يبقيها.","link":"https://binbaz.org.sa/fatwas/21967/ما-حكم-الفصل-بين-الشارب-واللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفصل بين الشارب واللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2513,"question":"قوله ﷺ: أكْثَرَتُ عليكم في السواك؟","title":"معنى حديث \"أكْثَرَتُ عليكم في السواك\"","answer":"الجواب:\nيعني لتأكُّده وفضله.\nس: هذه الأحاديث تدل على أن السواك للوجوب؟\nالشيخ: لا، مستحب، ولذلك قال: لولا أن أشق عليكم لأمرتكم.. فجعله الله مستحبًا.","link":"https://binbaz.org.sa/fatwas/22643/معنى-حديث-اكثرت-عليكم-في-السواك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السواك وأحكامه.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2515,"question":"الحديث في استياك النبي ﷺ في رمضان؟","title":"هل صح استياكُ النبي ﷺ في رمضان؟","answer":"الجواب:\nفي حديث عامر بن ربيعة: رأيت النبي ﷺ يستاك ما لا أحصي وهو صائم، لكن لا أعرف حال سنده الآن، يحتاج إلى مراجعة. لكن قوله ﷺ: مع كل وضوء يكفي، يَعُمُّ رمضان وغيره، ويَعُمُّ الصائم وغير الصائم، مع كل وضوء، مع كل صلاة، يعم الظهر والعصر في حق الصائم وغيره.\nس: في أثناء المضمضة؟\nالشيخ: عند المضمضة، عندما يبدأ الوضوء.","link":"https://binbaz.org.sa/fatwas/22645/هل-صح-استياك-النبي-ﷺ-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استياك النبي عليه الصلاة والسلام في رمضان.mp3","categories":["سنن الفطرة","شروح الحديث"]},{"id":2517,"question":"السواك في خطبة الجمعة؟","title":"حكم استعمال السواك أثناء خطبة الجمعة","answer":"الجواب: ما يصلح وقت الخطبة، ينصت ويترك الحركة، لا بالسواك ولا بغيره، يكون مُنْصتًا للخطيب، لا يشتغل بالسواك ولا بغيره.","link":"https://binbaz.org.sa/fatwas/22647/حكم-استعمال-السواك-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السواك في خطبة الجمعة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2521,"question":"التحديد بالنسبة لتقليم الأظافر؟","title":"ما أقصى مدة لترك تقليم الأظفار؟","answer":"الجواب: لا يُترك أكثر من أربعين يومًا، يجب أن يأخذ قبل أربعين يومًا.","link":"https://binbaz.org.sa/fatwas/22652/ما-اقصى-مدة-لترك-تقليم-الاظفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكثر وقت تقليم الأظافر.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2522,"question":"بعض كبار السن يَحلقون اللحية ويُبقون الذقن، ويقولون إن هذا ما زاد عن قبضة اليد؟","title":"ما حكم مَنْ يحلق اللحية ويترك الذقن فقط؟","answer":"الجواب: هذا غلط، والواجب إعفاؤها، هذا يُروى عن ابن عمر أنه كان يفعله في الحج والعمرة، يأخذ ما زاد على القبضة، لكن نقول: اجتهاده  خالف فيه السنة؛ اجتهادًا، غير مصيب، والصواب ما هو بحديث، هو يُروى عن ابن عمر مِن فِعله، وأما أنه كان يأخذ من لحيته؛ هذا حديث ضعيف غير صحيح، ما كان يأخذ منها عليه الصلاة والسلام، بل كان يعفيها ويُوَفِّرها، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22653/ما-حكم-من-يحلق-اللحية-ويترك-الذقن-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حلق اللحية وإبقاء الذقن.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2523,"question":"بالنسبة لخصال الفطرة: يوم الجمعة أفضل؟","title":"حكم تخصيص يوم معين لخصال الفطرة","answer":"الجواب: ما لها يوم معين.","link":"https://binbaz.org.sa/fatwas/22654/حكم-تخصيص-يوم-معين-لخصال-الفطرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تخصيص يوم معين لخصال الفطرة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2524,"question":"في بعض الروايات أحْفُوا الشَّواربَ ؟","title":"معنى \"أحْفُوا الشَّواربَ\" في الحديث","answer":"الجواب: يعني: أخذها أخذًا جيد، قصها قصًّا جيدًا، ما هو بحلق، قص لكن قص قوي.\nس: الحلق ليس من السنة؟\nالشيخ: لا لا، تركها أوْلى، السنة القص..... الحديث صحيح لا بأس به، أخذ الشارب واجب، لكن رخَّص النبي ﷺ في أقل من أربعين.","link":"https://binbaz.org.sa/fatwas/22655/معنى-احفوا-الشوارب-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى أحفوا الشوارب.mp3","categories":["سنن الفطرة","شروح الحديث"]},{"id":2525,"question":"الخِتَان بالنسبة للنساء؟","title":"حكم الخِتان للنساء","answer":"الجواب: إذا تيسر؛ الخاتنة تفهم، أو الخاتن يفهم؛ فلا بأس سنة، إذا تيسر من يختنها من الرجال والنساء العارفين فهو السنة.\nس: تركه بالنسبة للنساء؟\nالشيخ: إذا تُرك لا بأس، إذا ما تيسر مَنْ يختن، إذا ما تيسر حاذق يعرف ذلك.","link":"https://binbaz.org.sa/fatwas/22656/حكم-الختان-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الختان للنساء.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2526,"question":"ما يقال أن الختان واجب؟","title":"ما الصحيح في حكم الختان؟","answer":"الجواب: هو قول جمع من أهل العلم؛ لأنه يروى في بعض الأحاديث، لما أسلم بعض الكفار قال له النبي ﷺ: ألق عنك إزار الكفر واختتن لكن الأشهر أنه سنة؛ لأن الرسول ﷺ ما أمر الناس أن يختتنوا كلهم، دل على أنه سنة.\nس: عدم الاختتان ما يكون فيه مشابهة للمشركين؟\nالشيخ: لا ما فيه مشابهة، بعض المشركين يختتن، اليهود تختن.","link":"https://binbaz.org.sa/fatwas/22657/ما-الصحيح-في-حكم-الختان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الختان وحكمه وحكم تركه.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2527,"question":"هذا بمعنى التحريم: مَن يتعدى أكثر من شهرين أو ثلاثة (خصال الفطرة)؟","title":"ما أكثر مدة تُترك فيها خِصال الفطرة؟","answer":"الجواب: أكثر من أربعين ما يجوز.","link":"https://binbaz.org.sa/fatwas/22658/ما-اكثر-مدة-تترك-فيها-خصال-الفطرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكثر مدة يترك فيها خصال الفطرة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2528,"question":"من قال أن الطهارة لا تتم إلا بالختان؟","title":"هل للختان تَعَلُّق بالطهارة؟","answer":"الجواب: قول ضعيف، الطهارة ما لها تَعَلُّق بالختان، إذا استنجى يكفي.  لكن الخِتان مطلوب بين الوجوب وبين السُّنة المؤكدة.","link":"https://binbaz.org.sa/fatwas/22659/هل-للختان-تعلق-بالطهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للختان تعلق بالطهارة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2861,"question":"السُّنة في قص الشارب: هل الإطار، أو يُحْلَق؟","title":"ما السُّنة في قص الشارب وكيفيته؟","answer":"الجواب: السُّنة الإحفاء أحفوا الشوارب بالقص، ما هو بالحَلْق.","link":"https://binbaz.org.sa/fatwas/23014/ما-السنة-في-قص-الشارب-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة في قص الشارب.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2871,"question":"شعر الخدين في الوجه: هل جائز أخذه؟","title":"هل يجوز أخذ شعر الخدين؟","answer":"الجواب: اللحية ما نبت على الخدين والذقن، هذا في عرف اللغة، على الخدين والذقن هذه اللحية، لا يأخذ من الخدين ولا يأخذ اللحية.","link":"https://binbaz.org.sa/fatwas/23026/هل-يجوز-اخذ-شعر-الخدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز أخذ شعر الخدين.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3114,"question":"حلق اللحية مِن الكبائر أو مِن الصغائر؟","title":"هل حلق اللحية مِن الكبائر؟","answer":"الجواب: مُنكر ومعصية، أما كونه كبيرة فالله أعلم.\nس: الإصرار على حلق اللحية ألا يصيّرها مِن معصية إلى كبيرة؟\nالشيخ: المقصود أنها معصية، توفير اللحية واجب، وقصها وحلقها من المعاصي، أما كونها كبيرة محل بحث آخر.","link":"https://binbaz.org.sa/fatwas/23274/هل-حلق-اللحية-من-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حلق اللحية من الكبائر.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3150,"question":"عندنا مدرس يأخذ من لحيته ويقول إنه جائز ويستدل بقول الإمام الشافعي أظنه صحيح...؟","title":"ما الرد على مَنْ يجيز الأخذ مِن اللحية؟","answer":"الجواب: يُنصح يُنصح، ما لأحد كلام مع السنة، الرسول ﷺ يقول: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين.\nس: الشافعي يقول: أنه جائز الأخذ؟\nالشيخ: ولو، ولو، يُعَلّم، الشافعي وغير الشافعي ما هو بحجة في مخالفة السنة، لا الشافعي ولا غيره.\nس: يقول: المشايخ ابن باز وابن عثيمين يستدلّون بقول الإمام أحمد؟\nالشيخ: إذا قال رسول الله انتهى، لا أحمد ولا غيره، لا الشافعي ولا غيره، ابن عباس: (يوشك أن تنزل عليكم حجارة من السماء أقول قال رسول الله، وتقولون قال أبو بكر وعمر) أبو بكر وعمر وينهم، وأين الشافعي وأحمد؟ أبو بكر وعمر أعظم من الشافعي وأحمد وأبي حنيفة ومالك، أنكر عليهم ابن عباس لما خالفوا السنة لقول أبي بكر وعمر.","link":"https://binbaz.org.sa/fatwas/23312/ما-الرد-على-من-يجيز-الاخذ-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستدلال على جواز الأخذ من اللحية بقول الشافعي.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3625,"question":"حديث: ما زال جبريل يوصيني بالسواك حتى خشيت على أسناني؟","title":"هل صح حديث (حتى خشيت على أسناني)؟","answer":"الجواب: ما أعرفه.","link":"https://binbaz.org.sa/fatwas/23808/هل-صح-حديث-حتى-خشيت-على-اسناني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في السواك.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3701,"question":"الذي يخاف على نفسه مثلًا يقول: إذا لم أحلق لحيتي قد أسجن؟","title":"حكم حلق اللحية لمن خاف على نفسه","answer":"الجواب: لا، هذا من الشيطان ومن تخويف الشيطان، أما إذا أُكره فالإكراه بابه معروف حتى في الشرك: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ [النحل: 106] الإكراه الذي فيه الضرب.. الإكراه له حكمه.\nس: لا، هو يخاف؟\nالشيخ: لا، ما هو بعذر، العذر الإكراه بس.\nس: الإكراه يكون بالفعل؟\nالشيخ: يكون بالضرب والسجن والتهديد من قادر.","link":"https://binbaz.org.sa/fatwas/23891/حكم-حلق-اللحية-لمن-خاف-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حلق اللحية لمن خاف على نفسه.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3722,"question":"حلق اللحية من التخنث؟","title":"هل حلق اللحية من التخنث؟","answer":"الجواب: قد يُلحق بذلك، لكن أمره خاص، حلق اللحية محرم مطلقًا ولو ما قصد التخنث، يحرم عليه حلقها مطلقًا، وإذا أراد التخنث صار شرًّا إلى شر.","link":"https://binbaz.org.sa/fatwas/23914/هل-حلق-اللحية-من-التخنث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حلق اللحية من التخنث.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3889,"question":"بعض الناس يُرَبِّي شعر رأسه ويحلق لحيته؟","title":"حكم مَنْ يُرَبِّي شعر رأسه ويحلق لحيته","answer":"الجواب: التربية شيء، وحلق اللحية شيء، حلق اللحية محرم، وتربية الرأس جائزة، ما هي محرمة، ولا مشروعة متأكدة، لكن حلق اللحية محرم.","link":"https://binbaz.org.sa/fatwas/24105/حكم-من-يربي-شعر-راسه-ويحلق-لحيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يُربي شعر رأسه ويحلق لحيته.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4045,"question":"مَنْ لم يختتن يأثم؟","title":"هل يأثم مَنْ لم يختتن؟","answer":"الجواب: الجمهور على السنية، وذهب أحمد رحمه الله وابن عباس وجماعة إلى الوجوب.\nس: من لم يختتن يأثم؟\nالشيخ: من قال بالوجوب يأثم، ومن قال بأنه سنة لا يأثم، والذي ينبغي: فعله، كما قال ابن عباس وشدد فيه، وقال النبي لبعض الصحابة لما أسلم: ألق عنك شعر الكفر واختتن لكن في سنده ضعف.","link":"https://binbaz.org.sa/fatwas/24282/هل-ياثم-من-لم-يختتن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأثم من لم يختتن.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4046,"question":"اختتان النساء؟","title":"ما حكم اختتان النساء؟","answer":"الجواب: يستحب، إذا تيسر من يحسن ذلك.\nس: دليل اختتان النساء؟\nالشيخ: العموم، الفطرة خمس، وجاء في بعض الروايات التصريح بذلك.\nس: المرأة تختتن ولو كبرت؟\nالشيخ: إذا كان ما يخشى الخطر على الكبير: الرجل والمرأة، أما لو كان يخشى شيء؛ يسقط.","link":"https://binbaz.org.sa/fatwas/24283/ما-حكم-اختتان-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة اختتان النساء.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4052,"question":"بياض إبطيه هل هذا خاص بالنبيﷺ أم أنه نفس الإبط؟","title":"\"بياض إبطيه\" هل هو خاص بالنبي ﷺ؟","answer":"الجواب: قال بعضُهم: إنه خاص، وقال بعضُهم: إنه كان يتعاهد أخذ شعر الإبط عليه الصلاة والسلام، والسنةُ تعاهد ذلك.\nس: ما جاء في الحديث العفرة..؟\nج: العفرة بمعنى البياض.","link":"https://binbaz.org.sa/fatwas/24289/بياض-ابطيه-هل-هو-خاص-بالنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بياض إبطيه خاص بالنبي.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4172,"question":"حلق اللِّحَى هل يدخل في التَّشبه بالنساء؟","title":"هل يدخل حلق اللحية في التشبه بالنساء؟","answer":"الجواب: الحلق الكامل يصير تشبُّهًا، المرأة لا لحيةَ لها، الحلق الكامل الذي يُزيل الشعر كله تشبُّه بالنساء، مع أنه تشبّه بالكفار أيضًا، فيه تشبه بالكفار وفيه تشبه بالنساء، إذا استوفى حلقه يُخشى عليه من اللعنة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24428/هل-يدخل-حلق-اللحية-في-التشبه-بالنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حلق اللحية من التشبه بالنساء.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4173,"question":"حديث ابن عمر الذي يقول القبضة؟","title":"حكم أخذ قدْر القبضة من اللحية","answer":"الجواب: هذا من عمله، هذا غلط، هذا من فعله واجتهاده، الصواب إعفاؤها، ولا يُؤخذ منها شيء، ولو ما زاد على القبضة، فاجتهاده  مخالف لما ورد، فلا يأخذ ما زاد على القبضة .....، الرسول ﷺ أمر بإعفائها وإرخائها، وأما فعل ابن عمر في الحجِّ فهذا من اجتهاده، والأئمة غلَّطوه في هذا .","link":"https://binbaz.org.sa/fatwas/24429/حكم-اخذ-قدر-القبضة-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ القبضة من اللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4438,"question":"تقليم الأظافر يعني خاصّ بالرجال؟","title":"هل تقليم الأظفار خاصّ بالرجال؟","answer":"الجواب: لا، للرجال والنساء جميعًا، سنة قلم الأظفار ونتف الإبط وحلق العانة للجميع، للرجال والنساء.","link":"https://binbaz.org.sa/fatwas/24716/هل-تقليم-الاظفار-خاص-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقليم الأظافر يعني خاصّ بالرجال فقط.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4988,"question":"السواك هل يفضل عود على عود؟","title":"هل يفضل عود معيّن في السواك؟","answer":"الجواب: الأراك أفضل، أفضله الأراك، طيب، الأراك المناسب الذي لا يتفتت، وإذا تسوك بعود آخر يتشعث ويحصل به النقاء؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/28500/هل-يفضل-عود-معين-في-السواك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يفضل عود معين في السواك؟.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4989,"question":"بعض الأطباء صنعوا معجونًا يقولون من نفس المادة حق الأراك، هل يقوم مقام السواك أم لا؟","title":"هل المعجون المصنوع من السواك يقوم مقامه؟","answer":"الجواب: لا، المعجون يكلِّف، المعجون يحتاج كُلْفة، والسواك ما يحتاج كُلْفة، إلا إذا احتاج المعجون في بعض الأحيان من باب غسل الفم في وقت آخر غير وقت الصلاة، هذا لا بأس، أما وقت الصلاة السُّنة له السواك فقط.","link":"https://binbaz.org.sa/fatwas/28501/هل-المعجون-المصنوع-من-السواك-يقوم-مقامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المعجون المصنوع من السواك يقوم مقامه؟.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":5200,"question":"سماحة الشيخ، أفيدونا -جزاكم الله خيرًا- عن حكم حلق اللِّحى والأخذ منها وتسويتها؟","title":"حكم حلق اللحية أو الأخذ منها وتسويتها","answer":"الجواب: الرسول ﷺ قال: قصُّوا الشوارب، وأعفوا اللِّحَى، خالفوا المشركين متفق على صحَّته. ويقول ﷺ: قصُّوا الشوارب، ووفروا اللِّحَى، خالفوا المشركين، جزُّوا الشوارب، وأرخوا اللِّحَى، خالفوا المجوس. فالواجب إعفاؤها وإرخاؤها وتوفيرها وعدم قصِّها وعدم حلقها، يُوفِّرها ويجعلها على حالةٍ وافرةٍ، مُرخاة؛ طاعةً لله ورسوله، وابتعادًا عن مُشابهة الكفرة والنساء. ولا ينبغي أن يغترَّ بالناس اليوم وكثرة مَن يحلق أو يقصّ، لا يغترّ بهذا، فالتأسِّي يكون بأهل الخير، لا بأهل الشر، التأسي بالرسول ﷺ وبالأخيار، أما التأسي بمَن فعل معصيةً لا، يقول الله جلَّ وعلا: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، ويقول جلَّ وعلا: وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ [التوبة:100] اتبعوهم بإحسانٍ: ساروا على نهجهم في القول والعمل. فالمؤمن يقصّ الشارب ويُحفيه، ويُرخي اللحيةَ ويُعفيها، هذا هو الواجب الذي فعله النبيُّ ﷺ وفعله الصحابةُ، وأرشد إليه الأمةَ عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/30144/حكم-حلق-اللحية-او-الاخذ-منها-وتسويتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 173.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":5631,"question":"بعض الإخوان توسَّع في الأخذ من اللحية، يقول: هذه شوائب وزوائد، ومن قبيل هذا، كأنه مُستأنس برأي أحد العلماء؟","title":"ما حكم الأخذ من اللحية استئناسًا بفعل صحابي؟","answer":"الجواب: يُعلَّم أنَّ هذا غلط، الرسول ﷺ قال: قصوا الشَّوارب، ووفِّروا اللِّحَى، خالفوا المشركين، أخرجه البخاري في الصحيح، وفي اللفظ الآخر: قصوا الشوارب، وأعفوا اللِّحَى، خالفوا المشركين متفق عليه، وفي اللفظ الثالث عند مسلم: جزُّوا الشَّوارب، وأرخوا اللِّحى، خالفوا المجوس، فواجب إعفاؤها وإكرامها وتوفيرها وعدم التَّرخص بأقوال زيدٍ أو عمرٍو. س: وإن استدلَّ على ذلك بفعل بعض الصَّحابة؟ ج: هو معصوم الصَّحابي؟! المعصوم مَن هو فيما يُبلِّغ عن الله؟ عليك بالمعصوم، ودع عنك غير المعصوم؛ فإنه يُخطئ ويُصيب، وقل: اللهم اغفر له، فإذا كان ابن عمر أخطأ، أو زيد، أو عمرو، أو أحمد بن حنبل، أو الشافعي، أو واحد من المعاصرين أو غيرهم تقول: اللهم اغفر له، وعليك بالحقِّ، لا تترك الحقَّ لقول أحدٍ، لا لقول الصديق، ولا عمر، ولا عثمان، ولا ابن حنبل، ولا الشافعي، ولا زيد، ولا عمرو، الحق فوق الجميع متى ظهر وتبين، لكن مع التَّرضِّي عن أهل الخير، والترحم عليهم، وإحسان الظنّ بهم. س: حلق اللحية كبيرة من كبائر الذُّنوب؟ ج: معصية، وأما كونه كبيرةً الله أعلم، هو من المعاصي.[1]","link":"https://binbaz.org.sa/fatwas/31628/ما-حكم-الاخذ-من-اللحية-استىناسا-بفعل-صحابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 006.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":5689,"question":"نرى بعض الدعاة الذين يدعون الناس يخالفون سنن الرسول ﷺ في قص اللحى، فهل يجوز للدعاة ذلك؟","title":"هل يجوز للدعاة حلق أو تقصير اللحية؟","answer":"الجواب:\nالواجب على الدعاة، وعلى غير الدعاة إعفاء اللحى، وتوفيرها، وإرخاؤها، وعدم جزها وتقصيرها، هكذا أمرهم النبي ﷺ قال: قصوا الشوارب، واعفوا اللحى، خالفوا المشركين وقال: جزوا الشوارب، وأرخوا اللحى خالفوا المجوس.   فكان يأمر بإعفاء اللحى، وتوفيرها -عليه الصلاة والسلام- وينهى عن قصها، وعن جزها، فحلقها أشد وأحرم، حلقها أشد من تقصيرها، وكله محرم، وعلى الدعاة أكثر؛ لأنهم دعاة، فالواجب عليهم أكبر، وطالب العلم الإثم عليه يكون أكبر من العامة، وإن كان الجميع آثمين بفعل ما حرم الله، لكن أخذ اللحية من طالب العلم، أو قصها يكون إثمه أكبر؛ لأنه قدوة. السؤال: يا شيخ يقولون: إن  السنة لا يعاقب عليها، يعتبرونها سنة؟ الجواب: القول بأنها سنة غلط، بل واجب، سنة بمعنى الطريقة المحمدية، لكن واجب، يأثم من تركها، ثم لو قدرنا أنها مستحبة فقط، ما كان ينبغي لدعاة العلم، والدعاة، وطلبة العلم أن يضيعوا سنة واظب عليها النبي ﷺ وأمر بها، ودعا إليها، فكيف والأمر خلاف ذلك؟!  الأصل في الأوامر الوجوب، والأصل في النهي التحريم، ولا مخصص، ولم يحفظ عنه ﷺ أنه حلقها، وقصها حتى يقال: إن الأمر ليس للوجوب مع أن فعله يدل على عدم الوجوب، فلما أمر بإعفائها، وإرخائها، وأعفاها هو وأصحابه دل على وجوب ذلك.","link":"https://binbaz.org.sa/fatwas/984/هل-يجوز-للدعاة-حلق-او-تقصير-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_13.mp3","categories":["سنن الفطرة"]},{"id":5692,"question":"نرى بعض الدعاة الذين يدعون الناس يخالفون سنن الرسول ﷺ في قص اللحى، فهل يجوز للدعاة ذلك؟","title":"هل يجوز للدعاة حلق أو تقصير اللحية؟","answer":"الجواب:\nالواجب على الدعاة، وعلى غير الدعاة إعفاء اللحى، وتوفيرها، وإرخاؤها، وعدم جزها وتقصيرها، هكذا أمرهم النبي ﷺ قال: قصوا الشوارب، واعفوا اللحى، خالفوا المشركين وقال: جزوا الشوارب، وأرخوا اللحى خالفوا المجوس.   فكان يأمر بإعفاء اللحى، وتوفيرها -عليه الصلاة والسلام- وينهى عن قصها، وعن جزها، فحلقها أشد وأحرم، حلقها أشد من تقصيرها، وكله محرم، وعلى الدعاة أكثر؛ لأنهم دعاة، فالواجب عليهم أكبر، وطالب العلم الإثم عليه يكون أكبر من العامة، وإن كان الجميع آثمين بفعل ما حرم الله، لكن أخذ اللحية من طالب العلم، أو قصها يكون إثمه أكبر؛ لأنه قدوة. السؤال: يا شيخ يقولون: إن  السنة لا يعاقب عليها، يعتبرونها سنة؟ الجواب: القول بأنها سنة غلط، بل واجب، سنة بمعنى الطريقة المحمدية، لكن واجب، يأثم من تركها، ثم لو قدرنا أنها مستحبة فقط، ما كان ينبغي لدعاة العلم، والدعاة، وطلبة العلم أن يضيعوا سنة واظب عليها النبي ﷺ وأمر بها، ودعا إليها، فكيف والأمر خلاف ذلك؟!  الأصل في الأوامر الوجوب، والأصل في النهي التحريم، ولا مخصص، ولم يحفظ عنه ﷺ أنه حلقها، وقصها حتى يقال: إن الأمر ليس للوجوب مع أن فعله يدل على عدم الوجوب، فلما أمر بإعفائها، وإرخائها، وأعفاها هو وأصحابه دل على وجوب ذلك.","link":"https://binbaz.org.sa/fatwas/984/هل-يجوز-للدعاة-حلق-او-تقصير-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_13.mp3","categories":["سنن الفطرة"]},{"id":5734,"question":"هل يجوز حلق العارضين؟ وما حكم قص اللحية؟ وهل حكم قصها كحكم حلقها؟","title":"حدود اللحية وحكم حلقها وتقصيرها","answer":"الجواب:  اللحية كرامة من الله للرجل، جعلها الله كرامة للرجل، وجعلها الله ميزة له عن النساء، وجعلها ميزة له عن الكفرة الذين يحلقون لحاهم، فهي زينة الرجال، وهي نور في الوجه، وهي  ميزة لهم عن النساء، فلا يجوز له أن يتعرض لها بحلق، ولا قص، فلا يحلقها ولا يقصها، ولا يحلق العارضين مع الخدين؛ لأن اللحية اسم للشعر الذي ينبت على اللحيين والذقن، فإن الخدين والذقن هما اللحية، شعر اللحية، والذقن التي تحت الشفقة السفلى، هذا هو اللحية، فلا يجوز له قصها ولا حلقها، بل يجب إكرامها وإعفاؤها وتوفيرها؛ لأن النبي ﷺ أمر بإعفاء اللحى، وقص الشوارب، وقال: خالفوا المشركين، قصوا الشوارب وأعفوا اللحى وقال -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس وفي لفظ آخر: وفروا اللحى وأوفى اللحى.  فعلى المسلم أن يوفرها، ويرخيها، ويحرم عليه قصها وحلقها، هذا هو الواجب على المسلم، والمؤمن لا يرضى بأن يشابه أخته وبنته وعمته وأمه، بل ينبغي أن يرخيها، ويوفرها؛ حتى يبقى على سمة الرجال، ووجوه الرجال، وحتى يتباعد عن مشابهة المجوس، والمشركين الذين يحلقونها، ويطيلون السبلات، وهي الشوارب، الشارب يقص ويحفى، واللحية توفر وترخى هذا هو المشروع، هذا هو الواجب، والله المستعان. السؤال: يقولون: إن المشركين الآن الكفار يرخون لحاهم؟ الجواب:  إذا وفروها الحمد لله، عسى الله أن يهديهم، فيسلموا إذا وافقونا في الخير، ما نوافقهم في الشر، إذا وافقنا أرخوا لحاهم، وأسلموا، ودخلوا في دين الله فهذا طيب، لكن وفروها نحلق، وإذا صلوا ما نصلي، وإذا زكوا ما نزكي هذا كلام ... وإن خالفونا فنحن على ديننا، وهم على دينهم لَكُمْ دِينُكُمْ وَلِيَ دِينِ [الكافرون: 6].","link":"https://binbaz.org.sa/fatwas/1043/حدود-اللحية-وحكم-حلقها-وتقصيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_61.mp3","categories":["سنن الفطرة"]},{"id":5737,"question":"هل يجوز حلق العارضين؟ وما حكم قص اللحية؟ وهل حكم قصها كحكم حلقها؟","title":"حدود اللحية وحكم حلقها وتقصيرها","answer":"الجواب:  اللحية كرامة من الله للرجل، جعلها الله كرامة للرجل، وجعلها الله ميزة له عن النساء، وجعلها ميزة له عن الكفرة الذين يحلقون لحاهم، فهي زينة الرجال، وهي نور في الوجه، وهي  ميزة لهم عن النساء، فلا يجوز له أن يتعرض لها بحلق، ولا قص، فلا يحلقها ولا يقصها، ولا يحلق العارضين مع الخدين؛ لأن اللحية اسم للشعر الذي ينبت على اللحيين والذقن، فإن الخدين والذقن هما اللحية، شعر اللحية، والذقن التي تحت الشفقة السفلى، هذا هو اللحية، فلا يجوز له قصها ولا حلقها، بل يجب إكرامها وإعفاؤها وتوفيرها؛ لأن النبي ﷺ أمر بإعفاء اللحى، وقص الشوارب، وقال: خالفوا المشركين، قصوا الشوارب وأعفوا اللحى وقال -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس وفي لفظ آخر: وفروا اللحى وأوفى اللحى.  فعلى المسلم أن يوفرها، ويرخيها، ويحرم عليه قصها وحلقها، هذا هو الواجب على المسلم، والمؤمن لا يرضى بأن يشابه أخته وبنته وعمته وأمه، بل ينبغي أن يرخيها، ويوفرها؛ حتى يبقى على سمة الرجال، ووجوه الرجال، وحتى يتباعد عن مشابهة المجوس، والمشركين الذين يحلقونها، ويطيلون السبلات، وهي الشوارب، الشارب يقص ويحفى، واللحية توفر وترخى هذا هو المشروع، هذا هو الواجب، والله المستعان. السؤال: يقولون: إن المشركين الآن الكفار يرخون لحاهم؟ الجواب:  إذا وفروها الحمد لله، عسى الله أن يهديهم، فيسلموا إذا وافقونا في الخير، ما نوافقهم في الشر، إذا وافقنا أرخوا لحاهم، وأسلموا، ودخلوا في دين الله فهذا طيب، لكن وفروها نحلق، وإذا صلوا ما نصلي، وإذا زكوا ما نزكي هذا كلام ... وإن خالفونا فنحن على ديننا، وهم على دينهم لَكُمْ دِينُكُمْ وَلِيَ دِينِ [الكافرون: 6].","link":"https://binbaz.org.sa/fatwas/1043/حدود-اللحية-وحكم-حلقها-وتقصيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_61.mp3","categories":["سنن الفطرة"]},{"id":5953,"question":"أرجو توضيح ما هو الصحيح في السواك للصائم بعد الزوال؟","title":"حكم السواك للصائم بعد الزوال","answer":"الجواب: السواك سنة للجميع، السواك سنة للصائم قبل الزوال، وبعده. أما قول بعض الفقهاء: أنه يكره بعد الزوال فقول ضعيف، النبي ﷺ قال: السواك مطهرة للفم، مرضاة للرب، ولولا أن أشق على أمتي؛ لأمرتهم بالسواك مع كل وضوء.  وقال: عند كل صلاة فهذا يعم صلاة الظهر، وصلاة العصر في حق الصائم، وهو سنة للجميع.","link":"https://binbaz.org.sa/fatwas/1323/حكم-السواك-للصاىم-بعد-الزوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_292.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":5962,"question":"أرجو توضيح ما هو الصحيح في السواك للصائم بعد الزوال؟","title":"حكم السواك للصائم بعد الزوال","answer":"الجواب: السواك سنة للجميع، السواك سنة للصائم قبل الزوال، وبعده. أما قول بعض الفقهاء: أنه يكره بعد الزوال فقول ضعيف، النبي ﷺ قال: السواك مطهرة للفم، مرضاة للرب، ولولا أن أشق على أمتي؛ لأمرتهم بالسواك مع كل وضوء.  وقال: عند كل صلاة فهذا يعم صلاة الظهر، وصلاة العصر في حق الصائم، وهو سنة للجميع.","link":"https://binbaz.org.sa/fatwas/1323/حكم-السواك-للصاىم-بعد-الزوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_292.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":5992,"question":"أنا أعتقد أن المسلمين يريدون الجهاد، ويريدون العلم، ويكرهون الجهل، ويكرهون الوهن، لكن العلماء فيهم تقصير في عدم قول كلمة الحق بكل صراحة، وبكل صدق، ويفتقدون القيادة الصادقة من العلماء، فما رأيكم؟","title":"نصيحة موجهة للعلماء وطلبة العلم للقيام بواجبهم","answer":"الجواب:  هذا قد وقع كثير منه، لا شك أن هذا وقع، كثير من العلماء الآن ليس عندهم العناية التامة بتعليم الناس، وتوجيه الناس إلى الخير. وكما وقع في اليهود، والنصارى ما وقع من انحراف العلماء، وقع في هذه الأمة ما وقع أيضًا من عهد طويل، من انحراف كثير من العلماء، والرضا بالعاجلة، وعدم القيام بالواجب من التعليم، والتوجيه، ولكن هناك بقايا -بحمد الله- يعلمون، ويرشدون.  والعلماء هم ورثة الأنبياء، وهم القادة في كل زمان، ولكننا اليوم في غربة الإسلام، وفي قلة من العلماء، كما قال النبي -عليه الصلاة والسلام-: لا تقوم الساعة، حتى يظهر الجهل، ويقل العلم، ويفشو الزنا، ويشرب الخمر إلى آخره.  وقد وقع هذا الأمر من أزمان متطاولة، فقد قل العلماء، وكثر الجهل، وغلب على أكثر النفوس، تجد البلدان الكثيرة، والقبائل الكثيرة خالية من العلماء، والمتفقهين في دين الله. والعلماء الذين يصح أن يقال علماء: هم الذين تفقهوا في دين الله، وأخذوا علمهم عن كتاب الله، وعن سنة رسوله -عليه الصلاة والسلام- وليس العالم المقلد لفلان، أو فلان الذي يعرف مختصرًا من المختصرات، أو كتابًا من الكتب، فيقلد أربابها، ولا يدري عن كتاب الله، ولا عن سنة رسوله، هذا لا يعد من العلماء بإجماع أهل العلم، وإنما  العالم هو الذي يأخذ علمه عن كتاب الله، وعن سنة رسوله -عليه الصلاة والسلام- وهذا اليوم قليل في الأمصار، والدول، هذا الصنف قليلون جدًا.  وقد ظهر -بحمد الله- حركات في مواطن كثيرة، وبلدان كثيرة إسلامية، تنشد الحق، وتطلب الدليل، وتعنى بالكتاب والسنة، وهذا يبشر بالخير؛ فنسأل الله أن ينمي هذه الحركات الطيبة، وأن يزيدها خيرًا، وأن يبارك في العلماء الموجودين، وأن يرزقهم البصيرة، وأن يعينهم على أداء الواجب، وعلى نشر الحق. وينبغي أن يعلم أنه وإن كان قد وقع التقصير من الكثير من العلماء، وهكذا من الناس، ومن الشعوب، والطلبة، التقصير كثير، فقل من يأتي إلى العالم، ويسأله، ويشجعه على أن يدرس، أو ينشر العالم، فهذا قد يعرض، وهذا قد يعرض.  فالواجب التكاتف، فإن العالم إذا سئل، واتصل به السائلون من طلبة العلم، ومن غيرهم، كان هذا مما يعينه على العناية بالعلم، ومراجعة الآيات، والأحاديث، والاستعداد لإجابة السائلين، ولإظهار العلم، ونشره بين الناس، فإذا غفل غفل هذا، وأقبل هذا على دنياه، وهذا على دنياه، وقل السائلون. فالعالم أيضًا قد يغفل، وقد يعرض، وقد ينشغل بشيء آخر من أمور دنياه، فلا ينبغي للجميع الغفلة عن هذا الأمر، بل يجب على العالم أن يعنى بالقرآن، والحديث، وأن يأخذ علمه منهما، وأن يعنى بذلك، وأن يبذل الكثير من وقته، أو الأغلب من وقته في هذا السبيل العظيم، حتى يكن علمه علمًا شرعيًا نافعًا، ينفع الله به الناس. وعلى المسلمين أن يسألوا، ويتبصروا في دينهم، ويتفقهوا قال الله : فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43] وقال النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة فإذا جاء طالب العلم إلى عالم، ويسأل عالمًا آخر؛ أكد عليه، ويسأل من فوقه، أو جاء العامي يسأل العالم، أو طالب العلم، يريد العلم، يريد الفائدة؛ فله الخير العظيم، وله الفضل الكبير، وقد سعى في طريق إلى الجنة.  كذلك إذا حضر حلقات العلم ليستفيد في شرع الله، وقصده، ولو من بعيد، ولو بأسفار، ولو سافر المسافرات؛ ليحضر حلقات العلم، ويسأل العالم؛ فهذا أيضًا من المهمات، ومن الواجبات عند الحاجة. وكذلك طلبة العلم الذين في المدارس، والمعاهد، والكليات يجب عليهم أن يعنوا بالعلم النافع الحقيقي، الذي يؤخذ من كتاب الله، ومن رسوله -عليه الصلاة والسلامج حتى يكون علمهم علمًا حقيقيًا نافعًا؛ موصلًا إلى الآخرة، وإلى الجنة، والكرامة.","link":"https://binbaz.org.sa/fatwas/1397/نصيحة-موجهة-للعلماء-وطلبة-العلم-للقيام-بواجبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_352.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6010,"question":"ما هي كيفية التفقه في الدين؟ وهل يكفي قراءة المؤلفات، واستماع الإذاعات الدينية، أو لا بد من الالتحاق بالمعاهد، أجيبونا، جزاكم الله خيرًا؟","title":"أسباب وطرق التفقه في دين الله","answer":"الجواب:  التفقه في الدين يكون بأنواع، وأسباب، وطرق، التفقه في الدين هو التفقه في كتاب الله، وفي سنة رسوله -عليه الصلاة والسلام- حتى تعرف ما أوجب الله عليك، وما حرم عليك، وما أباح لك، فتكون على بصيرة في دينك من كتاب الله، وسنة رسوله، سواء كان في بيتك على شيخ من الشيوخ العارفين، أو في بيته هو، أو في المسجد، أو في مدرسة، أو في جبل، أو تحت شجرة في أي مكان. التفقه في دين الله المقصود به هو التفقه في الكتاب، والسنة في أي مكان، وعلى أي عالم ممن  عرف الحق، وهو من أهل العلم، والدين، والإيمان.","link":"https://binbaz.org.sa/fatwas/1394/اسباب-وطرق-التفقه-في-دين-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_350.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6041,"question":"هل هناك دليل، أو شيء يحث على حلق شعر الرأس؟","title":"حكم حلق شعر الرأس والسنة في شعر الإبط","answer":"الجواب: حلق الرأس جائز، النبي ﷺ قال في الرأس: احلقه كله، أو دعه كله لما رأى إنسانًا قد حلق بعض رأسه، وهو القزع، قال: احلقه كله، أو دعه كله والنبي حلق رأسه في الحج -عليه الصلاة والسلام- فالحلق لا بأس به، أو تربيته إذا قوي على تربيته على وجه شرعي؛ للتأسي بالنبي ﷺ لا بأس بذلك، طيب، إذا قوي عليه، واعتنى به، لا لقصد الفساد، والنساء، وأشباه ذلك؛ فلا حرج، وإن حلق؛ فلا بأس.  أما الإبط فالسنة أخذ الإبط، نتفه، هو هذا هو الأفضل، والعانة كذلك تحلق حلقًا، والأظفار تقلم، والشارب يقص، هذا سنة، بل قد يجب إذا طال وجوبًا، النبي ﷺ قال: قصوا الشوارب، وأعفوا اللحى وأمر بنتف الإبط، وحلق العانة، وقلم الأظفار للرجل، والمرأة، هذا عام للرجال، والنساء جميعًا، ومشروع للجميع قلم الأظفار، ونتف الإبط، وحلق العانة، هذا للجميع، وقص الشارب للرجال.","link":"https://binbaz.org.sa/fatwas/1463/حكم-حلق-شعر-الراس-والسنة-في-شعر-الابط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_393.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":6045,"question":"هل قص الأظافر بالليل حرام، أم لا؟","title":"حكم تقليم الأظافر ليلاً","answer":"الجواب: قص الأظافر بالليل، أو بالنهار جائز، في الليل، والنهار مطلقًا، مشروع.","link":"https://binbaz.org.sa/fatwas/1452/حكم-تقليم-الاظافر-ليلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_380.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":6107,"question":"كثيرًا ما يركز المشايخ في دعواهم إلى الله على جانب العقيدة، ومعلوم أن ذلك له أهميته الكبرى، ومكانته العظيمة، إذ أن تأسيس العقيدة هو الركيزة الكبرى للإسلام، ولكن نرجو توجيه العناية بالأخلاق الاجتماعية، ومحاربة الرذائل في بناء العقيدة، فلماذا نرى غالبًا العلماء يهملون هذا كثيرًا؟","title":"أهمية العقيدة والدعوة إليها","answer":"الجواب: على كل حال، المعروف عند العلماء أنهم يعتنون بهذا وهذا، العقيدة مثل ما ذكرت أيها السائل هي: الركيزة، وهي الأساس، ولهذا أغلب أهل العلم في بلدان العالم لا يهتمون بالعقيدة ضد ما قلت، فيتكلمون في الأخلاق، وفي أشياء أخرى في الصلاة، في الزكاة في الأوقات، في الصلاة، في أشياء أخرى، والعقيدة مهملة حتى عبدت بينهم القبور من دون الله، وحتى وقع الشرك بالله بينهم، وهم لا يشعرون. وربما وقع ذات العالم في الشرك بالله؛ لأنه عاش على الشرك مع أبيه، ومع عمه، ومع شيخه، فعاشوا على الشرك لأسباب عدم خوضهم في العقيدة، وعدم عنايتهم بالعقيدة، تجده يدرس، ويعبد غير الله، تجده في المسجد يدرس، ثم يدعو البدوي، ويدعو الحسين، ويدعو عبدالقادر؛ لأنه عاش على هذا هو وأبوه، وجده وأصحابه، هذه من نتائج إهمال العقيدة، وعدم العناية بالعقيدة.  وتجده جهبذًا بصيرًا بأحكام الصلاة، في أحكام الأوقات، في أحكام الإجارة، في الزكاة، في وصايا، في أشياء أخرى؛ لأنه درسها، واعتنى بها، أما العقيدة فلا يعتني بها ولا يعرف ... وإن كان جيدًا فهو يعتني بعقيدة المتكلمين، وما يخوض فيه المتكلمون من جهة الكلام، والعقائد التي ساقها أهل الكلام من الأشعرية، والجهمية، والمعتزلة، وغفل عن العقيدة السلفية التي درج عليها أصحاب الرسول ﷺ ودرج عليها سلفنا الصالح في إثبات الأسماء والصفات، ومن الإيمان بالله، وتوحيد العبادة، وعدم الشرك بالله  والعناية بهذا الأمر. فالحاصل أنه يجب وجوبًا عظيمًا وجوبًا مؤكدًا أن يعتنى بالعقيدة، وليعتني العلماء في إيضاحها للناس من عامة، وخاصة، وأن تكون الدروس غالبًا تعتني بها مع العناية بالأخلاق، والأحكام الأخرى، لا يهمل هذا، ولا هذا، ولكن تكون العناية الكبرى بالعقيدة. وكان الشيخ محمد -رحمه الله- في رسائله يقول لبعض خصومه الذين يكتب إليهم، ويخاصمون في العقيدة، يقول: إني أريد منكم أن تدرسوا العقيدة كما تدرسوا كتاب الأوقاف، يعني كما أنكم تعتنوا بالأوقاف -أوقاف الناس- فأرجو منكم أن تدرسوا العقيدة باب حكم المرتد مثل عنايتكم بكتاب الأوقاف.  فلو أنهم درسوا باب حكم المرتد في كتب الفقه التي ألفها العلماء في كل مذهب، لو درسوا باب حكم المرتد، واعتنوا به لظهر لهم ما هم فيه من الباطل، والشرك، ولكنهم يغفلون عن ذاك الباب؛ لأن السؤال ما يجدون السؤال فيه، ولا عناية به، وتجدهم مشغولين بالأوقاف، وأولياء الأوقاف، كيف ينفذ الوقف؟ كيف تصرف غلة الوقف؟ كيف يفعل بالإجارة؟ كيف يؤجر؟ كيف يفعل بمال اليتيم؟ فاشتغلوا بهذه، وضيعوا العقيدة لعدم عنايتهم بها، ولعدم سؤال العامة عنها؛ فلهذا جمدت، وغفل عنها، وصار الناس في غاية من الشرك بالله، وعبادة القبور، والأولياء، بسبب هذه الغفلة تجد البدوي، وغير البدوي، وفلانًا، وفلانًا، في مصر، والشام، والعراق، وفي كل مكان تجده معبودًا مع الله، والعلماء المعممون يدعون إلى ذلك، ويفعلون ذلك مع العامة.  قد لبسوا هذا الأمر، وضيعوه لعدم عنايتهم به، حتى وقعت العامة في الشرك بأسبابهم، وصاروا يعكفون على القبور، ويدعونها مع الله، وبها يستغيثون، ويسألونها قضاء الحاجات، وشفاء المرض، والنصر على الأعداء، هكذا وقع بين الناس، ومن استنكر هذا، وسافر إلى بلاد أخرى؛ فليمر على قبر البدوي، والحسين، وفلان، وفلان، يجد الناس حوله عاكفين، هذا يقول: يا سيدي فلان المدد، اشف مريضي، انصرني على عدوي، افعل بي، افعل بي، حتى آل بهم الأمر، حتى يسألوهم الأولاد، يسألونهم أن تحمل نساءهم أولادًا، وأن يعطوا كذا، ويعطوا كذا، نسأل الله العافية، نسوا الله فنسيهم، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1521/اهمية-العقيدة-والدعوة-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_451.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6404,"question":"مما يشاع بين طلاب العلم، وخاصة في الكليات، والمؤسسات العلمية قولهم: العلم ذهب مع أهله، وأنه لا يوجد أحد يتعلم في المؤسسات العلمية إلا من أجل الشهادات، والدنيا، فبماذا يرد عليهم؟ وما الحكم إذا اجتمع قصد الدنيا، والشهادة مع نية طلب العلم؛ لنفع نفسه، ومجتمعه؟","title":"ما الرد على أنه لا يوجد أحد يتعلم إلا من أجل الشهادات؟","answer":"الجواب: هذا الكلام ليس بصحيح، ولا ينبغي أن يقال هذا الكلام وأمثاله، ومن قال: هلك الناس فهو أهلكهم. ولكن ينبغي التشجيع والتحريض على طلب العلم والتفرغ لذلك، والصبر والمصابرة على ذلك، وحسن الظن بطلبة العلم إلا من علم منه خلاف ذلك. ولما حضرت المنية معاذا - فيما يذكر - أوصى من حوله بطلب العلم، وقال: «إن العلم والإيمان مكانهما من أرادهما وجدهما» يعني: مكانها في كتاب الله العظيم وسنة رسوله ﷺ الأمين، وإنما العالم يقبض بعلمه، فالعلم يقبض بموت العلماء، لكن لا تزال بحمد الله طائفة على الحق منصورة؛ ولهذا قال عليه الصلاة والسلام: إن الله لا يقبض العلم انتزاعا ينتزعه من العباد، ولكن يقبض العلم بقبض العلماء، حتى إذا لم يبق عالم اتخذ الناس رؤوسا جهالا فسئلوا فأفتوا بغير علم فضلوا وأضلوا رواه البخاري في صحيحه.\nوهذا هو الذي يخاف منه، يخاف أن يتقدم للإفتاء والتعليم الجهلة فيَضلون ويُضلون، وهذا الكلام الذي يقال: ذهب العلم ولم يبق إلا كذا وكذا، يخشى منه التثبيط لبعض الناس، وإن كان الحازم والبصير لا يثبطه ذلك، بل يدفعه إلى طلب العلم حتى يسد الثغرة. والفاهم المخلص، والصادق البصير بمثل هذا الكلام لا يثبطه ذلك، بل يتقدم ويجتهد، ويثابر ويتعلم، ويسارع لشدة الحاجة للعلم، وليسد الثغرة التي زعمها هؤلاء القائلون: إنه لم يبق أحد.\nوالحاصل أنه وإن نقص العلم وذهب أكثر أهله، فإنه ولله الحمد لا تزال طائفة على الحق منصورة كما قال النبي ﷺ: لا تزال طائفة من أمتي على الحق منصورة لا يضرهم من خالفهم ولا من خذلهم حتى يأتي أمر الله.\nفعلينا أن نجتهد في طلب العلم، وأن نشجّع عليه، وأن نحرص على سد الثغرة، والقيام بالواجب في مصرنا وغيره، عملا بالأدلة الشرعية المرغبة في ذلك، وحرصا على نفع المسلمين وتعليمهم، كما ينبغي أن نشجع على الإخلاص والصدق في طلب العلم.\nمن أراد الشهادة ليتقوى بها على تبليغ العلم والدعوة إلى الخير فقد أحسن في ذلك، وإن أراد المال ليتقوى به فلا بأس أن يدرس ليتعلم وينال الشهادة التي يستعين بها على نشر العلم، وأن يقبل الناس منه هذا العلم، وأن يأخذ المال الذي يعينه على ذلك، فإنه لولا الله سبحانه ثم المال لم يستطع الكثير من الناس التعلم وتبليغ الدعوة. فالمال يساعد المسلم على طلب العلم وعلى قضاء حاجته وعلى تبليغه للناس، ولما ولي عمر  أعمالا أعطاه رسول الله ﷺ مالا، قال: أعطه من هو أفقر مني، فقال النبي ﷺ: خذ هذا المال فتموله أو تصدق به، وما جاءك من هذا المال وأنت غير مشرف ولا سائل فخذه، وما لا فلا تتبعه نفسك خرجه مسلم في صحيحه.\nوأعطى النبي ﷺ المؤلفة قلوبهم ورغبهم حتى دخلوا في دين الله أفواجا، ولو كان حراما لم يعطهم، بل أعطاهم قبل الفتح وبعده. وفي يوم الفتح أعطى بعض الناس على مائة من الإبل، وكان يعطي عطاء من لا يخشى الفقر عليه الصلاة والسلام ترغيبا في الإسلام ودعوة إليه. وقد جعل الله سبحانه للمؤلفة قلوبهم حقا في الزكاة، وجعل في بيت المال حقا لهم ولغيرهم من المدرسين والقضاة وغيرهم من المسلمين. والله ولي التوفيق[1].","link":"https://binbaz.org.sa/fatwas/2035/ما-الرد-على-انه-لا-يوجد-احد-يتعلم-الا-من-اجل-الشهادات","audio":"undefined","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6476,"question":"صورة من جريدة من مجلات صفحة 16 وتحت موضوع \"حدث في كلية الشريعة: ملخص ما في الأمر: أن أحد أساتذة كلية الشريعة، وهو الدكتور حسن نيتو، حيث يقول: إن من خالف إجماع الأمة الإسلامية؛ فهو كافر، وأن ابن تيمية أحد علماء الشام قد خالف إجماع الأمة، ولولا أنه لم يمت في السجن؛ لأقيم عليه حد الردة، إذاً نرجو من سماحتكم التعليق على هذا الأمر، أو الرد على من يقول بمثل هذا القول، وذلك في وسائل الإعلام الكويتية، وجزاكم الله خير الجزاء؟","title":"الرد على من قال إن ابن تيمية خالف الإجماع","answer":"الجواب: هذا ما سمعناه، ومن قال هذا: فهو أجهل من حمار أهله، من قال هذا الكلام، سواء حسن، أو غير حسن الدكتور، من قال مثل هذا الكلام؛ فهو أضل من بعير أهله، وبقرة أهله، لا شك أنه قال بغير علم، وقال قولًا فاسدًا ضالًا. فإن ابن تيمية لم يخالف إجماع الأمة، وإنما بين ما يجب على الأمة أن يأخذوا به، وحرر المسائل التي اختلف فيها الناس، وأوضح أحد القولين الراجح من القولين، أو من الأقوال بالدلائل، وليس ممن يخالف إجماع الأمة، بل هو ممن يدعو إلى الخير، وينهى عن الشر، رحمه الله.  ولكنه قد خالف في مسائل جمهور الأمة، والعبرة بالدليل، ولو مع القليل، فإذا كان الأكثرون على قول، والقليل من العلماء على قول، والدليل مع القليل، فالحق مع القليل، الحق مع من معه الدليل، ولو كانوا هم القليل من العلماء، فليس الحق مع الكثيرين، الحق مع من معه الدليل، من قام معه الدليل من كتاب، أو سنة، فهو صاحب الحق، وإن كان القائل بذلك ليس هم الأكثرين، بل هم الأقل.  السؤال:.. في الكويت..؟ الجواب: إن شاء الله نبحث الموضوع، وننظر نبحث الموضوع.  السؤال: يعني الموضوع في كلية الشريعة في الكويت، ليس في المملكة، الحمد لله. الجواب: على كل حال الواجب علاج الموضوع، سواء هنا، أو هناك.","link":"https://binbaz.org.sa/fatwas/2220/الرد-على-من-قال-ان-ابن-تيمية-خالف-الاجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_840.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6501,"question":"ذهبت من بلدي إلى طلب العلم، ولكن والدي ليسوا موافقين ما أعمل، وما هي التوبة؟الشيخ: أعد ذهبت من بلدي إلى طلب العلم، ولكن والدي غير موافقين، فهم طلبوا مني عدم الذهاب، وأنا ذهبت للإفادة؟","title":"حكم السفر لطلب العلم دون موافقة الوالدين","answer":"الجواب: طلب العلم واجب، فإذا كان في بلدك ما عنده علماء يطلبون العلم عليهم؛ فإن طلب العلم واجب، عليه أن يسافر في طلب العلم الشرعي، ولو لم يرض والداه بقدر الحاجة، يسافر بقدر الحاجة، ويتعلم ما لا يسعه جهله من دين، ثم يرجع إلى والديه، ويستسمحهما بالكلام الطيب، والأسلوب الحسن، أو يتوجهون جميعًا إلى بلد العلم إذا استطاع ذلك؛ لأن هذا أمر لازم، طلب العلم واجب.","link":"https://binbaz.org.sa/fatwas/2250/حكم-السفر-لطلب-العلم-دون-موافقة-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_871.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6523,"question":"ذهبت من بلدي إلى طلب العلم، ولكن والدي ليسوا موافقين ما أعمل، وما هي التوبة؟الشيخ: أعد ذهبت من بلدي إلى طلب العلم، ولكن والدي غير موافقين، فهم طلبوا مني عدم الذهاب، وأنا ذهبت للإفادة؟","title":"حكم السفر لطلب العلم دون موافقة الوالدين","answer":"الجواب: طلب العلم واجب، فإذا كان في بلدك ما عنده علماء يطلبون العلم عليهم؛ فإن طلب العلم واجب، عليه أن يسافر في طلب العلم الشرعي، ولو لم يرض والداه بقدر الحاجة، يسافر بقدر الحاجة، ويتعلم ما لا يسعه جهله من دين، ثم يرجع إلى والديه، ويستسمحهما بالكلام الطيب، والأسلوب الحسن، أو يتوجهون جميعًا إلى بلد العلم إذا استطاع ذلك؛ لأن هذا أمر لازم، طلب العلم واجب.","link":"https://binbaz.org.sa/fatwas/2250/حكم-السفر-لطلب-العلم-دون-موافقة-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_871.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6615,"question":"هل على الحلاق الذي يحلق للناس لحاهم إثم، وذنب في ذلك؟ وإذا كان مصدر رزقه هو الحلاقة، فما حكم المال الذي يأخذه، هل هو حرام؟","title":"حكم من يحلق لحية غيره","answer":"الجواب: سمعتم أن حلق اللحية حرام، وأن اللحية ما نبت على الخدين، والذقن، ما نبت على العظم الذي يحاذي شحمة الأذن، هذا حد اللحية، ما فوقه إلى الرأس، وما تحته من اللحية، فاللحية ما نبت على الخدين، والذقن هو اللحية، فالذي يحلق هذا للناس، أو يقصه للناس آثم، وعليه نصيبه من الوزر، وما يأخذه سحت من المال .. حرام منكر، لأن الله -جل وعلا- يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] ومن أعان على المحرم؛ فقد شارك في المحرم، ولهذا لعن النبي ﷺ آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء لماذا لعن الكاتب؟ لأنه أعان على الإثم، ولعن الشاهدين؟ لأنهما أعانا على الإثم، ولعن من أكل الربا كذلك.  فالمقصود: أن الإعانة على ما حرم الله محرمة، وإذا أخذ عنها مالًا؛ صار كسبًا محرمًا، صار سحتًا، نسأل الله السلامة. وهكذا بيع الدخان، والخمور والمسكرات، وثمنها، كله حرام، الرسول ﷺ لعن الخمر، وشاربها، وساقيها، وعاصرها، ومعتصرها، وحاملها، والمحمولة إليه، وبائعها، ومشتريها، وآكل ثمنها كلهم ملعونون، نعوذ بالله، نسأل الله العافية. ويلتحق بهذا ما حرم الله  من التدخين، ومن الحشيشة التي تسكر المعروفة، والأفيون، كل ما هو مسكر، كله داخل في التحريم، فبيعه حرام، وثمنه حرام، والتعاون في هذا حرام، وهكذا حلق اللحى حرام، وأخذ الأجرة عليها حرام، وباذلها قد فعل محرمًا، وآخذها فعل محرمًا، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2446/حكم-من-يحلق-لحية-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_973.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":6795,"question":"ما هو حكم عدم إطلاق اللحية في بلد يضطهد كل من أطلق لحيته؛ بحجة أنه من المتطرفين، مما يجعل كل من يطلق لحيته هدفًا سهلًا لكل باضطهاده، وتعذيبه؟","title":"حكم حلق اللحية بسبب الضغط والاضطهاد","answer":"الجواب:\nهذه أوهام النفوس، وليس له أن يحلق لحيته لأجل خوف الحكام، بل عليه أن يتقي الله ويبقي لحيته ويعفيها، وله الأسوة، والعافية إذا استقام، وصدق، لا يتعرض لهم في شؤونهم، في شأنه، وبيعه، وشرائه، وطاعته لربه، وسوف لا يرى إلا الخير. وإن قهروه، وحلقوها هم لا يضره ذلك، يكون الإثم عليهم، أما لو قال: أحلقها أنا؛ لئلا يأخذوني، هذا من وساوس الشيطان، ومن ضلال الشيطان -نعوذ بالله- ومن طاعة الشيطان.","link":"https://binbaz.org.sa/fatwas/2672/حكم-حلق-اللحية-بسبب-الضغط-والاضطهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1169.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":6806,"question":"ما رأيكم في قراءة الكتب التي تعالج مشاكل هذا العصر، والفتن، والمذاهب المعاصرة، والمذاهب الهدامة، مثل القومية، والشيوعية، وغيرها، والكتب مثل كتب سيد قطب، والمودودي، ومحمد قطب، ويوسف العظمة، والندوي؟","title":"حكم القراءة في الكتب التي تعالج مشاكل العصر","answer":"الجواب: طيب، إذا قرأها ليستعين بما فيها من العلم إذا قرأ ما تيسر منها، لكن لا يغفل عن كتب السلف الصالح، يعتني بكتب السلف الصالح مثل: تفسير ابن جرير، والبغوي، وابن كثير، ممن ينقلون عن السلف الصالح، وينقلون علومهم، ويعتنون بها، ويستعين بالكتب الجديدة التي ألفها أهل العلم، يستعين بها حتى يستفيد من علمهم، ومن أساليبهم، ومن طرقهم في الدعوة إلى الله، يستفيد من ذلك، فيضم العلم الجديد إلى العلم القديم.","link":"https://binbaz.org.sa/fatwas/2688/حكم-القراءة-في-الكتب-التي-تعالج-مشاكل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1186.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6818,"question":"ما هي أنسب، وأنفع الطرق -في رأيكم- لتحصيل العلم في هذا الزمان؟ هل هو بالاتجاه إلى حلقات المشايخ في المساجد، أم بالاتجاه إلى الجامعات الإسلامية، أم إلى قراءة الكتب، وسؤال أهل العلم عما استشكل؟","title":"أنفع الطرق لتحصيل العلم","answer":"الجواب: هذا وهذا وهذا، يدرس في الجامعات، وفي المعاهد الدينية، ويعتني بالدراسة؛ حتى يستفيد شهادات تنفعه، وعلوم تنفعه، فالشهادات اليوم تنفع، ويستعان بها على تبليغ الدين، وعلى ما ينفع المسلمين. فيدرس في الجامعات، وفي المعاهد العلمية، ويأخذ الشهادات، ومع ذلك يحضر حلقات العلم حسب الإمكان، ويطالع الكتب الدينية، ويسأل أهل العلم، فيجمع بين هذا، وهذا، هكذا كان السلف، هكذا في الزمن الأول، وفي الزمن الأخير. أهل العلم هكذا يدرسون في المدارس، ويدرسون في حلقات العلم، ويدرسون، ويتذاكرون فيما بينهم، ويطالعون الكتب النافعة، ويقرؤون كتب التفسير، ويعتنون بالقرآن العظيم دراسة، وتدبرًا وتعقلًا، فيجمعون بين هذه الطرق كلها، هكذا طالب العلم لا يشغله شاغل، فهو مع الدارسين في المدارس، وفي الجامعات، وهو مع حلقات العلم، وهو مع المطالعة، والمذاكرة، والعناية بالقرآن، والسنة، والمذاكرة مع الزملاء، ومع العلماء، حتى يستفيد علمًا إلى علمه، وبصيرة إلى بصيرته.","link":"https://binbaz.org.sa/fatwas/2687/انفع-الطرق-لتحصيل-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1185.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6824,"question":"ما رأيكم في قراءة الكتب التي تعالج مشاكل هذا العصر، والفتن، والمذاهب المعاصرة، والمذاهب الهدامة، مثل القومية، والشيوعية، وغيرها، والكتب مثل كتب سيد قطب، والمودودي، ومحمد قطب، ويوسف العظمة، والندوي؟","title":"حكم القراءة في الكتب التي تعالج مشاكل العصر","answer":"الجواب: طيب، إذا قرأها ليستعين بما فيها من العلم إذا قرأ ما تيسر منها، لكن لا يغفل عن كتب السلف الصالح، يعتني بكتب السلف الصالح مثل: تفسير ابن جرير، والبغوي، وابن كثير، ممن ينقلون عن السلف الصالح، وينقلون علومهم، ويعتنون بها، ويستعين بالكتب الجديدة التي ألفها أهل العلم، يستعين بها حتى يستفيد من علمهم، ومن أساليبهم، ومن طرقهم في الدعوة إلى الله، يستفيد من ذلك، فيضم العلم الجديد إلى العلم القديم.","link":"https://binbaz.org.sa/fatwas/2688/حكم-القراءة-في-الكتب-التي-تعالج-مشاكل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1186.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6868,"question":"سمعنا من بعض مشايخنا الفضلاء القول بعدم صحة كتاب انتشر في أوساط الناس على مختلف طبقاته، وهو كتاب: الدعاء المستجاب لمؤلفه أحمد عبدالجواد، وتحذير من قراءته، ولكن المشاهدة في الواقع زيادة انتشاره، وكثرة وجوده في دار الكتب، والمكتبات؛ لذا نود منكم الإيضاح لنا عن أمر هذا الكتاب، وإذا كان الأمر كما سمعنا، فلماذا لا يعمل على جمعه من المكتبات، والأسواق، وتحذير الناس منه، والله يحفظكم ويرعاكم؟","title":"هل كتاب الدعاء المستجاب أحاديثه صحيحة؟","answer":"الجواب: هذا قد اطلعنا عليه، وهو كتاب ردئ، وفيه أحاديث موضوعة، وفيه بدع كثيرة، ومثل هذا صدر من دار الإفتاء لولاة الأمور بيان أنه كتاب غير صالح، وأن الواجب منعه، وعدم دخوله إلى البلاد، وعدم بيعه في المكتبات، هذا هو الذي صدر منا من دار الإفتاء لبيان ما فيه من الباطل، وأنه يجب أن يصادر، وأن يمنع من البلاد. وهناك كتب أخرى قد صدر من دار الإفتاء بيان أنها ضارة، وأن الواجب مصادرتها، وعدم دخولها البلاد، ومع هذا تدخل لأسباب كثيرة.  فنسأل الله أن يوفق ولاة الأمور للعناية بهذا الأمر، وأن يهاجموا هذه المكتبات مرة بعد مرة، وتارة بعد تارة؛ حتى يعرفوا ما فيها من الباطل، وحتى يصادروا ما فيها من الممنوعات، وحتى يعاقبوا المتساهلين، وسوف نفعل إن شاء الله ما نستطيع من المتابعة لهذا الأمر.","link":"https://binbaz.org.sa/fatwas/2756/هل-كتاب-الدعاء-المستجاب-احاديثه-صحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1248.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6874,"question":"ما رأي سماحتكم في الكتب التالية : تحفة العروس، وكتب الشيخ الندوي، والمودودي، ومحمد قطب وكتاب لطائف المعارف، لابن رجب الحنبلي؟","title":"تقييم كتب الندوي والمودودي ومحمد قطب","answer":"الجواب: كل كتاب في الغالب -ما عدا كتاب ربنا - لا يخلو من شيء، لا يخلو من أشياء تنتقد عليه، وفيه بعض الأغلاط، وطالب العلم لا يأخذ الكتاب مطلقًا، بل يقبل منه ما وافق الحق، ويترك ما خالف الحق.","link":"https://binbaz.org.sa/fatwas/2755/تقييم-كتب-الندوي-والمودودي-ومحمد-قطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1247.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6903,"question":"أنا شاب في متقبل دراستي الجامعية، واتجهت لمعرفة آيات الله في البحار، والجبال، وفي الكواكب، وفي النفس البشرية، هل يجوز أن أتعلم هذا وأنا لم أتعلم بشكل جيد باقي العلوم الشرعية؟ هل اتجاهي هذا جائز، أم أتركه، أفيدونا أفادكم الله؟","title":"حكم الاقتصار على معرفة الآيات الكونية دون الإلمام بالعلوم الشرعية","answer":"الجواب: عليك بالعناية بالعلم الشرعي حتى تعرف أحكام الله، وما أراده الله منك، وما حرم الله عليك، وهذه الأمور تدرك بأدنى عمل، وأنت تدرس تنظر في آيات الله، وأنت تدرس في ليلك ونهارك، آيات الله بارزة: النجوم، الشمس والقمر، والسماء، والأرض كلها بارزة تنظرها، وتراها، وأنت في دراستك وَفِي الْأَرْضِ آيَاتٌ لِلْمُوقِنِينَ [الذاريات:20]، إِنَّ فِي اخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَمَا خَلَقَ اللَّهُ فِي السَّمَاوَاتِ وَالْأَرْضِ لَآيَاتٍ لِقَوْمٍ يَتَّقُونَ [يونس:6]. المقصود: أن الآيات واضحة، وبينة لمن أرادها، ولا تمنعك من الدراسة التي أنت بها، أهم دراسة العلوم الشرعية، والإقبال عليها، والحرص عليها، ومع ذلك أنت تفكر في هذه الأمور التي تنفعك، وتزيدك إيمانًا بالله، وأنه الحق العظيم، وأنه الخلاق العليم، وأنه المستحق لأن يعبد وحده ويطاع أمره، وينتهى عن نهيه .","link":"https://binbaz.org.sa/fatwas/2832/حكم-الاقتصار-على-معرفة-الايات-الكونية-دون-الالمام-بالعلوم-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1280.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6914,"question":"نحيطكم علمًا بأنه قد ظهر كتاب في معرض الكتاب الواقع في وحدة القادسية التابعة للإسكان الجامعي، في جامعة الإمام، وهذا الكتاب اسمه: \"الغيث المسجم في شرح لامية العجم\" لابن إيدك الصفدي، وهذا الكتاب يذكر فيه مؤلفه أبياتًا، وحكايات في أخبار اللواط، ومتعاطيه، وفي هذا الكتاب كثير من المفاسد، ويجترئ على دعوة صريحة إلى اللواط، وترغيب الناس فيه، وأنت تعلم أيها الشيخ أن هذا قد توعد الله فيه قومًا جعل أعلى ديارهم أسفلها، وإن كان هذا حاصل، فما معنى وجود هذا الكتاب الداعي للواط في بلد التوحيد، نرجو من سماحتكم، وهذا الكتاب مكون من جزئين، والذي ذكرناه عنه موجود في أول الجزء الثاني، وأوسطه تحت عنوان الدبيب، وتحت عنوان حكاية العمياء؟","title":"التحذير من كتاب (الغيث المسجم في شرح لامية العجم)","answer":"الجواب:  نسأل الله العافية، قاتل الله من فعل الشر، أو من دعا إليه، إن شاء الله يعالج الموضوع، وإن شاء الله يمنع، نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/2839/التحذير-من-كتاب-الغيث-المسجم-في-شرح-لامية-العجم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1287.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6963,"question":"نرى بعضًا من المجالس يحضرها بعض من إخواننا طلاب العلم، لكنهم لا ينتهزون فرصة مجلسهم، ويذكرونهم بالله، بل ينتهزون معهم في خوضهم فيما لا فائدة فيه، فما هي نصيحة سماحتكم لهؤلاء ولأمثالهم؟","title":"توجيه طلبة العلم بعمارة المجالس بالذكر والعلم","answer":"الجواب: نصيحتي لكل طالب علم أن ينتهز الفرص، فإذا كان في أي مجلس يأمرهم بذكر الله، بقراءة القرآن، بقراءة الحديث الشريف؛ حتى ينتفع المجلس، حتى يكون وجوده نافعًا للمجلس، لا يشاركهم في الغيبة، والنميمة، والسواليف التي لا فائدة فيها، بل متى وجد طالب العلم يعمر المجلس إما بقراءة القرآن، والكلام على ما تيسر من الآيات، وإلا بقراءة الأحاديث، مثل رياض الصالحين، وغيره؛ حتى تكون الفائدة للجميع، وحتى يكون المجلس نافعًا من مجالس الآخرة.  وإذا كان  ولا بد من حديث؛ فليكن حديثًا قليلًا فيما أباح الله، لا في الغيبة، والنميمة، ونحوها، بل في الحاجات العادية التي ليس فيها محذور، حتى يعطيهم بعض الفرصة لأحاديثهم التي يريدونها، ولكن مع هذا يعمر الوقت بطاعة الله، وبذكر الله، وبالنصيحة، وبالقراءة، فيكون الوقت مشتركًا بعضه للنصيحة، وبعضه لقراءة القرآن، أو الحديث، وبعضه لحاجاتهم العادية، التي ليس فيها محذور شرعًا؛ حتى لا يملوا. السؤال: الذكر .. أن يسمع الناس على التسبيح، والتحميد، والتكبير؟ الجواب: هذا منها، إن جلس في المجلس قبل الصلاة؛ يذكر الله، أو يقرأ القرآن، ويذكر الله في نفسه، ويسبح، ويهلل هذه من.. أو جلسوا في أي مكان يذكرون الله، ويتباحثون في طاعة الله، حلقة أو اثنين، أو ثلاثة، يتباحثون، يتذاكرون فيما يجب عليهم، فيما حرم الله عليهم، فيما أعطاهم الله من الأرزاق، والخيرات، وخشية الله، هل أدوا حق الله. كما كان الصحابة يفعلون شيئًا من هذا؟! يذكرون حالهم في الجاهلية وما كانوا عليه، وما هداهم الله للإسلام، وهكذا المؤمنون إذا اجتمعوا يتذاكرون في أي مجلس.","link":"https://binbaz.org.sa/fatwas/2896/توجيه-طلبة-العلم-بعمارة-المجالس-بالذكر-والعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1344.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6969,"question":"ما حكم الذي يحلق لحيته بقصد مساواتها؛ لأن بعض وجهه فيه شعر كثيف والبعض الآخر يكاد يخلو من الشعر؟","title":"حكم تخفيف اللحية وتسويتها","answer":"الجواب:\n\nبسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، أما بعد:\n\nفقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين وقال -عليه الصلاة والسلام-: جزوا الشوارب وأرخوا اللحى خالفوا المجوس.\n\nفأمر بجز الشوارب، وقصها، وأمر بإعفاء اللحى، وتوفيرها، وإرخائها -عليه الصلاة والسلام- فهذا هو الواجب على المؤمن أن يعفي اللحية، ويرخيها ويوفرها، وألا يتعرض لها بشيء من القص، والتسوية، بل يتركها، ويعفيها، ويرخيها كما أمره النبي الكريم -عليه الصلاة والسلام-. \n\nأما الشوارب فالواجب قصها، وعدم إطالتها.","link":"https://binbaz.org.sa/fatwas/2903/حكم-تخفيف-اللحية-وتسويتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1351.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6979,"question":"كتاب منتشر في الأسواق عند الكثير من الشباب، واسم هذا الكتاب هو \"أنت تسأل والإسلام يجيب\" الذي ألفه محمد متولي الشعراوي، فما مدى صلاحية هذا الكتاب من عدمه؟","title":"تقييم كتاب (أنت تسأل والإسلام يجيب)","answer":"الجواب: هذا اطلعنا عليه، وفيه أجوبة جيدة، وفيه غلط فيما يتعلق بأن الرسول ﷺ خلق من النور، وأنه خلق من نور الله، هذا غلط، بناه على حديث باطل موضوع لا أصل له، فغلط فيه -عفا الله عنا وعنه- ولا بد أن ينبه عليه -إن شاء الله- اطلعت عليه منذ أيام؛ لأن بعض الناس قد يغلط في هذا، ويوجد من بعض الخطباء، وبعض الناس يتكلمون في هذا، ويقولون: إن محمدًا خلق من نور الله، وبعضهم يقول: خلق من نور العرش، كل هذا كلام باطل، لا أساس له، كله باطل، محمد ﷺ خلق من ماء أبيه وأمه، مثل بقية الناس، خلق من ماء عبدالله بن عبدالمطلب، ومن ماء آمنة، فالله خلقه مثل ما خلق بقية البشر كما قال تعالى: قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَى إِلَيَّ [الكهف:110] فهو خلق كما خلق بنو آدم جميعًا يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى [الحجرات:13] ما عدا آدم خلقه الله من الطين، وما عدا عيسى خلقه الله من أنثى بلا ذكر، والبقية من ذكر، وأنثى. قال -جل وعلا-: الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ وَبَدَأَ خَلْقَ الْإِنْسَانِ مِنْ طِينٍ ۝ ثُمَّ جَعَلَ نَسْلَهُ مِنْ سُلَالَةٍ مِنْ مَاءٍ مَهِينٍ [السجدة:7-8] فنسل آدم كلهم من ماء مهين، ومحمد ﷺ وبقية الرسل كلهم من نسل آدم -عليه الصلاة والسلام- فهذا هو الحق الذي لا ريب فيه، أما ما يروى عن النبي -عليه السلام- أنه قال: \"إن النبي خلق من نور الله\" فهذا خبر باطل، لا أساس له، بل هو مكذوب على النبي ﷺ وليس له صحة، فينبغي أن يعلم هذا، ويكون على البال؛ لأن هذا من الأخطاء التي سارت على ألسنة بعض الناس -نسأل الله السلامة- يريدون بها أن يرفعوا شأن النبي ﷺ والله قد رفعه بدون كذبهم، الله قد رفعه، ورفع شأنه، وجعله خير البشر، وأفضل عباد الله، ولا حاجة إلى الكذب.","link":"https://binbaz.org.sa/fatwas/2915/تقييم-كتاب-انت-تسال-والاسلام-يجيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1363.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":6985,"question":"نرى بعضًا من المجالس يحضرها بعض من إخواننا طلاب العلم، لكنهم لا ينتهزون فرصة مجلسهم، ويذكرونهم بالله، بل ينتهزون معهم في خوضهم فيما لا فائدة فيه، فما هي نصيحة سماحتكم لهؤلاء ولأمثالهم؟","title":"توجيه طلبة العلم بعمارة المجالس بالذكر والعلم","answer":"الجواب: نصيحتي لكل طالب علم أن ينتهز الفرص، فإذا كان في أي مجلس يأمرهم بذكر الله، بقراءة القرآن، بقراءة الحديث الشريف؛ حتى ينتفع المجلس، حتى يكون وجوده نافعًا للمجلس، لا يشاركهم في الغيبة، والنميمة، والسواليف التي لا فائدة فيها، بل متى وجد طالب العلم يعمر المجلس إما بقراءة القرآن، والكلام على ما تيسر من الآيات، وإلا بقراءة الأحاديث، مثل رياض الصالحين، وغيره؛ حتى تكون الفائدة للجميع، وحتى يكون المجلس نافعًا من مجالس الآخرة.  وإذا كان  ولا بد من حديث؛ فليكن حديثًا قليلًا فيما أباح الله، لا في الغيبة، والنميمة، ونحوها، بل في الحاجات العادية التي ليس فيها محذور، حتى يعطيهم بعض الفرصة لأحاديثهم التي يريدونها، ولكن مع هذا يعمر الوقت بطاعة الله، وبذكر الله، وبالنصيحة، وبالقراءة، فيكون الوقت مشتركًا بعضه للنصيحة، وبعضه لقراءة القرآن، أو الحديث، وبعضه لحاجاتهم العادية، التي ليس فيها محذور شرعًا؛ حتى لا يملوا. السؤال: الذكر .. أن يسمع الناس على التسبيح، والتحميد، والتكبير؟ الجواب: هذا منها، إن جلس في المجلس قبل الصلاة؛ يذكر الله، أو يقرأ القرآن، ويذكر الله في نفسه، ويسبح، ويهلل هذه من.. أو جلسوا في أي مكان يذكرون الله، ويتباحثون في طاعة الله، حلقة أو اثنين، أو ثلاثة، يتباحثون، يتذاكرون فيما يجب عليهم، فيما حرم الله عليهم، فيما أعطاهم الله من الأرزاق، والخيرات، وخشية الله، هل أدوا حق الله. كما كان الصحابة يفعلون شيئًا من هذا؟! يذكرون حالهم في الجاهلية وما كانوا عليه، وما هداهم الله للإسلام، وهكذا المؤمنون إذا اجتمعوا يتذاكرون في أي مجلس.","link":"https://binbaz.org.sa/fatwas/2896/توجيه-طلبة-العلم-بعمارة-المجالس-بالذكر-والعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1344.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":7188,"question":"إذا أراد الإنسان أن يقرأ بعض الكتب، ويريد منها الفائدة، قد يقرأ هذا الكتاب حول شيء ثلاث ساعات، أو أكثر، وخلص، ولم يفهم مما قرأ شيئًا، هذه تكون عبادة، أم ضياع للوقت؟ أفيدونا جزاكم الله خيرًا.","title":"لو قرأ كتابا ولم يفهم، هل تكون عبادة، أم ضياعًا للوقت؟","answer":"الجواب:\n\nعلى طالب العلم، وعلى طالب الحق أن يلتمس الحق من طرقه، فأعظم طريق، وأفضل طريق، وأكبر طريق، وأنفع طريق طريق من على كتاب الله القرآن، هذا أعظم شيء، كثير من الناس إذا قلت الكتاب والسنة ما عنده حماس، يدور شيئًا آخر، أعظم طريق، وأعظم سبيل، وأفضل طريق، وأنجح طريق كتاب الله العظيم، ثم سنة الرسول المصطفى -عليه الصلاة والسلام- هذه هي الطرق، هذان الطريقان.\n\nفالمؤمن يقبل على القرآن، يكثر من تلاوته، يتدبر معانيه .. لماذا أنزل إلا لك؟ حتى تستفيد، ما أنزله الله للبهائم، ولا للجمادات، أنزله لك، للثقلين، للجن والإنس؛ ليتفقهوا، ويتعلموا يقول سبحانه: كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ [ص:29] يعني محمد ﷺ إليك يعني وإلى أمتك، أنزل إليه لينتفع به هو وأمته كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ [ص:29].\n\nويقول سبحانه: أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ [محمد:24] من هم؟ أنت، الجن والإنس هم الذين يتدبرون، ما هو البهائم أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، ويقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]. \n\nفعليك يا أخي أن تقبل على القرآن، وأن تكثر من تلاوته، وأن تدبر معانيه وتقف عند الآيات، يقول: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] ما معنى يهدي للتي هي أقوم؟ يعني يدل على الناس على الطريقة التي هي أقوم يرشدهم، فالتمس من هذا الكتاب الهداية، وسل ربك أن يفقهك، وأن يعينك، ويمنح قلبك الفهم الصحيح، ما أنزل عبث قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ [ص:29]. \n\nفعليك بالتدبر، والتعقل، تقف عند الآيات، تستفيد منها، تعرف مراد الله منها، وإذا أشكل عليك عندك كتب التفسير؛ راجع كتب التفسير: ابن جرير، ابن كثير، البغوي، الشوكاني، القرطبي، غيرهم، تنظر ومن أنفعها وأحسنها: ابن جرير، وابن كثير، والبغوي، هذه الكتب ميسرة بحمد الله، موجودة، تراجع كلام أهل العلم عليها تستفيد.\n\nكذلك أحاديث الرسول ﷺ تراجعها، تستفيد منها، عندك إن كنت طالب علم، عندك البخاري، عندك مسلم، عندك مختصرات: مثل المنتقى لابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للحافظ عبدالغني، هذه مختصرات تفيدك تأملها، وانظر ما يتعلق بالصلاة في أبواب الصلاة، ما يتعلق بالزكاة في أبواب الزكاة، ما يتعلق بالتوحيد في أبواب التوحيد، إلى آخره، ثم تسأل أهل العلم.\n\nأما الكتب المجهولة، كتب لا تدري عن حالها، تضيع فيها أوقاتك لا، لا تضيع أوقاتك في كتب ما تدري عنها، دع الأوقات تروح في كتب معلومة للفائدة، عليك بالكتب المعروفة التي فيها الفائدة والخير، أعظمها الكتاب العزيز القرآن، ثم كتب السنة البخاري ومسلم، المختصرات من ذلك: المنتقى، بلوغ المرام، عمدة الحديث، كتاب أبي داود، كتاب الترمذي، سنن النسائي، ابن ماجه، مسند أحمد، إذا كنت طالب علمن وإذا كنت عاميًّا فاسأل أهل العلم، أكثر من القرآن وتدبر القرآن لعلك تستفيد، واسأل أهل العلم عما أشكل عليك.\n\nأما تطلب كتبًا جدت بين الناس، ما تدري ما حالها تضيع أوقاتك فيها لا، أما إذا كانت كتبًا طيبة أثنى عليها العلماء، وأرشدوك إليها؛ فلا بأس أن تجعل لها وقتًا، فتأخذ منها ما وافق الكتاب والسنة، وتحمد الله على ذلك، وما خالف الكتاب والسنة تدعه، فبعض الكتب تفيد، ترشد إلى الكتاب والسنة، تعين على فهم الكتاب والسنة، تعين على فهم الأحاديث الصحيحة والضعيفة، لا بأس.\n\nلكن بعض الناس يضيع أوقاته في مجلات، في جرائد يومية، في كتب لا قيمة لها، حتى أهلها لا يعرفون بالفضل، ولا بالعلم، تذهب أوقاته ليلًا ونهارًا في مجلة من أولها إلى آخرها، في خرافات، وضلالات، أو أشياء لا قيمة لها، أو في كتاب مجهول، أو كتاب ضال مضل، أو في غير ذلك، وعنده كتاب الله فيه الهدى والنور، وعنده سنة الرسول فيها الهدى والنور، عنده كلام أهل العلم المعروفين بالهدى والعلم، يتركهما جانبًا، هذا من طرق الضلال، هذا من العمى فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَكِنْ تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ [الحج:46].\n\nالسؤال:...؟\n\nالجواب: يعني إذا كان طالب علم؛ يكفي، إذا كان ما هو طالب علم؛ لا يقرأ، لكن إذا كان طالب علم، ينتسب إلى العلم، يقرأ ويستفيد من قول النبي ﷺ ويستفيد من كلام الله -جل وعلا- وإذا أشكل عليه شيء؛ يطالع، ما معنى الآية في تفسير ابن كثير، في الجلالين، في البغوي، في ابن جرير، في الشوكاني، ويسأل إخوانه الزملاء الطيبين، يتذاكر معهم، لا يحقرهم، قد يكون زميل له أفضل من شيخ، قد يكون زميل جيد يتفاهم معك أكثر من شيخ، قد لا يعطيك إلا كلمة، أو كلمتين، تفاهم مع الزملاء الطيبين، ومع أستاذك الذي تدرس عليه الطيب، تخير من الأساتذة أطيبهم وأنفعهم وأغيرهم لله وأكثرهم علمًا؛ حتى تستفيد.\n\nالسؤال: يقول هل يؤجر حتى ولو ما استفاد منها إن قرأها؟\n\nالجواب: يؤجر يؤجر، لكن ينبغي له أن يقرأ حسب الاستفادة، إذا أشكل عليه لا يقف عند الجهل، يراجع الكتاب، يراجع التفسير، يراجع زملاءه، يتعاونون، يراجع الأساتذة، لا يرضى بالجهالة التي لم يفهمها، أقول لا يرضى بهذا، يعني يستفيد إذا جهل شيئًا وهو يهمه، يراجع التفسير، يراجع أهل العلم..","link":"https://binbaz.org.sa/fatwas/3239/لو-قرا-كتابا-ولم-يفهم-هل-تكون-عبادة-ام-ضياعا-للوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1580.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":7428,"question":"الحصون المنيعة جمعها محمد علوي المالكي ...؟","title":"تقويم كتاب الحصون المنيعة لمحمد علوي المالكي","answer":"الجواب:  لا، هذه الحصون المنيعة فيها أغلاط، فيها بعض البدع، وكتب العلوي هذا مبتلى بشر كثير من البدع، ومبتلي بأشياء كثيرة من الشرك -نسأل الله العافية- وهو معروف في مكة، وقد نبهه العلماء على أخطائه وأغلاطه، ولكنه أصر على باطله، ونسأل الله أن يهديه ويرده إلى الصواب، فله مؤلفات فيها شر كثير، له الذخائر المحمدية فيها شركات وبدع كبيرة، وله كتاب المفاهيم وفيه أغلاط كثيرة.  فالمقصود: أن الرجل لا يعتمد، محمد بن علوي المالكي لا يعتمد عليه في كتبه؛ لأنه رجل عنده تخريف، وعنده انحراف في العقيدة -نسأل الله لنا وله الهداية- فلا يجوز الاعتماد على كتبه ولا على فتاويه حتى يرجع إلى الصواب، ويعلن توبته، ويعدل ما كتبه من الباطل -نسأل الله لنا وله الهداية-.","link":"https://binbaz.org.sa/fatwas/3513/تقويم-كتاب-الحصون-المنيعة-لمحمد-علوي-المالكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1817.mp3","categories":["سنن الفطرة","العالم والمتعلم"]},{"id":7559,"question":"سؤاله الرابع يقول: الأخذ من اللحية هل يجوز أم لا؟","title":"حكم أخذ شيء من اللحية","answer":"الجواب: اللحية الواجب إعفاؤها وإرخاؤها وتوفيرها، هذا الواجب، وليس لأحد من الناس الأخذ منها ولا حلقها ولا تقصيرها، بل يجب إعفاؤها وتوفيرها وإرخاؤها، عملاً بقول النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وعملاً بقوله ﷺ: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، فالرسول ﷺ أمر بإرخائها وتوفيرها وإعفائها، فدل ذلك على وجوب هذا الأمر، وأن الواجب على المسلمين طاعة النبي ﷺ في ذلك، وأن يعفوا اللحى ويوفروها ويرخوها، ولا يعرضوها لقص ولا حلق.\nأما ما يروى عن أبي هريرة  عند الترمذي: أن النبي ﷺ كان يأخذ من لحيته من طولها وعرضها هذا رواه الترمذي، وهو حديث باطل عند أهل العلم ليس بصحيح؛ لأن في إسناده عمر بن هارون البلخي وهو متهم بالكذب، فلا يجوز أن يعتمد عليه، وإن كان رواه الترمذي ، فـالترمذي قد يروي أحاديث غير صحيحة، ومنها هذا الحديث وهو: أن النبي ﷺ كان يأخذ من لحيته من طولها وعرضها هذا خبر باطل لا صحة له، وقد يتعلق به من لا يعرف الأحاديث. فينبغي للمسلم التنبه لهذا، وأن هذا الحديث عند أهل العلم ليس بصحيح، وإنما المحفوظ عنه ﷺ الأمر بإعفاء اللحى وتوفيرها وإرخائها، كما في الصحيحين من حديث ابن عمر، وفي صحيح مسلم من حديث أبي هريرة رضي الله تعالى عنهما في أحاديث أخرى. نعم.","link":"https://binbaz.org.sa/fatwas/4563/حكم-اخذ-شيء-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01404.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":7569,"question":"طيب وبالنسبة للملابس الشفافة؟","title":"حكم لبس الملابس الشفافة أمام المحارم","answer":"الجواب: لا ما تجوز الشفافة، الشفافة خطيرة قد تبدي العورة، لكن إذا كان يعني شفافة في الذراع فهذا سهل، إذا كان البدن مستورا، فينبغي أن تكون الملابس ساترة صفيقة، لا تبين ما وراءها من حسن اللحم، وظهور اللحم من حمرة وبياض ونحو ذلك، بل تكون ساترة لهذا الشيء، تكون تحت الثوب الخفيف مثل الفنيلة التي تعين على ذلك وأشباه ذلك، المقصود أن الشفافة كالعارية، الشفافة من جنس العارية، فينبغي التحرز من هذا الشيء وعدم التساهل في هذا الشيء.","link":"https://binbaz.org.sa/fatwas/4575/حكم-لبس-الملابس-الشفافة-امام-المحارم ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01605.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":7605,"question":"هذه الرسالة تتضمن بعض الأسئلة التي بعث بها عبد الوهاب بن عمر المريح ، يقول في رسالته: ما حكم حلق اللحى، وإطالة الإزار، والتكبر على الغير من المسلمين؟","title":"حكم حلق اللحى وإطالة الإزار والتكبر على الغير","answer":"الجواب: حلق اللحى محرم ومنكر ومخالف لسيرة النبي ﷺ وأوامره، وقد صح عن رسول الله عليه الصلاة والسلام أنه نهى عن ذلك فقال: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين، وقال: جزوا الشوارب وأرخوا اللحى، خالفوا المجوس هكذا جاء عنه عليه الصلاة والسلام في الصحيحين من حديث ابن عمر رضي الله تعالى عنهما أن النبي ﷺ أمر بإعفاء اللحى وقص الشوارب فقال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وفي صحيح مسلم عن أبي هريرة  عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، فأنت يا أخي مأمور باتباع نبيك عليه الصلاة والسلام وطاعته والسير على منهاجه، كما قال عز وجل: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، وقال جل وعلا: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، وقال: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59]، وقال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، فالخير كله في طاعته؛ لأن طاعته طاعة لله ، وفي صحيح البخاري -رحمه الله- عن النبي ﷺ أنه قال: كل أمتي يدخلون الجنة إلا من أبى، قيل: يا رسول الله! ومن يأبى؟ قال: من أطاعني دخل الجنة، ومن عصاني فقد أبى. \nوهكذا التكبر على الناس وغمطهم من الكبائر، فالواجب التواضع لله والحذر من التكبر، صح عن رسول الله عليه الصلاة والسلام أنه سئل قال له رجل: يا رسول الله! الرجل يجب أن يكون ثوبه حسناً ونعله حسنة، أفذلك من الكبر؟ فقال النبي ﷺ: لا، إن الله جميل يحب الجمال، الكبر بطر الحق وغمط الناس» فبين عليه الصلاة والسلام أن كون الثياب حسنة والنعال حسنة وهكذا البشت وما أشبه ذلك هذا ليس من الكبر، إن الله جميل يحب الجمال، فالجمال طيب ومحبوب إلى الله ، وقد قال في كتابه الكريم: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31]، ثم بين أن الكبر أنه بطر الحق وغمط الناس، فالكبر بطر الحق، يعني: رد الحق واطراحه إذا خالف هواه، ومعنى غمط الناس يعني: احتقار الناس، هذا الكبر احتقار الناس، واستصغارهم، والتكبر عليهم، ورد الحق إذا خالف الهوى، هذا هو الكبر. \nأما الإسبال فهو محرم، جر الثياب أو الأزر أو السراويل أو البشت كله حرام؛ لما فيه من الكبر والخيلاء، ولما فيه أيضاً من إفساد الثياب وتنجيسها وتوسيخها، ولما فيه أيضاً من التشبه بالنساء، فإن المشروع للنساء إرخاء الثياب على الأقدام، فالمسبل قد تشبه بالنساء وخالف أمر الرسول ﷺ حيث نهى عن الإسبال، وقال عليه الصلاة والسلام: إياك والإسبال؛ فإنه من المخيلة، وقال أيضاً عليه الصلاة والسلام: ما أسفل من الكعبين فهو في النار رواه البخاري في الصحيح، وهذا عام سواء أراد تكبر أو لم يتكبر، هذا عام إذا تعمد ذلك، أما إذا غلبه ذلك ارتخى، مرفع وارتخى قليل وتعاهده هذا لا يدخل في ذلك، في قصة الصديق لما قال: يا رسول الله! إن الإزار يرتخي، قال: لست ممن يفعل ذلك خيلاء، أي لست ممن يتعمد إرخاء الإزار تكبراً وتعاظماً، وليس معناه التقييد، بل معناه أن من شأن من جر الأزر من شأنه التكبر، بخلاف الذي يتعاهد إزاره ويعتني به إذا استرخى فهذا ما قصد التكبر وليس ممن توعد بهذا الوعيد، ولهذا جاءت الأحاديث عامة في النهي عن الإسبال من غير تقييد، وجاء التقييد في أحاديث أخرى، فالتقييد لا يدل على تقييد الأحاديث الأخرى، بل هو من باب ذكر أفراد العام، فقوله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، هذا يوحي وعيداً شديداً فيمن قصد الخيلاء، مع عموم الأحاديث الدالة على تحريم الإسبال مطلقاً، مثل قوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار هذا عام ولأنه في الغالب يكون على الكبر، هذا الغالب، مع ما فيه من التساهل والتشبه بالنساء وتوسيخ الثياب ويعرضها للنجاسة، ومن هذا قوله صلى الله عليه وسلم في حديث أبي ذر عند مسلم: ثلاثة لا يكلمهم الله ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، هذا وعيد شديد فيما رواه مسلم في الصحيح لم يقيد بالكبر فهو عام، ومن قال: (إنه مع الكبر محرم ومع عدم ذلك مكروه) فقد ضاع.. خالف الأدلة مخالفة ظاهرة، لكن من جره بقصد الخيلاء صار إثمه أعظم وصارت عقوبته أشد، ومن جره تساهلاً وتعمداً فهو قد فعل منكراً وتشبه بالنساء وخالف الرسول ﷺ، وقد تعرض للوعيد: ما أسفل من الكعبين من الإزار فهو في النار، والوعيد في الآخر: ثلاثة لا يكلمهم الله ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، فالواجب على المسلمين الحذر من هذه الصفة وهذا الخلق الذميم ورفع الثياب فوق الكعب وألا تنزل تحت الكعب، فإن إزرة المؤمن من نصف ساقه إلى كعبه، ولا يجوز له نزول الثوب يعني سواء كان إزاراً أو قميصاً عن الكعب، ولا ينبغي أن يكون فوق نصف الساق؛ لأنه إذا كان فوق نصف الساق قد يتعرض لظهور العورة، والعورة من السرة إلى الركبة، لكن إذا ارتفع عن نصف الساق قد تنكشف العورة، فالأولى أن ينزل عن الركبة إلى نصف الساق، ولكن بين نصف الساق وبين الكعب هذا محل الإزرة الشرعية، وهذا محل أطراف الثياب من نصف الساق إلى الكعب، ولا يجوز النزول عن الكعب، نسأل الله للجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/4658/حكم-حلق-اللحى-واطالة-الازار-والتكبر-على-الغير ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02105.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":7783,"question":"هذه الرسالة من المستمع يقول: فضيلة الشيخ عبد العزيز بن عبد الله بن باز ! أخوكم في الله شلهوب بن حسن ، السؤال الأول: أنا أقص من طول لحيتي، وهذا الشعر الذي أقصه إذا تركته يضايقني ولا أستطيع تركه، فما الحكم؟ وفقكم الله.","title":"حكم الأخذ من اللحية","answer":"الجواب: ظاهر السنة عن النبي ﷺ أنه لا يجوز ولو طالت، النبي ﷺ قال: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين متفق عليه، وقال عليه الصلاة والسلام: جزوا الشوارب وأرخوا اللحى، خالفوا المجوس فالرسول ﷺ أمر بإحفاء الشوارب وقصها، وأمر بإعفاء اللحى وتوفيرها وإرخائها، فيجب عليك -أيها السائل- أن تتقي الله وأن تجتنب هذا العمل، وأن تبقي لحيتك وتعفيها طاعة لله ولرسوله وتمسكاً بشرعه وحذراً من مشابهة من خالف ذلك من المجوس وسائر المشركين ومن العصاة، هذا هو الواجب عليك، ومن اتقى الله جعل له مخرجاً، ويسر له من أمره يسراً. نعم.","link":"https://binbaz.org.sa/fatwas/5123/حكم-الاخذ-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04805.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":7888,"question":"أيضاً هناك سؤال آخر فيه: ما حكم الصلاة في الأظافر الطويلة؟","title":"حكم إطالة المرأة أظفارها","answer":"الجواب: على كل حال ما ينبغي بقاء الأظافر طويلة، الرسول ﷺ أمر بقصها وظاهر الأوامر الوجوب، فالواجب قص الأظافر، قص الشارب، نتف الإبط، حلق العانة، قد ثبت في الحديث الصحيح أن النبي عليه السلام وقت للناس في قص الأظافر، وفي قص الشارب، وفي نتف الإبط، وحلق العانة ألا يترك أكثر من أربعين ليلة، فلا ينبغي للمسلم أن يدعها أكثر من أربعين ليلة، بل السنة قص الشارب قبل ذلك، وهكذا قلم الأظفار من الرجل والمرأة، وهكذا نتف الإبط من الرجل والمرأة، وهكذا حلق العانة من الرجل والمرأة، كل هذا ينبغي أن يبادر إليه وأن يعتنى به قبل أربعين ليلة، فالرجل يقص شاربه، ويقلم أظفاره، وينتف إبطه، ويحلق عانته، والمرأة كذلك تقلم أظفارها، وتنتف إبطها، وتحلق عانتها أو تزيل العانة بشيء من الأدوية كالرجل سواء، هذه سنة مؤكدة، وقد يقال بالوجوب؛ لأنه وقت لنا في ذلك ألا ندع هذا أكثر من أربعين ليلة، والرسول ﷺ جاءت عنه الأوامر بقص الشارب، قلم الظفر، نتف الإبط.\nفظاهر هذا الوجوب وأنه لا يجوز أن تترك على وجه يشوه الحال ويعد طويلاً عرفاً؛ لأن هذا خلاف السنة الثابتة عنه عليه الصلاة والسلام، وما يفعله بعض الناس من تطويل الأظافر هذا منكر لا وجه له وتأس ببعض أعداء الله. نعم.","link":"https://binbaz.org.sa/fatwas/5359/حكم-اطالة-المراة-اظفارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05907.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":7915,"question":"يقول: أرجو عرض سؤالي هذا على المشايخ وهو: ما رأي فضيلة الشيخ بواعظ قام يعظ ويسهب في نصيحته وتطرق إلى موضوع توفير اللحية حتى بلغ به الأمر إلى قوله: (إن الذي يحلق لحيته تطلق منه زوجته ) وعلل ذلك أنه ديوث ومخنث إلى حد قوله أشياء كثيرة فيه، يقول: وأنه يستند أو يستدل بحديث: وفروا اللحى وجزوا الشوارب، خالفوا المجوس خالفوا المشركين بينما واقع الحال أن اليهود والنصارى والمجوس والهندوس هم الذين يوفرون شعورهم وخاصة اللحى والشوارب، فما رأي سماحتكم في ذلك؟","title":"حكم توفير اللحية وإرخاءها؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفلا ريب أن توفير اللحى وإرخاءها مما شرعه الله لعباده، ومما أمر به النبي عليه الصلاة والسلام، فالواجب على المسلم أن يعفيها وأن يرخيها وألا يتعرض لها بشيء لا حلق ولا قص؛ لما ثبت عنه عليه الصلاة والسلام أنه قال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين متفق على صحته، ولقوله عليه الصلاة والسلام: قصوا الشوارب وفي لفظ: جزوا الشوارب وأرخوا اللحى، خالفوا المجوس هذا هو الثابت عنه عليه الصلاة والسلام، وذلك يدل على وجوب إعفائها وإرخائها؛ لأن الأمر للوجوب هذا هو الأصل، فعلى المسلم أن يرخيها وأن يعفيها ويوفرها ولا يتعرض لها بقص ولا حلق.\nأما هذا المفتي أو هذا القاص أو هذا الواعظ الذي قال: إن من قص تطلق زوجته وأنه كذا وأنه كذا هذا غلط، وكلامه ليس بصحيح، وينبغي أن يعلم ويوجه ويخبر أنه قد أخطأ في هذا السبيل، فليس حلقها ولا قصها ردة عن الإسلام حتى تطلق منه امرأته، لا. بل معصية من المعاصي، فزوجته لا تطلق، ولا يسمى ديوثاً، ولا يجوز أن يقال هذا الكلام في حق حالق اللحية ولا قاصها، ولكن يقال: إنه خالف الرسول صلى الله عليه وسلم، عصى الرسول ﷺ، فهو من جنس بقية المعاصي التي ينهى عنها ويحذر منها ولكن لا يقال فيها: إنه ديوث، ولا يقال فيها: إنها تطلق امرأته، الديوث هو الذي يرضى بالفاحشة في أهله، هذا الديوث، هو الذي يرضى بأن تأتي زوجته الفاحشة، هذا الديوث.\nفالحاصل أن هذا الكلام الذي قاله الواعظ هذا كلام خطأ، وقد غلط وجهل، فالواجب أن يعلم وأن يرشد ويحذر من الغلو في الكلام وتجازف الكلام بغير حجة، وإنما كلام أهل العلم في ذلك هو أن ذلك لا يجوز، وأنه معصية وأن الواجب على المسلم أن يعظم أمر النبي ﷺ وأن يأخذ به ويمتثله وذلك بإرخاء لحيته وتوفيرها.\nأما كون بعض الكفار من اليهود أو النصارى أو الهنود أو غيرهم يطولونها ويرخونها فهذا لا يضرنا، إذا وافقونا فيما شرع الله لنا لا يضرنا، إنما يضرنا إذا وافقناهم في عوائدهم وغلوهم وما أشبه ذلك من أعيادهم، هذا هو الذي يضرنا، أما إذا وافقونا قصوا شواربهم وأرخوا لحاهم هذا لا يضرنا، بل نحب لهم أن يهتدوا حتى يوافقونا في الإسلام كله. نعم.","link":"https://binbaz.org.sa/fatwas/5412/حكم-توفير-اللحية-وارخاءها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_063/06301.mp3","categories":["سنن الفطرة"]},{"id":7947,"question":"سؤاله الثاني يقول: ما حكم الشريعة الإسلامية في طهارة البنات؟الشيخ: طهارة إيش؟المقدم: طهارة البنات، يعني: في تطهير البنات، أو ختانة البنات.","title":"حكم ختان المرأة","answer":"الجواب: ختان البنات مشروع كالختان للرجال لكنه آكد في حق الرجال، وقد ذهب جمع من أهل العلم إلى أنه يجب في حق الرجال، ويستحب في حق النساء، وذهب الأكثرون إلى أنه يستحب في حق الجميع، ولكنه في حق الرجال آكد بكل حال، ولهذا ذهب ابن عباس إلى أن الختان في حق الرجل متأكد جداً وذكر في ذلك تشديداً كبيراً؛ ولهذا ذهب جمع من أهل العلم إلى أنه واجب في حق الرجل وسنة في حق المرأة. نعم.","link":"https://binbaz.org.sa/fatwas/5478/حكم-ختان-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06809.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":8049,"question":"هذه رسالة وردتنا من خميس مشيط من حسين سليمان الخدوري المالكي يقول في رسالته: يوجد إحدى الممرضات بمستوصف أحد البوادي، تقوم بعملية الختان للأولاد، ولا سيما شباب أعمارهم تزيد على السابعة عشرة، فهل يجوز ذلك منها أم لا؟","title":"حكم قيام المرأة بختان الصبيان البالغين","answer":"الجواب: هذا عمل غريب، لا شك أن هذا لا يجوز، وأن الواجب أن يتولاه الرجال، يتولى هذا العمل وهو ختان الصبيان البالغين، ولا سيما من بلغ هذا السن، فإن هذا منكر، وليس هذا من الأمور التي يعجز عنها الرجال، بل هذا ميسر للرجال، فإذا بلغ الطفل سبع سنين باشره الرجال، وليس لها أن تباشر الصبيان إلا ما دون السبع السنين، أما ما فوق السبع السنين فينبغي أن يوكل إلى الرجال، ولا يجوز أن يوكل إلى النساء، إلا في حالة الضرورة بأن لا يوجد من يتولى الختان من الرجال، وهذا بعيد، بل هذا متيسر، المقصود المتيسر من الرجال، فلا ينبغي أن تولى المرأة هذا الشيء، بل لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/5841/حكم-قيام-المراة-بختان-الصبيان-البالغين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08107.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":8091,"question":"هذه الرسالة يسأل فيها صاحبها أيضاً ويقول: أنه المستمع (س. م. س) مصري يعمل في مزرعة في القصيم في البكيرية، يقول في رسالته: أنا أتابع برنامج نور على الدرب، وعلمت من المشايخ أن اللحية سنة، وأمر بها النبي ﷺ، وحرام حلقها. وفرت لحيتي ولكن أرسل لي أخي وقال: إذا أردت أن تزورنا احلق لحيتك؛ لأن فيه عندنا قرار بالقضاء على الجماعات الإسلامية، وهذا القرار يضم جميع أصحاب الذقون، هل يجوز لي حلقها أو تركها، وجزاكم الله عنا خير الجزاء؟","title":"حكم حلق اللحية خوف الأذى والحبس","answer":"الجواب: النبي عليه الصلاة والسلام أمر بإعفاء اللحى وتوفيرها وإرخائها، والحمد لله الذي هداك لهذا الأمر العظيم، وهذه السنة التي هي مما شرعه الله ، وهي من طريقة النبي ﷺ، وهي سنة بمعنى أنها من أعمال النبي عليه الصلاة والسلام، وهي واجبة؛ لأن الرسول ﷺ أمر بذلك فهي واجبة، إعفاؤها وإرخاؤها أمر واجب.\nفالواجب على جميع المسلمين هو إعفاء اللحى وإرخاؤها وتوفيرها وعدم قصها وحلقها، ولا ينبغي لعاقل أن يغتر بمن حلق أو قص بل ينبغي للعاقل أن يهتم باتباع النبي عليه الصلاة والسلام والسير على منهاجه؛ لأن الله يقول: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، فعلينا أن نتبع الرسول ﷺ، وأن ننقاد لأمره، وأن نحذر معصيته عليه الصلاة والسلام، وأنت أيها الأخ إذا سافرت إلى مصر فاستعن بالله ولا تحلقها أبداً، وأبشر بالعافية، فالحكومة إنما تطلب من كان يتسبب في مشاكلها، أما من أعرض عنها فلا تضره إن شاء الله، فأنت لا تشتغل بما لا يعنيك، وإذا وصلت إلى البلاد فاشتغل بما ينفعك من طاعة الله ورسوله، ومن كسب الحلال ولا يضرك ما يقوله هذا الرجل، بل استقم على إعفائها وإرخائها وأبشر بالعافية: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/5889/حكم-حلق-اللحية-خوف-الاذى-والحبس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08605.mp3","categories":["سنن الفطرة"]},{"id":8142,"question":"يقول أيضاً: يقول ﷺ: خمس من الفطرة: الاستحداد، والختان، وقص الشارب، ونتف الإبط، وتقليم الأظافر، ما صحة هذا الحديث، ونرجو شرحه لنا؟","title":"الحكم على حديث: (خمس من الفطرة) وشرحه","answer":"الجواب: هذا الحديث صحيح عن رسول الله عليه الصلاة والسلام، رواه الشيخان البخاري ومسلم في الصحيحين، عن أبي هريرة ، أن النبي عليه السلام قال: خمس من الفطرة: الختان، والاستحداد، وقص الشارب، وقلم الظفر، ونتف الآباط، هذه من سنن الفطرة، وهي سنن متأكدة، ينبغي لكل مسلم ولكل مسلمة أن يتعاهد ذلك. الختان سنة في حق الجميع في حق الرجال والنساء، وذهب جمع من أهل العلم إلى وجوبه، ولاسيما في حق الرجال، وهو المعروف من مذهب أحمد رحمه الله أنه واجب الختان، وقال جمع من أهل العلم: إنه سنة مؤكدة في حق الجميع، فينبغي أن يتعاهد، وأن لا يترك، وإذا كان في حال الصغر كان أولى؛ لأنه أسلم للطفل وأقل تعباً وألماً، وأسرع في البرء.\nأما الاستحداد وقص الشارب وقلم الظفر ونتف الإبط، هذه سنة مؤكدة في حق الجميع، في حق الرجال والنساء، إلا: أن الشارب يختص بالرجال، لكن قلم الظفر نتف الإبط وحلق العانة هذا في حق الجميع، في حق الرجال والنساء جميعاً سنة، وينبغي أن لا يترك أكثر من أربعين ليلة، لذا ثبت في صحيح مسلم عن أنس  قال: وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة، أن لا نترك ذلك أكثر من أربعين ليلة، ومعنى وقت لنا: يعني: وقت الرسول ﷺ كما رواه أحمد وغيره، فالحاصل أنه لا ينبغي أن تؤخر هذه الأمور أكثر من أربعين ليلة، بل ينبغي للمؤمن أن يتعاهدها في أقل من أربعين ليلة، قص شاربه، قلم الظفر نتف الإبط حلق العانة، ينبغي التعاهد لهذه الأشياء، وأن لا تترك أكثر من أربعين ليلة. نعم.\nوما يعتاده بعض الناس الآن من تطويل الأظافر من بعض النساء هذا غلط، وهذا لا يجوز تطويلها هذا فيه تشبه بالبهائم، ثم إن كان يفعله بعض الكفرة هو تشبه بالكفرة، والنبي ﷺ نهى عن التشبه بأعداء الله، وعن التشبه بالبهائم، فالحاصل أن تطويل الأظافر أمر لا يجوز أكثر من أربعين ليلة، فالواجب على المرأة والرجل جميعاً أن يتعاهدا الأظفار، قبل أربعين ليلة في قصها قلمها، هكذا الإبط ينتف، فإن لم يتيسر نتفه وشق عليه نتفه، أزاله بغير ذلك بالنورة ويمكن بالأدوية التي تزيله؛ إذ المقصود إزالته، وكذلك العانة تحلق بالموسى، فإذا لم يستطع حلقها بالموسى أزالها بما يتيسر من الأدوية، وحلقها بالموسى أفضل إذا تيسر، وهو الاستحداد، فإن كان ذلك يشق، أو لم يتيسر للرجل أو للمرأة، فإنها تزال بالأدوية المعروفة التي يعتادها الناس.\nقص الشارب يقص بالمقراض، ويتعاهد حتى لا يطول؛ لأن النبي عليه السلام قال: قصوا الشوارب وأعفوا اللحى، وقال: أحفوا الشوارب، فالسنة إحفاؤها وقصها، وأما اللحى فلا، اللحى يجب إكرامها وإعفاؤها وتوفيرها وإرخاؤها، كما أمر به النبي صلى الله عليه وسلم، ومن المصائب اليوم ومن الأسف المحزن أن كثيراً من الناس صار يعاديها ويقصها ويحلقها وهذا منكر ظاهر، لا يجوز لمسلم أن يتعاطاه، بل الواجب إعفاؤها وإرخاؤها وتوفيرها؛ لأنها جمال المؤمن، وزينة وفارقة بينه وبين الكافر والمرأة، فكيف يليق به أن يتشبه بالنساء أو بالحالقين من الكفرة؟! بل يجب عليه أن يوفرها ويعفيها طاعة للنبي عليه الصلاة والسلام وامتثالاً لأمره عليه الصلاة والسلام، حيث قال: قصوا الشوارب وأعفوا اللحى، جزوا الشوارب وأرخوا اللحى خالفوا المجوس، هكذا قال عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/5946/الحكم-على-حديث-خمس-من-الفطرة-وشرحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08904.mp3","categories":["الحكم على الأحاديث","سنن الفطرة"]},{"id":8143,"question":"سؤاله الأخير يقول فيه: إذا أسلم الكافر هل يلزمه تغيير اسمه، وإذا كان رجل كبير ولم يطهر وهو صغير؛ لأنه كان كافراً، ماذا يفعل به إذا تكرمتم؟","title":"حكم تغيير اسم من أسلم من الكفار وختانه","answer":"الجواب: إذا كان اسمه ليس بحسن شرع له تغيير اسمه بعد الإسلام، ولأن تغييره أيضاً يعطي انطباعاً واضحاً وظاهراً عن انتقاله للإسلام، وأنه قد انتقل إلى الإسلام؛ لأنه يسأل عن أسباب التغيير، فيعرف الناس أنه أسلم، وأيضاً في الغالب أن أسماءهم في الكفر قد لا تكون مناسبة، فيغير بأسماء إسلامية: كصالح وأحمد وعبد الله وعبد الرحمن ومحمد ونحو ذلك، وأما إن كان اسمه معبداً لغير الله كعبد المسيح، أو عبد الزهرة، أو عبد موسى أو عبد عيسى، هذا يجب تغييره، لأنه لا يعبد إلا لله سبحانه وتعالى، فإذا كان اسمه معبداً لغير الله وجب أن يغير، بعبد الله وبعبد الرحمن أو نحو ذلك، أما إذا كان ما عبد لغير الله، ولكن أسماء معروفة عند الكفرة ومن عادة الكفرة، فالأولى تغييرها والأفضل تغييرها إلى أسماء إسلامية.\nوأما الختان فالأفضل أن يختتن ولو كبير، لكن بواسطة الطبيب الحاذق العارف، ينبغي له أن يختتن، وجمع من أهل العلم يقولون: يجب عليه أن يختتن. بعض أهل يرى أنه يجب عليه أن يختتن، إذا كان ما فيه خطر، أما إن قال الطبيب: إن فيه خطر فلا لزوم يسقط، لكن إذا قال الطبيب: إن اختتانه لا بأس به ولا حرج فيه، ولا خطر فيه، فإنه يختتن هذا هو الذي ينبغي له، وهو سنة مؤكدة أو واجب عند جمع من أهل العلم، فإذا تيسر له الاختتان وهو كبير من غير خطر، هذا هو الأولى والأفضل والأحوط، أما إن كان فيه مشقة، أو قال بعض الأطباء: إن فيه خطر، فلا، فلا حاجة إلى ذلك ويسقط، وإن كان ختنه قد يكون سبباً لتنفيره من الإسلام، فلا يذكر ولا يبين له ذلك ويترك؛ لأن دخوله في الإسلام نعمة عظيمة ولو لم يختتن، فلا ينبغي أن يعرض له بشيء ينفره من الإسلام، لكن إذا دخل في الإسلام واستقر في الإسلام، ينظر بعد ذلك، إن تيسر ختانه بدون مشقة وبدون خطر، هذا أولى وأحوط، وإن لم يتيسر ترك. نعم.","link":"https://binbaz.org.sa/fatwas/5947/حكم-تغيير-اسم-من-اسلم-من-الكفار-وختانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08905.mp3","categories":["مسائل متفرقة في العقيدة","سنن الفطرة","اللباس والزينة"]},{"id":8178,"question":"ما حكم حلق العارضين وترك الذقن؟","title":"حكم حلق شعر العارضين وترك الذقن","answer":"الجواب: اللحية عند أئمة اللغة هي ما نبت على الخدين والذقن يقال لها: لحية، اللحية بالكسر: هي الشعر النابت على الخدين والذقن فلا يجوز لمسلم أن يأخذ شعر خديه ولكن يجب توفير ذلك مع الذقن توفير هذا مع هذا؛ هذه اللحية، واللحية وجه الإنسان تقول العرب: ظهر وجه فلان يعني: ظهرت لحيته، فهي وجه الرجل المميز له عن النساء فلا يجوز له حلقها ولا قصها لقول النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين ولقوله عليه الصلاة والسلام قصوا الشوارب ووفروا اللحى خالفوا المشركين رواه البخاري في الصحيح.\nوقال ابن عمر رضي الله تعالى عنهما: إن الرسول عليه الصلاة والسلام أمرنا بإحفاء الشوارب وإرخاء اللحى متفق على صحته.\nوروى مسلم في الصحيح عن أبي هريرة رضي الله تعالى عنه عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفواا المجوس.\nفيجب على المؤمن توفير اللحية وقص الشارب كما أمر بهذا نبينا وإمامنا محمد عليه الصلاة والسلام وفي ذلك الخير العظيم وفي ذلك إحياء السنة وفي ذلك التأسي بالنبي صلى الله عليه وسلم وامتثال أمره وفي ذلك البعد عن مشابهة النساء والكفرة.\nفالواجب على المؤمن أن لا يغتر بهؤلاء الحليقين وأن لا يتأسى بهم وأن ينظر من الذي أمره من هو الذي أمره؛ أمره الرسول صلى الله عليه وسلم اللي بعثه الله هادياً ومبشراً ونذيراً، الذي قال فيه جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا[الحشر:7].\nوقال فيه سبحانه: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] وقال فيه : وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ [النساء:13]  ۝  وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَارًا خَالِدًا فِيهَا وَلَهُ عَذَابٌ مُهِينٌ [النساء:14] في آيات كثيرات. نعم.","link":"https://binbaz.org.sa/fatwas/5985/حكم-حلق-شعر-العارضين-وترك-الذقن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10506.mp3","categories":["سنن الفطرة"]},{"id":8263,"question":"أخونا (ع. ع. ع) بعث برسالة ووجها لكم خاصة سماحة الشيخ أخونا يعرض عدة أمور من بينها يقول: هناك أشخاص يحلقون لحاهم وهناك من يربيها من أجل الرياء كما يقول ما الحكم والحالة هذه؟","title":"حكم من يحلق لحيته وحكم من يعفيها رياءً","answer":"الجواب: الرسول ﷺ قال في الحديث الصحيح الذي رواه البخاري ومسلم في الصحيحين: قصوا الشوارب وأعفوا اللحى خالفوا المشركين وقال ابن عمر رضي الله تعالى عنهما: أمرنا الرسول ﷺ بإحفاء الشوارب وإعفاء اللحى وقال: وفروا اللحى وقصوا الشوارب خالفوا المشركين هكذا جاء في الحديث الصحيح ورواه مسلم في صحيحه عن أبي هريرة  عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس فأمر ﷺ بإرخاء اللحى وأمر بإعفائها وأمر بتوفيرها وأمر بإحفاء الشوارب وقصها وجزها، فالواجب على المسلم أن يمتثل أمر الرسول ﷺ لأن الله يقول: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُُ فَانْتَهُوا [الحشر:7] ويقول جل وعلا: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59] ويقول سبحانه وتعالى: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهََ [النساء:80].\nفعليك -يا عبد الله- أن تطيع الرسول ﷺ فيما أمر وأن تنتهي عما نهى عنه أما كونه يرائي هذا بينه وبين الله ليس للناس إلا الظاهر وعليه أن يتقي الله ويخلص لله في إعفائها وتوفيرها والله الذي يحاسبه فالواجب عليه أن يتظاهر بالمظهر الشرعي وأن يأخذ بالمظهر الشرعي وأن يعفي لحيته ويوفرها وأما كونه أراد رياءً فهذا ليس إليك أنت لا تعلم ما في القلوب بل الله الذي يعلم ما في القلوب.\nفعليه هو أن يتقي الله وأن يفعلها إخلاصاً لله وطاعة لله ولرسوله عليه الصلاة والسلام ولو فرضنا أنه فعلها رياءً فهو خير ممن حلقها هو خير، الذي حلقها تظاهر بالمعاصي والمعصية والمخالفة للرسول ﷺ.\nأما هذا أظهر الطاعة وأظهر الخير وأخفى الرياء والله هو اللي يحاسبه على نيته الباطنة ليس المخلوقون هم الذين يحاسبونه ولعله يرائي اليوم ويتوجه غداً إلى الإخلاص ويهديه الله إلى الإخلاص لأن طاعة الرسول ﷺ التي قدرها بفعله وإظهاره إعفاءها قد يغلب عليه بعد ذلك أن يقدرها في باطن أمره وأن يخلص لله  فالذي جعله يظهر الإعفاء والتوفير هو سبحانه قادر على أن يجعل في قلبه أيضاً الإخلاص وأن يكون هذا العمل لوجه الله .\nفبكل حال إظهار الطاعة خير من إظهار المعصية وأما الإخلاص فبين العبد وبين ربه.","link":"https://binbaz.org.sa/fatwas/6075/حكم-من-يحلق-لحيته-وحكم-من-يعفيها-رياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10602.mp3","categories":["سنن الفطرة"]},{"id":8362,"question":"سؤالها الثاني: ما حكم إطالة الأظافر للمرأة دون وضع الأصباغ عليها؟","title":"حكم إطالة المرأة لأظافرها","answer":"الجواب: الرسول ﷺ حدد في قص الشارب وقلم الظفر ونتف الإبط وحلق العانة أربعين ليلة، ثبت في الصحيح عن أنس  قال: وقت لنا في قص الشارب وقلم الظفر ونتف الإبط وحلق العانة أن لا ندع ذلك أكثر من أربعين ليلة خرجه مسلم في صحيحه رحمه الله، وأخرجه النسائي وجماعة بلفظ: وقت لنا رسول الله ﷺ في قص الشارب وقلم الظفر ونتف الإبط وحلق العانة، أن لا ندع ذلك أكثر من أربعين ليلة، فالواجب على الرجل والمرأة جميعاً أن يكون الحد هذا المقدار، أربعين ليلة، فإذا تمت المدة وجب قص الشارب وقلم الظفر ونتف الإبط وحلق العانة، ولا يزاد على ذلك، لا في الأظفار ولا في الشارب ولا في حلق العانة ولا في نتف الإبط. نعم.\nالمقدم: بارك الله فيكم، إذاً إبقاء النساء لأظافرهن حتى تطول سماحة الشيخ، وإن كان للزينة طبعاً هذا لا يجوز؟\nالشيخ: لا يجوز ما زاد عن الأربعين لا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6211/حكم-اطالة-المراة-لاظافرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11402.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":8389,"question":"يسأل أخونا سؤال آخر، ويقول: ما حكم من يساوي لحيته، بجعلها متساوية مع بعضها البعض؟","title":"الواجب في اللحية التوفير والإرخاء","answer":"الجواب: الواجب إعفاء اللحية وتوفيرها وإرخاؤها، وعدم التعرض لها بشيء؛ لما ثبت عنه ﷺ أنه قال: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين متفق على صحته عن ابن عمر رضي الله تعالى عنهما، وروى البخاري في صحيحه رحمة الله عليه، عن النبي ﷺ أنه قال: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وروى مسلم في صحيحه، عن أبي هريرة ، عن النبي ﷺ أنه قال: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس فهذه الأحاديث كلها تدل على وجوب إعفاء اللحى وتوفيرها وإرخائها، وعلى وجوب قص الشوارب وإحفائها.\nهذا هو المشروع، وهذا هو الواجب الذي أرشد إليه النبي عليه الصلاة والسلام، وفي ذلك تأس به ﷺ وبأصحابه، ومخالفة للمجوس والمشركين، وبعد عن مشابهة النساء.\nوأما ما رواه الترمذي رحمه الله، عن النبي ﷺ أنه كان يأخذ من لحيته من طولها وعرضها؛ فهو خبر باطل عند أهل العلم، لا يصح عن النبي صلى الله عليه وسلم، وقد تشبث به بعض الناس، وهو خبر لا يصح؛ لأن في إسناده عمر بن هارون البلخي ، وهو متهم بالكذب، فلا يجوز للمؤمن أن يتعلق بهذا الحديث الباطل، ولا أن يترخص بما يقوله بعض أهل العلم؛ فإن السنة حاكمة، والله يقول جل وعلا: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80] ويقول سبحانه: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلََ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6255/الواجب-في-اللحية-التوفير-والارخاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11608.mp3","categories":["سنن الفطرة"]},{"id":8404,"question":"رسالة باعثها أحد الإخوة يقول: عطا الله المطلق من العقبة في الأردن، صدر رسالته بقوله: برنامج نور على الدرب الذي يعتبر بحق إنارةً وتوعيةً وهداية لكل من ألقى السمع، أما الذين سدوا أو سدت أسماعهم فلا نسلم من شر ألسنتهم، التي هي مجرد وسيلة للكلام، بارك الله بكل من ساهم، ولا زال يساهم في البرنامج الديني الاجتماعي القيم، الأسئلة: ألاحظ بعض المصلين وقد طالت أظافرهم، واحتست بالأوساخ النجسة، فهل هذا يتفق مع الدين؟ وهل يصح وضوءهم؟","title":"الحث على تعاهد سنن الفطرة","answer":"الجواب: الأظفار ينبغي قلمها، وتعاهدها قبل الأربعين، الرسول ﷺ وقت للناس في قلم الظفر، وحلق العانة، ونتف الإبط، وقص الشارب، أن لا يترك ذلك أكثر من أربعين ليلة، هكذا ثبت الحديث عن رسول الله عليه الصلاة والسلام، قال أنس ، وهو خادم النبي ﷺ قال: وقت لنا في قص الشارب وقلم الظفر ونتف الإبط وحلق العانة أن لا نترك ذلك أكثر من أربعين ليلة خرجه الإمام مسلم في صحيحه وخرجه أحمد والنسائي وجماعة بلفظ: وقت لنا رسول الله ﷺ أن لا نترك الأظفار، والشارب، وحلقق العانة، ونتف الإبط، أكثر من أربعين ليلة.\nفالواجب على الرجال والنساء أن يلاحظوا هذا الأمر، فلا يترك الظفر، ولا الشارب، ولا العانة - الشعرة - ولا الإبط أكثر من أربعين ليلة، الرجل يتعاهد والمرأة تتعاهد، الرجل يتعاهد ظفره، وشاربه، وعانته، وإبطه؛ حتى لا تجتمع الأوساخ هناك، ليست نجسة الأوساخ ليست نجسة لكنها مستقذرة، ينبغي ملاحظة ما قاله النبي صلى الله عليه وسلم، وكذلك المرأة تلاحظ ذلك في ظفرها، وعانتها، وإبطها، كما قاله النبي عليه الصلاة والسلام، من باب النظافة والنزاهة، والرسول ﷺ جاء بكل خير، ودل على كل خير عليه الصلاة والسلام، ونهى عن كل شر. نعم.","link":"https://binbaz.org.sa/fatwas/6288/الحث-على-تعاهد-سنن-الفطرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11710.mp3","categories":["سنن الفطرة"]},{"id":8405,"question":"ألاحظ الاختلاف في إرخاء اللحى وإطلاقها، فأي تربية للحى توافق الشرع الإسلامي، وسار عليها السلف الصالح؟","title":"حكم إعفاء اللحى وتوفيرها","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين خرجه الإمام البخاري في صحيحه، وخرجه الإمام مسلم في صحيحه، وخرجه أئمة آخرون رحمة الله عليهم، فهو حديث صحيح، ثابت عن رسول الله ﷺ عند أهل العلم، ومعناه: أنه يجب على المؤمن قص شاربه، وإرخاء لحيته إعفاؤها، وعدم أخذها لا حلقاً ولا قصاً، وقال أيضاً عليه الصلاة والسلام: قصوا الشوارب ووفروا اللحى، خالفوا المشركين خرجه البخاري في صحيحه رحمه الله، وقال أيضاً فيما رواه أبو هريرة رضي الله عنه عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس المجوس: عباد النار، فهذه الأحاديث وما جاء في معناها تدلنا على أن الواجب على المسلمين قص الشوارب، وعدم إطالتها، وفي اللفظ الآخر: أحفواا الشوارب وتدل أيضاً على وجوب إرخاء اللحى وتوفيرها وإعفائها، هذا الواجب على المسلمين طاعة هذا الرسول الكريم عليه الصلاة والسلام، وقد قال الله عز وجل: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] ويقول سبحانه: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ وَمَنْ تَوَلَّى فَمَا أَرْسَلْنَاكَ عَلَيْهِمْْ حَفِيظًا [النساء:80] ويقول النبي ﷺ: كل أمتي يدخلون الجنة إلا من أبى، قيل: يا رسول الله! ومن يأبى؟ قال: من أطاعني دخل الجنة ومن عصاني فقد أبى.\nفالواجب على أهل الإسلام هو العناية بطاعة الرسول ﷺ في كل شيء، في الصلاة، والزكاة، والصيام، والحج، والجهاد، والأمر بالمعروف، والنهي عن المنكر، وإعفاء اللحى، وقص الشوارب، وعدم إسبال الثياب إلى غير ذلك، كل ما جاء به الرسول ﷺ يجب علينا أن نأخذ به؛ فعلاً للأوامر وتركاً للنواهي، وهذا هو طريق الجنة وطريق السعادة، يقول الله سبحانه في كتابه العظيم: تِلْكَ حُدُودُ اللَّهِِ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ [النساء:13]  ۝  وَمَنْ يَعْصِ اللَّهََ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَارًا خَالِدًا فِيهَا وَلَهُ عَذَابٌ مُهِينٌ [النساء:14] ويقول سبحانه: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَوَاتِ وَالأَرْضِ لا إِلَهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ فَآمِنُوا بِاللَّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللَّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ[الأعراف:158] فالهداية والسلامة والنجاة والفلاح في اتباعه ﷺ، وطاعة أوامره وترك نواهيه.\nويقول جل وعلا في كتابه العظيم: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] فمن كان يحب الله، ويحب رسوله عليه الصلاة والسلام، فعليه أن يتبع هذا الرسول العظيم عليه الصلاة والسلام، فاتباعه والتمسك بما جاء به هو السبيل الوحيد وهو الطريق للمغفرة ودخول الجنة والنجاة من النار ولمحبة الله للعبد، وفق الله الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/6289/حكم-اعفاء-اللحى-وتوفيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11711.mp3","categories":["سنن الفطرة"]},{"id":8686,"question":"يسأل أيضاً ويقول: هل يجوز حلق الشعر الموصل بين شحمتي الأذن وبين الحَنَك، مع إبقاء اللحية، وهل يعتبر هذا الشعر من اللحية؟","title":"حكم حلق الشعر بين شحمتي الأذن والحَنَك","answer":"الجواب: ما نبت على الخدين فهو من اللحية، وما كان فوق الخدين فوق العظم هذا تبع الرأس، ما فوق العظم الذي يحاذي الأذن هذا من الرأس وما تحته ما على الخد هذا تبع اللحية، يقول صاحب القاموس: اللحية: الشعر النابت على الخدين والذقن، فيترك الشعر الذي على الخدين وعلى الذقن؛ لأنه اللحية. نعم.","link":"https://binbaz.org.sa/fatwas/6824/حكم-حلق-الشعر-بين-شحمتي-الاذن-والحنك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/21511.mp3","categories":["سنن الفطرة"]},{"id":8803,"question":"السؤال الخامس - في رسالة الأخ سعد موسى السويرق الصلاحي - يقول فيه: ما هو الحكم فيمن حلق لحيته، وهل هناك دليل قرآني على ذلك أفيدونا جزاكم الله خيراً؟","title":"حكم حلق اللحية أو تقصيرها","answer":"الجواب: حلق اللحية أو قصها كله محرم ممنوع، لا يجوز للمسلم أن يقص لحيته ولا أن يحلقها، لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين هكذا قال عليه الصلاة والسلام فيما صح عنه رواه البخاري ومسلم في الصحيحين من حديث ابن عمر رضي الله تعالى عنهما، وقال أيضاً عليه الصلاة والسلام: جزوا الشوارب وأرخوا اللحى خالفوا المجوس وفي لفظ: ووفروا اللحى رواه مسلم في الصحيح، هذا يدل على وجوب إعفاء اللحية وتكريمها وتوفيرها وإرخائها، وفي نص القرآن الكريم يقول الله : مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، ويقول سبحانه من الآية الكريمة الأخرى: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [الحشر:7] ويقول سبحانه: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ يعني: أمر النبي ﷺ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] فهذا وعيد عظيم لمن خالف أمر الرسول ﷺ.\nفالواجب على الأمة اتباع الرسول ﷺ وطاعة أمره وترك نهيه، هذا هو الواجب على جميع الأمة، وقد ثبت عنه عليه الصلاة والسلام أنه قال: كل أمتي يدخلون الجنة إلا من أبى، قيل: يا رسول الله! من يأبى؟ قال: من أطاعني دخل الجنة، ومن عصاني فقد أبى رواه البخاري .\nفنصيحتي لجميع المسلمين في كل مكان أن يوفروا اللحية وأن يكرموها ويرخوها وأن يحذروا حلقها وقصها، وأن لا يتأسوا بمن فعل ذلك من الناس اليوم، فقد كثر من فعل ذلك اليوم، فلا ينبغي للمؤمن أن يتأسى بمن فعل ذلك، ولكن يأخذوا بأمر النبي ﷺ، ويطيعوه عليه الصلاة والسلام، ويعفي لحيته ويكرمها طاعة لله واتباعاً لشريعته والله ولي التوفيق. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6960/حكم-حلق-اللحية-او-تقصيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22207.mp3","categories":["سنن الفطرة"]},{"id":8928,"question":"يشترك مع الأخ: إبراهيم محمد العبدلي من ليبيا أخونا: مربع حسين علي آل حمران القحطاني ويسألان عن حكم رمي الشعر المتساقط والأظافر مع القمائم والوساخات، هل ذلك جائز أم أن هناك مشروعية لدفنها بمفردها؟","title":"حكم وضع الشعر والأظافر في القمائم","answer":"الجواب: لا نعلم في هذا بأساً أنها توضع مع القمائم لا بأس في ذلك ولا نعلم في هذا حرجاً، نعم. الأظفار والشعور التي تسقط من الإنسان توضع في القمائم أو تدفن كله واسع. نعم.","link":"https://binbaz.org.sa/fatwas/7085/حكم-وضع-الشعر-والاظافر-في-القماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14303.mp3","categories":["سنن الفطرة"]},{"id":9126,"question":"هذه الرسالة التي وردت إلى البرنامج من طالب علم كنا قد وعدنا مرسلها بإتمام أسئلته في هذه الحلقة، السؤال الثاني في رسالة الأخ طالب علم يقول فيه: قال ﷺ: خالفوا المشركين وفروا اللحى وأحفوا الشوارب، وقال في والد أبي بكر: غيروا شعره وجنبوه السواد، ما حكم صبغ الشعر للنساء والرجال إذا صح هذا الحديث أفيدونا أفادكم الله؟","title":"حكم حلق اللحى وصبغ الشعر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذان الحديثان صحيحان ثابتان عن النبي عليه الصلاة والسلام، فالأول: من حديث ابن عمر ، يقول النبي ﷺ: أحفوا الشوارب ووفروا اللحى، وفي لفظ آخر: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، متفق على صحته من حديث ابن عمر رضي الله تعالى عنهما، وروى مسلم في الصحيح عن أبي هريرة  أن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، فهذا يدل على وجوب إكرام اللحى وتوفيرها وإعفائها وإرخائها وأنه لا يجوز للمسلم قصها ولا حلقها، أما ما وقع فيه الكثير من الناس اليوم فهو مؤلم ومحزن ولا ينبغي للمسلم أن يتأسى بأحد في ذلك، فإن الأسوة هو رسول الله عليه الصلاة والسلام ومن سار على نهجه من أهل الخير، أما من خالف نهج الرسول ﷺ وخالف أمره بحلق اللحية أو قصها فليس بقدوة، بل ينبغي أن ينصح بل يجب أن ينصح وأن ينكر عليه ويوجه إلى الخير ولا يقتدى به.\nأما الشوارب فالواجب قصها وإحفاؤها وعدم إطالتها؛ لأن إطالتها مشابهة للمشركين ولا سيما المجوس ، فإنهم يطيلون شواربهم، فالرسول ﷺ أمر بقصها وأمر بجزها، قال أبو محمد بن حزم -وهو من الكبار المعروفين بمعرفة مقالات العلماء- قال: اتفق العلماء على أن إعفاء اللحى وتوفيرها وقص الشوارب أمر مفترض، فحكى الإجماع على أن قص الشوارب مفترض، وعلى أن إعفاء اللحية وتوفيرها أمر مفترض فلا يجوز للمسلم أن يخالف سنة الرسول ﷺ وإجماع أهل العلم في ذلك.\nأما الحديث الثاني: وهو قوله ﷺ في قصة والد أبي بكر: غيروا هذا الشعر وجنبوه السواد، فليس لفظ الحديث هكذا، لفظ الحديث: غيروا هذا الشيب، يقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد رواه مسلم في الصحيح وغيره، ومعنى هذا الحديث الدلالة على أن الشيب يغير وأن السنة تغييره ومن هذا قوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم، فالسنة للمسلم أن يغير شيبه وهكذا المرأة تغير شيبها، لكن بغير السواد، ولهذا قال: اجتنبوا السواد، فيغير الشيب بالحمرة والصفرة والسواد المخلوط بالحمرة لا بأس، كان أبو بكر وعمر يخضبان بالحناء والكتم، وروي عن النبي ﷺ أنه خضب بالحناء والكتم، يعني: بالسواد المخلوط بالكتم يصبغ سواداً والحناء حمرة فإذا اجتمعا صارا سواداً بحمرة فإذا خضب بالسواد المخلوط بالحمرة فلا بأس، أما السواد الخالص فلا يجوز لهذا الحديث ولأحاديث أخرى جاءت في المعنى تدل على تحريم الصبغ بالسواد، ومن هذا ما رواه أبو داود والنسائي وجماعة بإسناد صحيح عن ابن عباس رضي الله عنهما عن النبي ﷺ أنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة، وهذا وعيد عظيم يوجب الحذر. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7285/حكم-حلق-اللحى-وصبغ-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22901.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":9264,"question":"إذا ولد الطفل معوقاً كيف يكون ختانه مع العلم أن الطبيب لا يقر إجراء أي عملية له خوفاً على حياته؟","title":"حكم ترك ختان الطفل خوفاً على حياته","answer":"الجواب: إذا كان الختان قد يؤدي إلى فقد الحياة سقط الختان، والختان سنة عند الجمهور وإن أوجبه بعض أهل العلم فهو واجب عند قوم وسنة عند الجمهور، فإذا لم يتيسر إلا بخطر سقط وإن تيسير بدون خطر شرع فعله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7427/حكم-ترك-ختان-الطفل-خوفا-على-حياته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15402.mp3","categories":["سنن الفطرة"]},{"id":9318,"question":"وأولى رسائل هذه الحلقة وردت إلى البرنامج من السائل علي بن حزام اليماني ، يقول في رسالته: أنا رجل ولدت مختوناً، ولم يقم أهلي بختانتي مرة أخرى، والآن أسأل إذا كان الشخص مختوناً عند ولادته هل يجزئ ذلك عن الاختتان المسنون أم لا؟","title":"من ولد مختوناً هل يختن مرة ثانية أم لا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، وصلى الله وسلم وبارك على عبده ورسوله وخيرته من خلقه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد:\nفإن الإنسان إذا ولد مختوناً فإن ذلك يكفي ولا حاجة إلى أن يعمل أهله شيئاً، وقد كفاهم الله المئونة والحمد لله، وهذا قد يقع لبعض الناس، وقد بلغنا من ذلك عدة وقائع يولد فيها الرجل مختوناً، وبذلك يكون أهله قد كفوا هذه المئونة والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7481/من-ولد-مختونا-هل-يختن-مرة-ثانية-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23701.mp3","categories":["سنن الفطرة"]},{"id":9447,"question":"ووردت رسالة من الأخ آدم أحمد من قرية المثابة بالسودان، يقول في رسالته التي تحتوي على سؤالين: إذا كان لدي بعض الشعيرات في لحيتي وهي لا تتجاوز عشر شعرات، وأنها قبيحة المنظر أي: غير مقبولة، هل يجوز لي حلقها، أفيدونا أفادكم الله؟","title":"حكم حلق لحية بها شعرات قليلة","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال: قصوا الشوارب واعفوا اللحى، خالفوا المشركين رواه البخاري ومسلم في الصحيحين من حديث ابن عمر رضي الله تعالى عنهما، وخرج مسلم في صحيحه من حديث أبي هريرة  عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى، خالفوا المجوس هكذا يقول ﷺ، وهكذا يأمر، ولم يستثن شعيرات قليلات ولا شعيرات كثيفات بل أطلق، قال: واعفوا اللحى وأرخوا اللحى وهذا يعم قليلها وكثيرها.\nفلا يجوز للمسلم أن يقصها ولا أن يحلقها ولو كانت قليلة، ولو كانت بزعمه فيها تشويه، فإنه متى اتقى الله يسر الله أمره وعدل لحيته ووفقه إلى الخير، وأزال عنه ما يخشى مما يكره.\nفالواجب على المؤمن أن يتقي الله في ذلك، وأن يعتني بها من جهة إكرامها وتوفيرها وتعاطي ما يكثرها من الأسباب، قد يكون عند الأطباء أشياء تعين على تحسين هذا الشعر وتوافره، فليتعاط ما يعينه على ذلك .\nأما أن يقصها أو يحلقها فلا، السنة واضحة في هذا الأمر، فليس لمؤمن أن يقص اللحية ولو كانت قليلة وليس له أن يحلقها، بل الواجب عليه توفيرها وإكرامها وإعفاؤها وإرخاؤها طاعة لله ولرسوله ﷺ، ومخالفة لأعداء الله من المشركين والمجوس .\nولو أنهم أرخوها في بعض الأحيان ولو فرضنا أنهم أرخوها جميعًا فإنا نبقى على حالنا نرخيها وإذا وافقونا فلا يضر، ليتهم يوافقونا حتى في الإسلام، ليتهم يسلمون ونحمد الله على ذلك.\nفالمقصود أن بعض الجهلة قد يظن أنهم متى أرخوا نحلق وهذا غلط كبير، لا، إذا أرخوها فالحمد نسأل الله لهم الهداية حتى يدخلوا في الإسلام، إذا وافقونا في أمور الإسلام لا نخالف الإسلام لأجلهم، لا؛ ولكن لا نفعل ما يوافقهم ويوافق زيهم ونخالف ديننا. نعم.","link":"https://binbaz.org.sa/fatwas/7611/حكم-حلق-لحية-بها-شعرات-قليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19104.mp3","categories":["سنن الفطرة"]},{"id":9451,"question":"السؤال الثالث والأخير في رسالة الأخت السائلة من العراق تقول: في الأفراح كفرح الزفاف مثلاً هل يجوز الغناء والتزين له؟ وهناك رقصة أحياناً عندنا تسمى: بالدبكة كانت تجري سابقاً للرجال فقط بمعزل عن النساء، لكن في الوقت الحاضر تطور الأمر فأصبحت هذه الرقصة يختلط فيها الرجال والنساء في مناسبات الزواج، فما حكم الشرع في ذلك بارك الله فيكم؟","title":"حكم الغناء للنساء ورقصة الدبكة للرجال مع النساء","answer":"الجواب: أما الغناء المعروف الذي ليس فيه تعد لحرمات الله، بل الغناء في مدح أهل الزوجة أو أهل الزوج مع الدف فلا بأس مثل ما جاء في حديث عائشة لما زاروهم قالوا:\n\n\t\n\t\t\n\t\t\tأتيناكم أتيناكم\n\t\t\tفحيانا وحياكم\n\t\t\n\t\n\n\n\n\t\n\t\t\n\t\t\tولولا الذهب الأحمـر\n\t\t\tما حلت بواديكم\n\t\t\n\t\n\n\n\n\t\n\t\t\n\t\t\tولولا الحنطة الحمـراء\n\t\t\tما سمنت عذاريكم\n\t\t\n\t\n\nوما أشبه ذلك من الأشعار والغناء يتعلق بمدح الزوج مدح الزوجة مدح أهلهم، أهل الزوج أو أهل الزوجة، أو أشياء نحو هذا ليس فيها ظلم لأحد، وليس فيها غيبة لأحد، فهذا لا بأس به مع الدف بين النساء خاصة، هذا مشروع من باب إعلان النكاح، كما أمر النبي بإعلان النكاح عليه الصلاة والسلام، وأمر بضرب الدف فيه؛ لأن إعلانه أمر مطلوب حتى يعرف أن فلانة تزوجت فلاناً، وحتى لا يظن بهم السوء، فإن السفاح والزنا يكون بالسر، أما الزواج الشرعي فيكون بالعلن.\nأما الدبكة التي يفعلها الرجال فلا يجوز، وإذا فعلوها مع النساء كان أشر وأقبح، فلا يجوز فعل ذلك من الرجال مع النساء مختلطين؛ لما فيه من الفتنة والفساد الكبير، أما الرجال فليس لهم دخل في هذا إنما هذا للنساء، وإذا فعل الرجال شيئاً يوافق الشرع مثل التدرب على السلاح، وحمل الأثقال، مثل اللعب بالحراب، والتروس، والرمي هذا هو شأن الرجال وحدهم، في أي مناسبة.\nأما اختلاط الرجال بالنساء في الأعراس أو في غير الأعراس هذا منكر لا يجوز؛ لما فيه من الفتنة، قد قال عليه الصلاة والسلام: ما تركت بعدي فتنة أضر على الرجال من النساء، واختلاط الرجال بالنساء في كل مناسبة ينبني عليه شر كثير، ويفضي إلى فتنة عظيمة، فيجب الحذر من ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7630/حكم-الغناء-للنساء-ورقصة-الدبكة-للرجال-مع-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24007.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":9883,"question":"يقول في رسالته: ما حكم ختان البنات، فإنه لا بد من فعل ذلك عندنا، وقد قال لي بعض الناس: إنه لا يجوز؛ لأن فيه مثلة أو تعذيب فما حكم ذلك؟","title":"حكم ختان النساء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالختان للبنات سنة مؤكدة، وهكذا للرجال كله سنة مؤكدة، وذهب جمع من أهل العلم إلى وجوب ذلك في حق الرجال، وهو قول قوي، فينبغي ختن الرجال ولا ينبغي التساهل في ذلك، وهكذا يستحب ختن النساء إذا تيسر من يعرف ذلك من الخاتنات، أو الخاتنين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8044/حكم-ختان-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26401.mp3","categories":["سنن الفطرة","قضايا المرأة"]},{"id":9908,"question":"هذا السائل من الجمهورية العربية السورية (ت. م. ع. جميل ) يقول: هل حالق اللحية آثم، أم عاص عن طاعة الله عز وجل، وهل توجد آية قرآنية تحض على ذلك؟","title":"هل يأثم حالق اللحية؟","answer":"الجواب: حالق اللحية آثم؛ لأنه عاصي للرسول ﷺ؛ لقول النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين ولقوله ﷺ: قصوا الشوارب ووفروا اللحى خالفوا المشركين وفي اللفظ الآخر: جزوا الشوارب وأرخوا اللحى، خالفوا المجوس فالواجب على كل مسلم أن يعفي لحيته وأن يحذر قصها أو حلقها، هذا هو الواجب على الجميع تأسياً بالنبي ﷺ وعملًا بقوله، والله يقول سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ويقول سبحانه: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النور:54] وقد أمرنا فعلينا أن نطيعه عليه الصلاة والسلام، وقد كان كث اللحية، فعلينا أن نتأسى به عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8076/هل-ياثم-حالق-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27320.mp3","categories":["سنن الفطرة"]},{"id":9995,"question":"يسأل أخونا سؤال مطول حول سنة إعفاء اللحية، فيقول: سماحة الشيخ! هل ثبت عن رسولنا الكريم محمد ﷺ أنه قال: قصوا الشوارب وأعفوا اللحى وهل معنى هذا أن نترك اللحية تنمو وتكبر ولا نحلق أو نقص منها أي شيء، فإن كان ذلك هو الحال فإنها ستصبح غزيرة لدرجة كبيرة، وحدثونا عن الشارب هل يقص من الأطراف أم من الوسط أم من جميع أجزائه أم يترك، وما هو الحال بالنسبة للمنطقة الوسطى التي بين الشارب واللحية؟","title":"حكم قص الشارب وإعفاء اللحية","answer":"الجواب: ثبت عن رسول الله ﷺ في الصحيحين في البخاري ومسلم وهما أصح الكتب بعد القرآن، هذان الصحيحان صحيح البخاري وصحيح مسلم هما أصح الكتب بعد كتاب الله عز وجل ثبت فيهما عن النبي ﷺ أنه قال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين من حديث ابن عمر عن النبي ﷺ قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وفي اللفظ الآخر: قصوا الشوارب ووفروا اللحى خالفوا المشركين، وفي الآخر: أحفوا الشوارب ووفروا اللحى خالفوا المشركين.\nوفي رواية مسلم من حديث أبي هريرة ، عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس فهذه الأحاديث الصحيحة كلها تدل على وجوب إعفاء اللحى وتوفيرها وإرخائها وعدم قصها أو حلقها، ولو طالت، الواجب علينا السمع والطاعة لنبينا عليه الصلاة والسلام، يقول الله : قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] عليه الصلاة والسلام.\nويقول الله جل وعلا: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّه [النساء:80] ويقول  في كتابه العظيم: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] يعني: المخالف لأمر الرسول صلى الله عليه وسلم في خطر عظيم، وذلك أن المخالف قد يصاب بالفتنة وهي الشرك -والعياذ بالله- أو بعذاب أليم في الدنيا أو في الآخرة بسبب المخالفة، وقال جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] وقال جل وعلا: تِلْكَ حُدُودُ اللَّهِ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ ۝ وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَارًا خَالِدًا فِيهَا وَلَهُ عَذَابٌ مُهِينٌ [النساء:13-14].\nوفي صحيح البخاري عن النبي ﷺ أنه قال: كل أمتي يدخلون الجنة إلا من أبى، قيل: يا رسول الله! من يأبى؟ قال: من أطاعني دخل الجنة ومن عصاني فقد أبى وفي الصحيحين عن النبي ﷺ أنه قال: من أطاعني فقد أطاع الله، ومن عصاني فقد عصى الله، ومن أطاع الأمير فقد أطاعني، ومن عصى الأمير فقد عصاني يقول ﷺ فيما رواه الشيخان - البخاري ومسلم: من أطاعني فقد أطاع الله ومن عصاني فقد عصى الله، ومن أطاع الأمير فقد أطاعني ومن عصى الأمير فقد عصاني يعني: في المعروف، الأمير يطاع في المعروف لا في المعصية، كما في الأحاديث الأخرى: إنما الطاعة في المعروف والشوارب تقص: قصوا الشوارب وتحف: أحفوا الشوارب جميعها أطرافها ووسطها، فالواجب قصها جميعها أو حفها جميعها ما هو بالأطراف فقط يخلي الوسط أو الوسط ويخلي الأطراف كفعل المجوس لا، الواجب قصها.\nقال أبو محمد بن حزم -في كتابه المحلى المعروف-: اتفق العلماء على أن قص الشارب وإعفاء اللحية فرض، يعني: واجب على المسلمين، حكى الإجماع إجماع العلماء على أن قص الشارب وإعفاء اللحية فرض؛ لأن الأوامر جاءت بذلك.\nفالواجب على المؤمن أن يمتثل.\nأما العنفقة التي تحت الشفة السفلى فهذه تبع اللحية، العنفقة، يقال لها: العنفقة، الشعيرات التي تحت الشفة السفلى هذه تابعة للحية، وأما الشارب فهو كل ما كان على الشفة العليا هذا يقال له: شارب.\nالواجب إحفاؤه أو قصه كما أمر به النبي عليه الصلاة والسلام، ولا يحلق، الأفضل أن لا يحلق يقص قص. نعم وفق الله الجميع.\nالمقدم: اللهم آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8160/حكم-قص-الشارب-واعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30002.mp3","categories":["سنن الفطرة"]},{"id":10032,"question":"تقول: عندنا عادة موجودة في بلدتي وهي عند تقليم الأظافر نقوم بدفن الأظافر في الأرض ونقول: يا تراب! اشهد يوم الحساب، فما هو رأيكم؟","title":"حكم دفن الأظافر بعد تقليمها","answer":"الجواب: هذا لا أصل له، لا أصل له، فلو رمت الأظافر القصاصة فلا بأس، لو رمتها في الأرض أو مع القمامة لا حرج، أما دفنها في الأرض وتقل: يا تراب.. ! اشهد.. ! هذا لا أصل له، بل هذا من البدع التي لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8203/حكم-دفن-الاظافر-بعد-تقليمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30107.mp3","categories":["سنن الفطرة"]},{"id":10039,"question":"تقول: عندنا عادة موجودة في بلدتي وهي عند تقليم الأظافر نقوم بدفن الأظافر في الأرض ونقول: يا تراب! اشهد يوم الحساب، فما هو رأيكم؟","title":"حكم دفن الأظافر بعد تقليمها","answer":"الجواب: هذا لا أصل له، لا أصل له، فلو رمت الأظافر القصاصة فلا بأس، لو رمتها في الأرض أو مع القمامة لا حرج، أما دفنها في الأرض وتقل: يا تراب.. ! اشهد.. ! هذا لا أصل له، بل هذا من البدع التي لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8203/حكم-دفن-الاظافر-بعد-تقليمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30107.mp3","categories":["سنن الفطرة"]},{"id":10273,"question":"يقول: إن له لحية من شعرات قليلة، ربما خمس أو أكثر قليلاً وإذا تركها يكون شكلها بالنسبة له غير مرض، فما هو توجيهكم؟","title":"وجوب إعفاء اللحية الكثيفة والخفيفة","answer":"الجواب: الواجب على من له لحية أن يحافظ عليها، وأن يعفيها ويكرمها، ولو كانت قليلة، لعموم قول النبي ﷺ : قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وفي اللفظ الآخر: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين رواه البخاري ومسلم في الصحيحين، وروى مسلم في صحيحه عن النبي ﷺ أنه قال : جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس.\nفالواجب عليك يا أخي! أن تعفيها ولو كانت قليلة، ولو شعرات، ليس لك أخذها، واسأل ربك أن يحسنها وأن يزيدها، حتى تكون على هيئة حسنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8460/وجوب-اعفاء-اللحية-الكثيفة-والخفيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31107.mp3","categories":["سنن الفطرة"]},{"id":10283,"question":"يقول: إن له لحية من شعرات قليلة، ربما خمس أو أكثر قليلاً وإذا تركها يكون شكلها بالنسبة له غير مرض، فما هو توجيهكم؟","title":"وجوب إعفاء اللحية الكثيفة والخفيفة","answer":"الجواب: الواجب على من له لحية أن يحافظ عليها، وأن يعفيها ويكرمها، ولو كانت قليلة، لعموم قول النبي ﷺ : قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وفي اللفظ الآخر: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين رواه البخاري ومسلم في الصحيحين، وروى مسلم في صحيحه عن النبي ﷺ أنه قال : جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس.\nفالواجب عليك يا أخي! أن تعفيها ولو كانت قليلة، ولو شعرات، ليس لك أخذها، واسأل ربك أن يحسنها وأن يزيدها، حتى تكون على هيئة حسنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8460/وجوب-اعفاء-اللحية-الكثيفة-والخفيفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31107.mp3","categories":["سنن الفطرة"]},{"id":10795,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المدينة المنورة، وباعثها المستمع عبدالمنعم بشارة محمد علي، الأخ عبدالمنعم يقول: نحن نعلم جميعًا فضل السواك، ونعلم حديث رسول الله ﷺ الذي يقول: لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة لكني ألاحظ -يا سماحة الشيخ- أن كثيرًا من الناس لا يحرصون على نظافة السواك، ولا يحرصون على الأوقات المستحب فيها استعمال السواك، فهم يستعملونه مثلًا بعد أن يكبر الإمام، ويستعملونه أثناء الخطبة، أرجو أن يتفضل سماحتكم بتوجيه الناس حول الأوقات المناسبة لاستعمال السواك؟ جزاكم الله خيرًا.","title":"السواك.. فضله وحكمه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، نبينا وإمامنا محمد بن عبدالله، وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد.  فقد صحت الأحاديث عن رسول الله -عليه الصلاة والسلام- في فضل السواك والترغيب فيه، ومن ذلك ما رواه الشيخان البخاري ومسلم في الصحيحين عن النبي -عليه الصلاة والسلام- أنه قال: لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة وهذا يدل على تأكد السواك، وشرعيته؛ لأنه ﷺ رغب فيه، وحرض عليه، وإنما أراد أمر الوجوب، يعني: لأمرت أمر إيجاب، وإلا فأمر الاستحباب قد ثبت عنه -عليه الصلاة والسلام- ما يدل على استحبابه وشرعيته. ومن ذلك قوله ﷺ: السواك مطهرة للفم، مرضاة للرب خرجه النسائي وغيره بإسناد صحيح، ومن ذلك قوله ﷺ: لولا أن أشق على أمتي لأمرتهم بالسواك مع كل وضوء ومن ذلك ما ثبت في صحيح مسلم عن عائشة -رضي الله عنها- قالت: \"كان -عليه الصلاة والسلام- يبدأ بالسواك إذا دخل منزله -عليه الصلاة والسلام، وكان يستعمل السواك كثيرًا -عليه الصلاة والسلام- وكان إذا قام من الليل يشوص فاه بالسواك\" رواه الشيخان من حديث حذيفة . والأحاديث في هذا كثيرة تدل على شرعية السواك، واستحبابه، وهو يتأكد عند الصلاة قبل أن يكبر الإمام، يستاك قبل أن يكبر، السنة أن يستاك عند الصلاة قبل أن يكبر، فإذا كبر الإمام بادر، وكبر بعده. كذلك عند المضمضة عند الوضوء في أول الوضوء، وهكذا عند دخول المنزل، وهكذا إذا تغير الفم والأسنان يستحب أن يستاك حتى يزيل الرائحة السيئة من الفم، وحتى يحصل بذلك تنظيف الأسنان، ولهذا قال -عليه الصلاة والسلام-: السواك مطهرة للفم، مرضاة للرب وهذا يعم الصائم، وغير الصائم، في آخر النهار، وفي أوله، وفي الليل والنهار. وقد ذهب بعض أهل العلم إلى أنه يكره في آخر النهار للصائم، لقوله ﷺ: خلوف فم الصائم أطيب عند الله من ريح المسك قالوا: السواك يزيل هذا الخلوف، أو يخففه، والصواب أنه لا يكره للصائم، في آخر النهار، بل يستحب دائمًا؛ لأنه -عليه الصلاة والسلام- قال: لولا أن أشق على أمتي لأمرتهم بالسواك مع كل وضوء، وعند كل صلاة. وهذا يعم الصائم وغيره، ويعم صلاة الظهر والعصر في حق الصائم وغيره، ولهذا الخلوف لا يزول، بل يبقى؛ لأن الخلوف شيء يتصاعد من الجوف في حق الصائم، فالسواك لا يزيله، بل بعد رفع السواك يحصل تصاعد هذا الخلوف الذي هو مفضل عند الله . ثم خبر الخلوف خاص بمعنى يقتضي ترغيب الصائم في الصيام، وبيان فضل الصيام، وأنه له عند الله منزلة عظيمة، ولا يمنع في مسألة السواك. فالمشروع لكل مؤمن أن يعتني بالسواك كما شرعه الله -جل وعلا- على يد رسوله -عليه الصلاة والسلام- وأن يحرص عليه إحياءً للسنة، وتعظيمًا، لها وترغيبًا فيها حتى يتأسى به غيره. وهكذا بقية السنن مثل الوتر فإنه متأكد ما بين صلاة العشاء إلى طلوع الفجر، يستحب للمؤمن أن يوتر في السفر والحضر، وأقله ركعة، وليس له حد، لكن أقله ركعة، وإن أوتر بثلاث أو بخمس أو بأكثر كان أجره أعظم، والأفضل أن يوتر بوتر النبي ﷺ إحدى عشرة، أو ثلاث عشرة، وإن أوتر بأقل، أو بأكثر فلا حرج في ذلك، وهكذا صلاة الضحى سنة مؤكدة، وأقلها ركعتان، وإن صلى أكثر فلا بأس، هكذا سنة الظهر.. سنة المغرب.. سنة العشاء.. سنة الفجر.  وهكذا بقية السنن، سنة الظهر أربع قبلها وثنتان بعدها، يعني: تسليمتين قبلها والسنة ركعتان بعدها، سنة المغرب ركعتان بعدها، سنة العشاء ركعتان بعدها، سنة الفجر ركعتان قبلها، يستحب قبل العصر أربع، لقوله ﷺ: رحم الله امرءًا صلى أربعًا قبل العصر يعني من تسلمتين، ويستحب أن يصلي أمام كل صلاة ركعتين، قبل المغرب.. قبل العشاء لقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، ثم قال في الثالثة: لمن شاء. وهكذا عيادة المريض، تشميت العاطس إذا حمد الله، البداءة بالسلام، وإفشاء السلام، نصيحة المسلمين، اتباع الجنائز، الصلاة على الجنائز، كل هذه سنن عظيمة ينبغي للمؤمن العناية بها. وهكذا صدقة التطوع، ولو بشق تمرة، والدعوة إلى الخير، والتشجيع عليه، حفظ اللسان عن فضول الكلام التي لا فائدة فيها، إلى غير هذا مما ينبغي للمؤمن أن يعتني به، نعم. المقدم: جزاكم الله خيرًا يذكر -سماحة الشيخ- أن بعض الناس يستعمل السواك بعد أن يكبر الإمام للبداية في الصلاة، وأثناء الخطبة؟  الشيخ: تقدم التنبيه على هذا، السنة أن يستاك قبل أن يكبر الإمام، حتى إذا كبر الإمام بادر بالتكبير، لقوله ﷺ: إذا كبر فكبروا فيستحب للمؤمن أن يستاك قبل تكبير الإمام، إذا قام للصلاة يستاك، وإذا كبر إمامه كبر، وهكذا يوم الجمعة لا يستاك وقت الخطبة، بل ينصت، ويقبل على الخطبة، ولا يستاك ولا يعبث، حتى السواك، ولا يرد السلام، ولا يشمت العاطس، والإمام يخطب، بل يقبل على الخطبة، ويستمع لها وينصت لها، ويحفظ السواك حتى تأتي الحاجة إليه عند إقامة الصلاة، عندما ينتهي من الخطبة، وهكذا لا يعبث بثيابه، أو بلحيته، أو بغير ذلك، بل يقبل على خطبة الإمام، ويستمع لها، وينصت، ويكون قلبه حاضرًا حتى يستفيد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8971/السواك-فضله-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35201.mp3","categories":["سنن الفطرة"]},{"id":10940,"question":"سمعت من إحدى الصديقات أن رمي الشعر المتساقط من الرأس، وبقايا الأظافر بعد قصها في الزبالة حرام؛ لأن الإنسان يسأل عنها يوم القيامة، فهل هذا صحيح؟ وإذا كان صحيحًا فما هو المكان المناسب لإتلافها، والتخلص منها، نرجو النصح والتوجيه جزاكم الله خيرًا.","title":"حكم رمي الشعر المتساقط من الرأس والأظافر في القمامة","answer":"الجواب:  ليس لهذا أصل، ولا حرج أن تلقى هذه الأشياء في القمامة، سواء كانت من الشعر، أو من الأظفار، كل ذلك لا حرج فيه، مع القمامة، أو في أرض تدفن، فكل ذلك لا بأس به، ولا حرج في ذلك والحمد لله، نعم.  المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9123/حكم-رمي-الشعر-المتساقط-من-الراس-والاظافر-في-القمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36307.mp3","categories":["سنن الفطرة"]},{"id":11030,"question":"السائل: أحمد إبراهيم من الرياض يقول: هل المقصود باللحية هو الشعر الذي ينبت على اللحية، أو جميع ما ينبت في الوجه والرقبة، أو المتصل بالرقبة، وهل على الرجل شيء إذا حلق الشعر من رقبته، وخده، وجهونا سماحة الشيخ؟","title":"حد اللحية وحكم حلق شعر الرقبة","answer":"الجواب:  اللحية: ما نبت على الخدين والذقن، هذه اللحية، كما قال صاحب القاموس، ولسان العرب، اللحية: الشعر النابت على الخدين والذقن، هذه اللحية، لا يجوز قصها ولا حلقها، أما ما نبت على الرقبة لا، ليس من اللحية، الشعر الذي على الرقبة ليس من اللحية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9208/حد-اللحية-وحكم-حلق-شعر-الرقبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28712.mp3","categories":["سنن الفطرة"]},{"id":11102,"question":"سماحة الشيخ له فقرة أخيرة يسأل عن السواك بعد العصر في رمضان ما حكمه يقول؟","title":"حكم السواك بعد العصر في رمضان","answer":"الجواب:  حكمه لا بأس، حكمه سنة مطلقًا في جميع الأوقات، السواك للصائم وغير الصائم في العصر وغيره، لقوله ﷺ: السواك مطهرة للفم مرضاة للرب ويقول ﷺ: لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة هذا يعم صلاة الظهر والعصر وغيرهما في حق الصائم وغيره.","link":"https://binbaz.org.sa/fatwas/9280/حكم-السواك-بعد-العصر-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29010.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":11592,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، رمز إلى اسمه بالحروف (أ. ح) أخونا سبق وأن عرضنا جزءًا من أسئلته في حلقات مضت، وفي هذه الحلقة يسأل جمعًا من القضايا، فيسأل سماحتكم فيقول: ما حكم من يقوم بقص شيء من اللحية، أو تقصيرها؟ وهل يجب على المسلم ألا يأخذ منها شيئًا على الإطلاق؟ جزاكم الله خيرًا.","title":"حكم تقصير اللحية أو أخذ شيء منها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالواجب على كل مسلم توفير اللحية وإكرامها وإعفاؤها وإرخاؤها كما أمر النبي بذلك -عليه الصلاة والسلام- فليس له أن يأخذ منها شيئًا لا بحلق ولا بقص، بل الواجب إعفاؤها وإكرامها وإرخاؤها؛ لما ثبت عن النبي ﷺ أنه قال: قصوا الشوارب، وأعفوا اللحى؛ خالفوا المشركين ويقول ﷺ: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين ويقول -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس.  فهذه الأحاديث، وما جاء في معناها كلها تدل على وجوب إعفاء اللحية، وتوفيرها وإرخائها، وأنه لا يجوز حلقها، ولا قصها؛ لأن في ذلك تشبهًا بأهل الشرك، والله يقول -جل وعلا- في كتابه الكريم: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول -جل وعلا-: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] ويقول -جل وعلا-: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلاغُ الْمُبِينُ [النور:54] فالهداية، والنجاة في طاعته -عليه الصلاة والسلام- واتباع شريعته في هذا الباب وغيره. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9775/حكم-تقصير-اللحية-او-اخذ-شيء-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38701.mp3","categories":["سنن الفطرة"]},{"id":11612,"question":"ما الحكم في حلق اللحية، فإن هناك من يقول بأن إطلاق اللحية سنة، والسنة يثاب فاعلها، ولا يعاقب تاركها؟","title":"حكم اللحية وجوب الإعفاء والتوفير","answer":"الجواب:  حكم اللحية، وجوب الإعفاء والتوفير، عملًا بقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى؛ خالفوا المشركين وقوله ﷺ: قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين وقوله ﷺ: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس وما ورد أنه ﷺ كان يقص من لحيته من طولها وعرضها هذا باطل، ليس بصحيح، رواه الترمذي، ولكن إسناده ليس بصحيح. فالواجب على المؤمن توفير اللحية، وإكرامها، وإعفاؤها، وقد كتب بعض الناس هذه الأيام في بعض الصحف الأهلية هنا ما يدل على تسهيله في جز اللحية، وفي قصها وتعديلها، وهذا قول باطل، وقد غلط في هذا، وقد تعلق بما يروى عن ابن عمر أنه كان يأخذ من لحيته في الحج يقبض .... يأخذ ما زاد على القبضة، وهذا من اجتهاده  ولا يجوز أن يحتج باجتهاد الصحابي فيما يخالف السنة، السنة مقدمة على الجميع، وهذا اجتهاد منه  في الحج، تأول فيه قوله تعالى: ثُمَّ لْيَقْضُوا تَفَثَهُمْ [الحج:29] وظن واجتهد أن هذا منه. والصواب أن هذا خلاف الحق، وأنه غلط من ابن عمر  وكذلك احتج بما رواه الترمذي أن النبي ﷺ كان يأخذ من طول لحيته وعرضها، وهو خبر باطل كما تقدم، ليس بصحيح. فالواجب على أخينا الذي كتب في هذا المقام أن يتوب إلى الله، وأن يرجع عن كتابته التي أخطأ فيها، وسوف نكتب إن شاء الله في ذلك ما يبين الصواب للأمة، نسأل الله أن يوفق الجميع، ويحسن العاقبة للجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9794/حكم-اللحية-وجوب-الاعفاء-والتوفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38805.mp3","categories":["سنن الفطرة"]},{"id":11661,"question":"المستمع مطير ناير الجهني من المدينة المنورة بعث يسأل ويقول: توفي لي ابن عندما اكتمل له عام، وأنا لم أقم بختانه بعد، فهل أكون آثمًا؟ وهل علي كفارة؟","title":"حكم تأخير الختان ومتى يتعين","answer":"الجواب:  لا حرج في ذلك، لأن الختان لا يتعين في مدة الرضاع، لو ما ختنه إلا بعد خمس سنين، أو ست سنين، أو أكثر، لا حرج، لكن قبل أن يبلغ، يختن قبل أن يبلغ، وإذا ختنه في ...... سن الرضاع كان أسهل وأيسر، والأمر فيه واسع والحمد لله، وإذا مات ولم يختن لا حرج عليه؛ لأن الختان لا يجب في سن الرضاع، بل يجوز تأخيره إلى ما قبل البلوغ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9844/حكم-تاخير-الختان-ومتى-يتعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29813.mp3","categories":["سنن الفطرة"]},{"id":11733,"question":"رجل نبتت له لحية، ولكنها لم تقم، بل هنا شعر كثيف، وهنا شعر خفيف، هل يجوز حلقها لتتساوى بعد ذلك؟","title":"حكم حلق اللحية إذا كان بعضها خفيفاً وبعضها كثيفاً","answer":"الجواب:  ليس له الحلق لا، يبقاها على حالها حتى يعدلها الله ما يحلقها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9919/حكم-حلق-اللحية-اذا-كان-بعضها-خفيفا-وبعضها-كثيفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39304.mp3","categories":["سنن الفطرة"]},{"id":12006,"question":"ما حكم أخذ الشيء اليسير من اللحية؟","title":"حكم الأخذ اليسير من اللحية","answer":"الجواب:  الواجب إعفاؤها، وعدم التعرض لها، لقول النبي ﷺ: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين قصوا الشوارب وأرخوا اللحى، خالفوا المجوس والشيء اليسير يجر إلى الكثير، فالواجب إعفاؤها، وإرخاؤها، والحذر من القص. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10191/حكم-الاخذ-اليسير-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43120.mp3","categories":["سنن الفطرة"]},{"id":12469,"question":"أخيرًا تسأل سماحتكم وتقول: أين توضع الأظافر بعد تقليمها؟ وهل يجوز رميها في سلة المهملات؟","title":"حكم وضع الأظفار والشعر في سلة المهملات","answer":"الجواب:  نعم إذا قلم أظافره؛ يرميها في سلة المهملات لا حرج، أو قص شاربه؛ يرميه كذلك، الأمر واسع في هذا، أو قص عانته كذلك إذا رماها في القمامة؛ فلا حرج، وإن دفنها؛ فلا حرج، كله طيب. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/10670/حكم-وضع-الاظفار-والشعر-في-سلة-المهملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40411.mp3","categories":["سنن الفطرة"]},{"id":12615,"question":"سمعت في إحدى حلقات هذا البرنامج سؤالًا يتعلق بكيفية قص الشارب، وإعفاء اللحى، ولكن فاتني تمام الجواب، أرجو أن تعيدوا لي ذلك، جزاكم الله خيرًا؟","title":"كيفية قص الشوارب وإعفاء اللحى","answer":"الجواب:  السنة قص الشارب بحيث لا يحفيه كله، بل يجتهد في قصه قصًا تامًا، مثلما قال النبي ﷺ: أحفوا الشوارب لكن لا يكون حلقًا، يكون له أساس بقية حتى يعرف أنه شارب، والنبي ﷺ قال: قصوا الشوارب، جزوا الشوارب وقوله: أحفوا الشوارب يفسر بقوله: (جزوا) ليس معناه الحلق، وإنما معناه المبالغة، حتى لا يكون له سبالات، وحتى لا يكون يقع في شرابه إذا شرب، بل يكون خفيفًا جدًا، لا يتأذى به في شربه، ولا في كلامه؛ لقوله ﷺ: قصوا الشوارب، وأعفوا اللحى قصوا الشوارب، ووفروا اللحى. ولا يجوز ترك ذلك أكثر من أربعين ليلة، لما ثبت عن أنس -رضي الله عنه- في صحيح مسلم قال: \"وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة ألا نترك ذلك أكثر من أربعين ليلة\" ورواه أحمد وغيره بلفظ: \"وقت لنا رسول الله ﷺ\" فهذا شيء من الرسول ﷺ يتضمن ألا يزيد على أربعين ليلة، بل يقص شاربه قبل ذلك، وهكذا يقلم أظفاره، وينتف إبطه، ويحلق عانته قبل كمال الأربعين، يلاحظ هذا ويواظب عليه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10812/كيفية-قص-الشوارب-واعفاء-اللحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45709.mp3","categories":["سنن الفطرة"]},{"id":12636,"question":"تقول في سؤال آخر: نسمع دائمًا من بعض الناس بأن الذي يرمي قلامة أظافره، والشعر الذي يسقط منه بأنه يكلف بأكله جزاءً له يقوم القيامة، هل هذا صحيح؟","title":"حكم إلقاء قلامة الأظافر والشعر في القمامة","answer":"الجواب:  لا نعلم لهذا أصلًا، لا نعلم لهذا أصلًا، ولا حرج في إلقاء قلامة الأظفار، وما قص من شاربه، أو من إبطه؛ لا حرج بإلقائها مع القمامة، أو في أي مكان، أو دفنها في الأرض، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10846/حكم-القاء-قلامة-الاظافر-والشعر-في-القمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41510.mp3","categories":["سنن الفطرة"]},{"id":13035,"question":"أخيرًا تسأل أختنا من جدة وتقول: ما حكم تطويل أظافر المرأة، علمًا بأنها تصلي، وتؤدي جميع فرائضها؟","title":"حكم إطالة المرأة الأظافر","answer":"الجواب:  تطويل الأظافر ممنوع في حق الرجل والمرأة جميعًا....، ليس للمرأة أن تطول أظافرها، وليس للرجل أن يطول أظافره، والحد في ذلك أربعون أربعون ليلة، فما زاد على هذا؛ يجب عليها قص الظفر، وعلى الرجل كذلك، قلم الظفر، وعلى الرجل كذلك. وهكذا نتف الإبط، وحلق العانة، وقص الشارب، يقول أنس : \"وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة ألا نترك ذلك أكثر من أربعين ليلة\" رواه مسلم في صحيحه، ومعنى: (وقت لنا) يعني: وقته النبي ﷺ وهكذا جاء في رواية أحمد والنسائي وجماعة: وقت لنا رسول الله ﷺ بالتصريح أنه وقته ﷺ. فالواجب على الرجال والنساء ألا يطولن الأظافر أكثر من هذه المدة، أما في هذه المدة فأقل؛ فالأمر واسع، لكن لا يزدن على الأربعين، لا في الظفر، ولا في الإبط، ولا في العانة، وهكذا الرجل في الشارب، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11252/حكم-اطالة-المراة-الاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47215.mp3","categories":["سنن الفطرة"]},{"id":13160,"question":"في أسئلتها هذا السؤال تقول السائلة من سلطنة عمان: ما حكم الشرع في نظركم -سماحة الشيخ- فيمن يقوم بتحسين اللحية دون حلقها، خاصة بأن حجم اللحية كثيف جدًا، وملفت للنظر، هل يكون معذور أمام الله  إذا قام بتهذيبها؟ وجهونا في ضوء هذا السؤال.","title":"حكم تقصير اللحية وتهذيبها","answer":"الجواب:  ليس لأحد أن يتعدى على اللحية لا بحلق ولا تقصير ولا تهذيب، الواجب تركها، وعدم التعرض لها؛ لقول النبي ﷺ في الحديث الصحيح: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين متفق على صحته، ويقول ﷺ: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين هكذا جاء في الحديث الصحيح عند البخاري ومسلم. وفي رواية لـمسلم يقول -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس. فالواجب على المؤمن إعفاء اللحية، وتوفيرها، وعدم التعرض لها، أما الشارب فيقص، ويحفى بأمر النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11416/حكم-تقصير-اللحية-وتهذيبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51019.mp3","categories":["سنن الفطرة"]},{"id":13237,"question":"يقول هذا السائل: هل يجب دفن الشعر المتساقط، والأظافر المقصوصة في التراب، نرجو منكم إفادة؟","title":"حكم دفن الشعر المتساقط وقلامة الأظافر","answer":"الجواب:  ليس بلازم، يلقيها في القمامة، والحمد لله، ما فيه دليل على دفنها، إذا ألقاها في القمامة؛ كفى، والحمد لله.","link":"https://binbaz.org.sa/fatwas/11520/حكم-دفن-الشعر-المتساقط-وقلامة-الاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52019.mp3","categories":["سنن الفطرة"]},{"id":13391,"question":"يقول هذا السائل: هل قص بعض من أجزاء اللحية جائز؟ خاصة إذا كان المراد تجميل اللحية؟","title":"حكم قص اللحية بقصد الزينة","answer":"الجواب: لا يجوز القص منها، ولا النتف منها مطلقًا، لقوله ﷺ: قصوا الشوارب، وأعفوا اللحى؛ خالفوا المشركين اللفظ الآخر: قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين اللفظ الثالث: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس. فالأحاديث الصحيحة كلها دالة على وجوب إعفائها، وتوفيرها، والحذر من جزها، وقصها ولو زعم أنه يعدلها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11681/حكم-قص-اللحية-بقصد-الزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52511.mp3","categories":["سنن الفطرة"]},{"id":13674,"question":"السائلة في آخر أسئلتها تقول: هل من السنة عند الإفطار، أو إفطار الصائم أن يأكل تمرات، ويشرب الماء، ثم يقوم ليصلي المغرب، ثم بعد ذلك يأكل ما شاء من الطعام والشراب؟","title":"كيفية الجمع بين الإفطار وصلاة المغرب","answer":"الجواب: نعم؛ لأن هذا هو الذي يمكن فيه الجمع بين المصالح، فيبادر بالفطور على ما يسر الله من رطب، أو تمر، أو ماء، ثم يذهب إلى الصلاة مع الجماعة؛ حتى لا تفوته صلاة الجماعة، ثم يرجع ويتعشى، ما فيه بأس، هكذا. أما لو كانوا جماعة في سفر مثلًا، فلهم أن يأكلوا، ويتعشوا، ثم يصلوا، وإن أخروا العشاء، وقدموا الصلاة بعدما أفطروا؛ فلا بأس، أما في المدن والقرى فإن الإنسان يتناول ما يسر الله من الفطور، ثم يذهب إلى الصلاة حتى لا تفوته صلاة الجماعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12020/كيفية-الجمع-بين-الافطار-وصلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52916.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":13749,"question":"آخر سؤال له عن حلق اللحية، يقول: ما حكم حلق اللحية؟ وهل تربيتها واجبة، أم هو من السنة؟ جزاكم الله خيرًا.","title":"حكم حلق اللحية وتربيتها","answer":"الجواب: اللحية تربيتها، وإعفاؤها، وتوفيرها أمر واجب، وليس له قصها، ولا حلقها، بل الواجب توفيرها، وإعفاؤها؛ لقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وقوله ﷺ: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وقوله ﷺ: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس. فالأحاديث الصحيحة توجب على المؤمن أن يعفي اللحية، ويوفرها طاعة لله وللرسول، ويحذر قصها، أو حلقها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12111/حكم-حلق-اللحية-وتربيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48118.mp3","categories":["سنن الفطرة"]},{"id":13832,"question":"في ثاني أسئلته يقول: البعض من الناس يقولون: بأن المقصود باللحية هو الشعر النابت على الذقن، أما ما يوجد على الخدين فليس من اللحية، فهل هذا صحيح؟","title":"هل الشعر النابت على الخدين من اللحية؟","answer":"الجواب: اللحية ما نبت على الخدين والذقن، هذا هو الصحيح، اللحية: هي الشعر الذي ينبت على الخدين والذقن، هكذا قال أئمة اللغة، كصاحب القاموس وصاحب اللسان وغيرهما، قالوا: اللحية: ما نبت على الخدين والذقن، وهم أعلم بلغة العرب. نعم.","link":"https://binbaz.org.sa/fatwas/12207/هل-الشعر-النابت-على-الخدين-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53714.mp3","categories":["سنن الفطرة"]},{"id":13835,"question":"في ثاني أسئلته يقول: البعض من الناس يقولون: بأن المقصود باللحية هو الشعر النابت على الذقن، أما ما يوجد على الخدين فليس من اللحية، فهل هذا صحيح؟","title":"هل الشعر النابت على الخدين من اللحية؟","answer":"الجواب: اللحية ما نبت على الخدين والذقن، هذا هو الصحيح، اللحية: هي الشعر الذي ينبت على الخدين والذقن، هكذا قال أئمة اللغة، كصاحب القاموس وصاحب اللسان وغيرهما، قالوا: اللحية: ما نبت على الخدين والذقن، وهم أعلم بلغة العرب. نعم.","link":"https://binbaz.org.sa/fatwas/12207/هل-الشعر-النابت-على-الخدين-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53714.mp3","categories":["سنن الفطرة"]},{"id":13998,"question":"أيضًا يقول: إذا نام الإنسان وحلم في الليل وأصبح على جنابة وأراد أن يحلق ذقنه أو يقص أظافره قبل أن يغتسل هل هذا حرام خاصة إذا لم يجد ماءً عند قيامه من النوم؟","title":"حكم تقليم الأظافر وحلق اللحية للجنب","answer":"الجواب: إذا احتلم المؤمن إذا احتلم الإنسان في الليل أو في النهار ورأى المني خرج منه المني فإنه يغتسل وجوبًا، عليه الاغتسال من الجنابة كما لو جامع أهله، سواء كان نومه ليلًا أو نهارًا إذا رأى المني، أما إذا احتلم أنه يأتي المرأة، ولكن ما رأى منيًا فليس عليه غسل؛ لأن النبي ﷺ لما سئل عن ذلك قال: إذا رأت الماء، سألته أم سليم عن ذلك وقالت: «يا رسول الله! إن الله لا يستحي من الحق، هل على المرأة من غسل إذا هي احتلمت؟ قال النبي ﷺ: نعم، إذا هي رأت الماء يعني: المني.\nفدل ذلك على أن من لم ير الماء سواء كان رجلًا أو امرأة فإنه لا غسل عليه.\nولا بأس أن يقلم أظفاره ويقص شاربه ويحلق عانته قبل الغسل لا حرج في ذلك، سواء فعله قبل الغسل أو بعده لا يضر، تقليم أظفاره حلق عانته -وهي الشعرة- قص شاربه نتف إبطه لا يضر ولو قبل الغسل.\nأما حلق اللحية فلا يجوز مطلقًا لا قبل الغسل ولا بعده، حلق اللحية حرام منكر، الواجب إعفاؤها وإكرامها وتوفيرها، وليس للمسلم أن يحلق لحيته، يقول النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، ويقول عليه الصلاة والسلام: جزوا الشوارب وأرخوا اللحى خالفوا المجوس.\nوالخلاصة: أن اللحية يجب توفيرها وإعفاؤها وإرخاؤها ولا يجوز أبدًا حلقها ولا تقصيرها، وما يفعله الناس اليوم ما يفعله بعض الناس اليوم منكر لا ينبغي التأسي بهم في ذلك ولا الاغترار بهم، بل هذا منكر لا يجوز فعله، نسأل الله للجميع العافية والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/12417/حكم-تقليم-الاظافر-وحلق-اللحية-للجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54003.mp3","categories":["سنن الفطرة"]},{"id":14088,"question":"رسالة وصلت إلى البرنامج من الإخوة المستمعين: حمزة وحسين عبودة وحسن موسى الكميلة من قبائل عرب محافظة مرسى مطروح جمهورية مصر العربية، الإخوة يسألون في رسالتهم عن ختان الأولاد كيف يكون؟ وجهوا الناس حول هذا الموضوع لو تكرمتم شيخ عبد العزيز .","title":"كيفية الختان وحكمه","answer":"الجواب: الختان سنة مؤكدة، وذهب بعض أهل العلم إلى وجوبه كما قال ابن عباس وجماعة من أهل العلم أنه واجب في حق الرجال؛ لقول النبي ﷺ: الفطرة خمس يعني: السنة خمس: الختان، والاستحداد، وقص الشارب، وقلم الظفر، ونتف الإبط.\nفالختان من آكد السنن، وهو قطع القلفة التي على رأس الذكر؛ حتى تخرج الحشفة التي هي طرف الذكر وتبرز، وهي قلفة معروفة يعرفها الختانون، تقطع في حال الصغر أفضل؛ لأن قطعها في حال الصغر أسهل، ولا يجوز تأخير ذلك إلى أن يبلغ، بل يجب المبادرة بذلك قبل أن يبلغ، وكلما كان في حال الصغر في حال الرضاع أو أول الولادة في اليوم السابع أو بعده، كلما كان في حال الصغر فهو أسهل.\nوهي سنة مؤكدة، وذهب بعض أهل العلم إلى وجوب ذلك في حق الرجال، وهي سنة في حق النساء أيضًا إذا تيسر الخاتن الذي يعرف ذلك، أو الخاتنة التي تعرف ذلك، فهي سنة في حق النساء أيضًا، لكنها في حق الرجال آكد، ولهذا ذهب بعض أهل العلم إلى وجوبها في حق الرجال، فينبغي لأهل الإسلام أن يحافظوا على ذلك، وأن يحرصوا على ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12544/كيفية-الختان-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61011.mp3","categories":["سنن الفطرة"]},{"id":14229,"question":"المستمع حسين صالح العويدي الحارثي بعث يسأل ويقول: ما هي السنة في طول اللحية؟ ودليل ذلك؟ وهل من قصر لحيته يعتبر عاصيًا؟ وهل هي من المعاصي الكبيرة؟ أو من الصغائر؟وتعليقكم على هذا بكل وضوح، جزاكم الله خيرًا.","title":"ما السنة في اللحية؟ وهل حلقها من الكبائر؟","answer":"الجواب: اللحية يجب إعفاؤها وتوفيرها وليس لذلك حد في أصح قولي العلماء، بل الواجب إعفاؤها وإرخاؤها وتوفيرها، لما ثبت في الصحيحين عن النبي ﷺ أنه قال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وفي اللفظ الآخر: قصوا الشوارب ووفروا اللحى خالفوا المشركين، وفي صحيح مسلم عن أبي هريرة  عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحىى خالفوا المجوس، ولم يحدد حدًا عليه الصلاة والسلام، فدل ذلك على أن الواجب إرخاؤها وتوفيرها وعدم قصها، لا يجوز قصها ولا حلقها ولو طالت ليس له قصها وليس له حلقها عملًا بهذه الأحاديث الثابتة عن رسول الله عليه الصلاة والسلام؛ ولأن في ذلك مخالفة لأهل الشرك وبعدًا عن مشابهة النساء.\nأما ما روى الترمذي رحمه الله عن أبي هريرة : أن النبي عليه السلام كان يأخذ من لحيته من طولها وعرضها فهو حديث غير صحيح عند أهل العلم وفي إسناده متهم بالكذب وهو عمر بن هارون البلخي، فهو حديث باطل ليس بصحيح عن رسول الله عليه الصلاة والسلام، ومع بطلانه فهو مخالف للأحاديث الصحيحة التي ذكرناها آنفًا، فلا يجوز التعويل عليه ولا التشبث به.\nوأما ما ثبت عن ابن عمر رضي الله عنهما أنه كان يأخذ من لحيته في الحج والعمرة من طولها ما زاد على القبضة ويتأول قوله تعالى: ثُمَّ لْيَقْضُوا تَفَثَهُمْ [الحج:29]، فهذا من رأيه واجتهاده، كان يقبض عليها فما خرج من بعد القبضة من أسفل اليد قصه في حجه وعمرته ويرى أن ذلك من تأويل قوله تعالى: ثُمَّ لْيَقْضُوا تَفَثَهُمْ [الحج:29]، وهذا ليس بصحيح؛ لأنه مخالف للأحاديث الصحيحة والله يغفر له  هذا اجتهد فيه  والمعول على السنة على كلام النبي ﷺ وما عارض كلام النبي ﷺ لا يعول عليه، وقصارى ذلك أن يقال: عفا الله عنه اجتهد فأخطأ والله يعفو عنه. نعم.\nالمقدم: يسأل سماحة الشيخ: هل الأخذ منها أو حلقها أو تقصيرها يعتبر من الصغائر أو من الكبائر؟\nالشيخ: هو معصية لله عز وجل أما كونه من الكبائر محل نظر، لكنه من المعاصي التي حرمها الله جل وعلا ونهى عنها نبيه ﷺ، أما كون ذلك من الكبائر فقد يقال: إنه من الكبائر لأنه تشبه بأهل الشرك والنبي عليه السلام قال: من تشبه بقوم فهو منهم، وهذا وعيد عظيم وقد يقال: إنها من الصغائر لأنه لم يرد فيها وعيد ولا لعن والكبيرة عند العلماء ما ورد فيها وعيد بالعذاب أو جاء فيها لعن أو حد في الدنيا.\nفالحاصل: أنها محتملة أن تكون كبيرة ومحتمل أن تكون صغيرة، ليس هناك دليل واضح فيما أعلم يقتضي أنها كبيرة، فالواجب طاعة الله ورسوله سواء كانت المعصية كبيرة أو صغيرة يجب الحذر من معصية الله سبحانه وتعالى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12686/ما-السنة-في-اللحية-وهل-حلقها-من-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48605.mp3","categories":["سنن الفطرة"]},{"id":14376,"question":"يقول السائل (ن. ح. م): هل الصلاة لا تصح إذا لم يزِل المسلم أو المسلمة شعر الإبط والعانة؟أفيدونا بذلك.","title":"هل من شروط الصلاة إزالة شعر الإبط والعانة؟","answer":"الجواب: الصلاة صحيحة، ليس من شرطها زوال الإبط والعانة، لكن سنة للإنسان أن يتعاهد عانته وإبطه، وألا يتركها أكثر من أربعين، يقول أنس : «وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة، ألا نترك ذلك أكثر من أربعين ليلة» وفي لفظ: «وقّت لنا رسول الله ﷺ ذلك».\nفالسنة للمؤمن أن يتعاهدها قبل كمال الأربعين، نعم.","link":"https://binbaz.org.sa/fatwas/12857/هل-من-شروط-الصلاة-ازالة-شعر-الابط-والعانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55119.mp3","categories":["سنن الفطرة","مسائل متفرقة في الصلاة"]},{"id":14628,"question":"هذه رسالة وصلت إلى البرنامج من الطائف، مستشفى الملك فيصل، وباعثها المستمع أحمد حامد أحمد سوداني، الأخ أحمد يقول: لاحظت بعض الإخوة المصلين يستعملون السواك خلال وقوفهم للصلوات، ما حكم التسوك في مثل هذا الموضع، أليس من المستحب التسوك قبل الصلاة وقبل الوضوء؟","title":"حكم السواك عند القيام للصلاة","answer":"الجواب: يستحب السواك عند الوضوء عند المضمضة، ويستحب السواك أيضًا عند الدخول في الصلاة قبل أن يكبر للإحرام يستاك، ثم يكبر، سواء كان إمامًا أو مأمومًا أو منفردًا؛ لقول النبي ﷺ: لولا أن أشق على أمتي لأمرتهم بالسواك مع كل وضوء وفي اللفظ الآخر: مع كل صلاة فدل ذلك على أنه يستحب السواك عند الوضوء وعند الصلاة فرضًا ونفلًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13118/حكم-السواك-عند-القيام-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62610.mp3","categories":["سنن الفطرة"]},{"id":14630,"question":"هذه رسالة وصلت إلى البرنامج من الطائف، مستشفى الملك فيصل، وباعثها المستمع أحمد حامد أحمد سوداني، الأخ أحمد يقول: لاحظت بعض الإخوة المصلين يستعملون السواك خلال وقوفهم للصلوات، ما حكم التسوك في مثل هذا الموضع، أليس من المستحب التسوك قبل الصلاة وقبل الوضوء؟","title":"حكم السواك عند القيام للصلاة","answer":"الجواب: يستحب السواك عند الوضوء عند المضمضة، ويستحب السواك أيضًا عند الدخول في الصلاة قبل أن يكبر للإحرام يستاك، ثم يكبر، سواء كان إمامًا أو مأمومًا أو منفردًا؛ لقول النبي ﷺ: لولا أن أشق على أمتي لأمرتهم بالسواك مع كل وضوء وفي اللفظ الآخر: مع كل صلاة فدل ذلك على أنه يستحب السواك عند الوضوء وعند الصلاة فرضًا ونفلًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13118/حكم-السواك-عند-القيام-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62610.mp3","categories":["سنن الفطرة"]},{"id":14847,"question":"اللحية هل هي سنة واجبة يجب المحافظة على إعفائها، أم هي سنة مستحبة لا يعاقب على تركها؟","title":"ما حكم إعفاء اللحية؟","answer":"الجواب: اللحية فريضة؛ لا يجوز تعرضها لا بحلق ولا بقص، يجب إعفاؤها، وإكرامها وتوفيرها وإرخاؤها، سنة من جهة الشرع، تسمى سنة من جهة أنها مشروعة، وتسمى واجبة؛ لأن الرسول أمر بها، وفرضها -عليه الصلاة والسلام-، قال -عليه الصلاة والسلام-: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وقال: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وقال -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس هذه كلها أحاديث صحيحة عن النبي ﷺ، فالواجب على المسلم إعفاؤها وإكرامها وتوفيرها، ولا يجوز له قصها، ولا حلقها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13347/ما-حكم-اعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64404.mp3","categories":["سنن الفطرة"]},{"id":15234,"question":"وردتنا من المدينة المنورة رسالة من المستمع (م. د) يقول فيها: فضيلة الشيخ عبدالعزيز بن باز -وفقه الله وأمد في عمره على زود عمل صالح-.السلام عليك ورحمة الله وبركاته، وبعد:يقولون أو يقول بعض إخواننا: إن اللحية سنة، يثاب فاعلها، ولا يعاقب تاركها، هل هذا القول صحيح أم لا؟","title":"هل اللحية سنة، يثاب فاعلها، ولا يعاقب تاركها؟","answer":"الجواب:  الذي ثبت في الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- هو أن اللحية يجب توفيرها وإعفاؤها؛ لأن الأصل في الأوامر من الله -جل وعلا-، ومن رسوله ﷺ الأصل فيها الوجوب والفرضية، هذا هو الأصل، والقول بأنها سنة لا يعاقب تاركها يحتاج إلى دليل، الرسول ﷺ أمرنا أن نتبعه، وأن نمتثل أمره، والله  فوق ذلك أمرنا باتباع الرسول ﷺ وطاعته، وقال: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59] وقال: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63] فتوعدهم، توعد من خالف أمره بأن تصيبه فتنة وهي الشرك والعياذ بالله، أو يصيبه عذاب أليم بسبب المخالفة. وقد قال -عليه الصلاة والسلام-: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين رواه الشيخان البخاري ومسلم في الصحيحين، وقال أيضًا: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس خرجه مسلم في صحيحه، وفي لفظ: وفروا اللحى وفي لفظ: أرخوا اللحى فهذه أوامر تدل على وجوب إرخاء اللحى وإعفائها وتوفيرها. فلا يجوز لأحد أن يخالف هذه الأوامر بغير حجة، بل يجب عليه التسليم لها، والأخذ بها، والحذر من عصيان الرسول -عليه الصلاة والسلام-، فإن في عصيانه الشر والعاقبة الوخيمة. أما ما رواه الترمذي من حديث أبي هريرة  : أن النبي ﷺ كان يأخذ من لحيته من طولها وعرضها فهذا عند أهل العلم خبر لا يصح ولا يثبت عن النبي ﷺ؛ لأنه من رواية عمر بن هارون البلخي، وهو متهم بالكذب، حديثه لا يعول عليه ولا يثبت ولا يعتبر، والأحاديث الصحيحة الثابتة كلها تدل على وجوب إعفاء اللحى وتوفيرها وإرخائها. فالواجب على كل مسلم أن يعظم أمر الله ورسوله، وأن يحذر ما نهى الله عنه ورسوله، والقول بأن اللحية سنة حسب الاصطلاح يجوز فعلها وتركها يعني: يثاب فاعلها، ولا يعاقب تاركها، هذا أمر اصطلاحي، وعلى قائله إقامة الدليل، وهو على خطر من عصيان الرسول -عليه الصلاة والسلام-، فالواجب الحذر. والصواب: أن إعفاءها واجب، وأن حلقها محرم، هذا هو الصواب، نعم.","link":"https://binbaz.org.sa/fatwas/13741/هل-اللحية-سنة-يثاب-فاعلها-ولا-يعاقب-تاركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67305.mp3","categories":["سنن الفطرة"]},{"id":15283,"question":"سؤالها الآخر تقول: ما الحكم فيمن يضع قصاصات الأظافر والمتساقط من الشعر في القمامة؟ وهل لا بد من دفنها؟","title":"حكم إلقاء قصاصات الأظفار والشعر في القمامة","answer":"الجواب: لا، لا حرج، لا بأس، إن دفنها فلا بأس، وإن وضعها مع القمامة فلا بأس، ليس لها حرمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13800/حكم-القاء-قصاصات-الاظفار-والشعر-في-القمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68108.mp3","categories":["سنن الفطرة"]},{"id":15725,"question":"المقدم:ماذا عن الختان سماحة الشيخ؟","title":"بعض أحكام الختان","answer":"الجواب: الختان مشروع، سنة مؤكدة، وليس له حد محدود، سواء في السابع أو بعده قبل البلوغ، هذا هو الأفضل قبل البلوغ؛ لأنه إذا كبر قد يضره الختان، لكن إذا كان في الصغر أسهل وأيسر، وهو مشروع للجميع في حق الرجال والنساء جميعًا، الختان مشروع للجميع؛ يقول النبي ﷺ: الفطرة خمس: الختان، والاستحداد، وقص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة. فالختان سنة عند جمهور أهل العلم، وقال بعضهم: بالوجوب، قال بعض أهل العلم: إنه يجب، والمشهور عند العلماء أنه سنة مؤكدة في حق الجميع، وقال بعضهم: يجب على الرجل دون المرأة، سنة في حق المرأة، وواجب في حق الرجل، والأدلة تقتضي أنه سنة في حق الجميع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14286/بعض-احكام-الختان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70613.mp3","categories":["سنن الفطرة"]},{"id":15916,"question":"يقول: إنني أستعمل السواك عند كل صلاة، لكن ألاحظ أنه يخرج من أسناني دم في بعض الأحيان، فهل يؤثر ذلك على الوضوء والصلاة؟","title":"حكم الدم الخارج من الفم عند التسوك","answer":"الجواب: السواك سنة، وقربة للرجال والنساء جميعًا، السواك سنة للرجال والنساء، يقول النبي ﷺ: السواك مطهرة للفم، مرضاة للرب رواه النسائي بإسناد صحيح، عن عائشة -رضي الله عنها-، ويقول النبي ﷺ: لولا أن أشق على أمتي لأمرتهم بالسواك مع كل صلاة ويقول أيضًا -عليه الصلاة والسلام-: لولا أن أشق على أمتي لأمرتهم بالسواك مع كل وضوء وتقول عائشة -رضي الله عنها-: \"كان النبي ﷺ إذا دخل المنزل بدأ بالسواك\" -عليه الصلاة والسلام-، فالسواك سنة دائمًا، وسنة عند الوضوء، وعند الصلاة، فنوصي الجميع باستعماله، وهو من الأراك أطيب، من الأراك أحسن من غيره، يختار السواك اللين، الذي لا يتبحثر، ويتقطع في فمه، يحرص على النوع الطيب، الذي يدلك به الأسنان، وهو لا يتفتت، هذا هو السواك الطيب. وإذا خرج شيء من الأسنان من دم أو نحوه لا يضر، الشيء اليسير يعفى عنه، فإن كان كثيرًا تمضمض، وغسل ما خرج، أما إن كان قليل فالقليل يعفى عنه، إذا خرج من الأسنان دم يسير، يعفى عنه، قد يقع هذا، فيعفى عنه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا كان كثيرًا -سماحة الشيخ- يعيد الوضوء؟\nالشيخ: إذا كان كثيرًا يعيد الوضوء، هذا هو الأحوط له، أحسن، يعني: فيه خلاف بين العلماء، لكن إذا كثر جدًا يعيد الوضوء، وإن كان قليلًا، يتمضمض ويكفي، والحمد لله، وإن كان يسيرًا جدًا ما يحتاج المضمضة.\nالمقدم: بارك الله فيكم، هل تتفضلون بتحديد الكثرة سماحة الشيخ؟ الشيخ: الشيء اليسير عرفًا، مثل النقاط اليسيرة عرفًا يعفى عنها، أما الشيء يعده في نفسه كثير، يعتبره في نفسه كثيرًا، هذا يتمضمض منه، ويتوضأ إذا تيسر احتياطًا، خروجًا من خلاف العلماء؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك وقوله ﷺ: من اتقى الشبهات فقد استبرأ لدينه وعرضه؛ لأن كثيرًا من العلماء يقولون: إذا خرج الدم الكثير ينقض الوضوء، ويحتجون بحديث المستحاضة الذي قال لها: توضئي لكل صلاة لكن حديث المستحاضة في خروج الدم من الفرج، هذا ناقض بلا خلاف، إذا خرج من الفرج ناقض بالإجماع، لكن الخلاف إذا كان الدم من الرجل، من الرأس، من الفم، هذا محل الخلاف، من توضأ هو أحوط، إذا كان الدم كثيرًا أحوط، ومن لم يتوضأ فنرجو أن طهوره صحيح، لكن الوضوء أحوط وأحسن.\nأما الشيء اليسير، الجرح اليسير، من الأسنان، من الأنف، شيء يسير هذا يعفى عنه، والحمد لله. المقدم: بارك الله فيكم، وجزاكم عن الإسلام والمسلمين خيرًا.","link":"https://binbaz.org.sa/fatwas/14510/حكم-الدم-الخارج-من-الفم-عند-التسوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_708/nour_70807.mp3","categories":["سنن الفطرة"]},{"id":15919,"question":"ننتقل بعد هذا إلى السؤال الثاني لأخينا من دمشق (ع. ع) يقول: هل إعفاء اللحية، وإرسالها واجب أم فرض أم سنة لا يعاقب تاركها، ولكن يثاب فاعلها؟ وما هي الأدلة؟جزاكم الله خيرًا.","title":"حكم إعفاء اللحية وأدلة ذلك","answer":"الجواب: إعفاء اللحية من أهم الفرائض، واجب على الصحيح من أقوال أهل العلم؛ لأن الرسول ﷺ قال: قصوا الشوارب، واعفوا اللحى، خالفوا المشركين متفق على صحته عند البخاري ومسلم -رحمة الله عليهما-، وقال أيضًا -عليه الصلاة والسلام-: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين رواه البخاري وغيره، وقال أيضًا -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس رواه مسلم في الصحيح، فهو ﷺ قال: اعفوا أرخوا وفروا. وهذا كله يدل على الوجوب؛ لأن الأوامر من الرسول ﷺ يجب أن تحمل على الوجوب، ويجب أن نتمسك بها، إلا بدليل يدل على أنها للاستحباب، ولم يرد فيما نعلم من الشرع ما يدل على الاستحباب، والله يقول سبحانه: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول: قُلْْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النور:54]، فعلينا أن نطيع الرسول ﷺ وأن نأخذ بما أتانا به -عليه الصلاة والسلام-، ومن قال: إنها سنة فقط فعليه الدليل، الأوامر للوجوب هذا هو الأصل إلا بدليل يدل على الاستحباب.\nأما ما رواه الترمذي -رحمه الله- أنّ النبي ﷺ \"كان يأخذ من لحيته من طولها وعرضها\" فهو حديث غير صحيح كما بين أهل العلم، ولو صح لقلنا به، وأخذنا به، ولكنه لا يصح؛ لأن في إسناده عمر بن هارون البلخي، وهو متهم بالكذب؛ فلهذا أعرض عنه أهل العلم، والأحاديث الصحيحة هي التي بينا، يقول فيها النبي ﷺ: قصوا الشوارب، وأعفوا اللحى، قصوا الشوارب، ووفروا اللحى، خالفوا المشركين، جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس. فنصيحتي لكل مسلم أن يتقي الله، وأن يوفر اللحية، وأن يعفيها طاعة لله ولرسوله -عليه الصلاة والسلام-، وحذرًا من مشابهة المشركين، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14514/حكم-اعفاء-اللحية-وادلة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_709/nour_70902.mp3","categories":["سنن الفطرة"]},{"id":15948,"question":"ما رأيكم في تخفيف اللحى وتقصيرها؟","title":"ما حكم تخفيف اللحية وتقصيرها؟","answer":"الجواب: يقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين ويقول -عليه الصلاة والسلام-: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين ويقول -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس كلها أحاديث صحيحة، فالواجب إكرام اللحية وإعفاؤها، وإرخاؤها، وعدم قصها، أو حلقها، يجب تركها وإعفاؤها وإرخاؤها؛ لأنها زينة الرجل، وهي سنة النبي ﷺ، كان يعفي لحيته -عليه الصلاة والسلام- ونهى الأمة عن قصها، وأمر بإعفائها وإرخائها وتوفيرها، فلا يجوز لأي مسلم أن يخالف ما شرع الله، ليس له حلقها، ولا قصها.\nبل الواجب عليه توفيرها وإرخاؤها امتثالًا لأمر الرسول ﷺ، وتأسيًا به -عليه الصلاة والسلام-، ومن المؤسف أن كثيرًا من الناس يعادي هذه اللحية، ويحاربها بالحلق والتقصير، وهذه مصيبة عظيمة وقعت في المسلمين، نسأل الله أن يمن عليهم بتركها، والحذر منها؛ لأنها مخالفة لشرع الله، ومجاهرة بالمعصية، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14554/ما-حكم-تخفيف-اللحية-وتقصيرها ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71007.mp3","categories":["سنن الفطرة"]},{"id":15949,"question":"سماحة الشيخ، هل تتفضلون بالتحديد الشرعي للحية؟","title":"حدود شعر اللحية","answer":"الجواب: بين أهل العلم أن اللحية ما نبت على الخدين والذقن، هذه اللحية، ما نبت على الخدين والذقن يقال لها: لحية، أما ما ينبت على الحلق فليس بلحية، وهكذا ما فوق العظم المحاذية للأذن هذا تبع الرأس ليس من اللحية، إنما اللحية ما نبت على الخدين تحت العظم الذي يحاذي الأذن وعلى الذقن الذي هو معروف، وهكذا ما ينبت تحت الشفه السفلى، ويقال له: العنفقة من اللحية، نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا: أخذ ما كان من تحت اللحية من جهة الحلق؟\nالشيخ: ما كان على الحلق ليس من اللحية. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14556/حدود-شعر-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71008.mp3","categories":["سنن الفطرة"]},{"id":16074,"question":"من سلطنة عمان رسالة بعثت بها إحدى الأخوات من هناك تقول المرسلة (م. م)، لها سؤالان.في سؤالها الأول تقول: سمعت بعض الناس يقولون: إنه عند الانتهاء من قص الأظافر لابد من أخذها، ودفنها في مكان، وقراءة بعض السور عليها مثل الإخلاص، والمعوذتين، وعدم رميها، فما حكم ذلك؟ جزاكم الله خيرًا.","title":"حكم دفن الأظافر بعد قراءة القرآن عليها","answer":"الجواب: هذا شيء لا أصل له، إذا قص الإنسان أظفاره يرميها، ولا بأس، ولا حاجة إلى دفنها، ولا قراءة قرآن عليها، كل هذا خرافة لا أصل لها، ولا أساس لها، متى قص الإنسان أظفاره رجل، أو امرأة؛ فلا حرج في إلقائها في أي مكان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14707/حكم-دفن-الاظافر-بعد-قراءة-القران-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80302.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":16101,"question":"تقول السائلة: يا سماحة الشيخ! إذا طلبت الزوجة من زوجها أن يقوم بتقصير شعر الذقن؛ تزينًا لها، هل يجيبها الزوج في ذلك؟","title":"هل يستجاب للزوجة في تقصير اللحية؟","answer":"الجواب: ليس له أن يجيبها، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق؛ إنما الطاعة في المعروف والنبي ﷺ يقول: قصوا الشوارب، ووفروا اللحى (وفروا) أعفوا اللحى أرخوا اللحى هكذا أمر النبي ﷺ يعصى النبي ﷺ وتطاع الزوجة؟ لا، لا يعصى النبي ﷺ بل يجب طاعة النبي ﷺ وعصيان الزوجة، وغيرها، لا يطاع المخلوق في المعصية، الواجب توفير اللحى، وإكرامها،  نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14745/هل-يستجاب-للزوجة-في-تقصير-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57921.mp3","categories":["سنن الفطرة"]},{"id":16237,"question":"له سؤال آخر يقول: ما حكم تصليح اللحية من قصها، وتدويرها من أقصى الرقبة؟ جزاكم الله خيرًا.","title":"حكم حلق اللحية والأخذ منها","answer":"الجواب: اللحية يجب توفيرها، اللحية يجب توفيرها وإرخاؤها، وعدم قصها، أو حلقها، لقول النبي ﷺ في الحديث الصحيح: قصوا الشوارب، وأعفوا اللحى؛ خالفوا المشركين متفق على صحته، وفي لفظ آخر يقول ﷺ: قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين رواه البخاري في صحيحه -رحمه الله- وفي لفظ آخر يقول ﷺ: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس رواه مسلم في صحيحه. فقوله ﷺ: أرخوا وقوله: وفروا وقوله: أعفوا كل هذا يدل على أنه لا يجوز التعرض لها، لا بقص، ولا بحلق، بل يجب أن توفر على حالها، وترخى، وتعفى، فلا يقص منها، ولا يحلق منها، ولا تحلق كلها، لا يجوز حلقها، ولا قصها، بل يجب توفيرها، وإرخاؤها، وإبقاؤها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14935/حكم-حلق-اللحية-والاخذ-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80706.mp3","categories":["سنن الفطرة"]},{"id":16279,"question":"تسأل عن الطفل الذي مات ولم يختن، تجادل أناسًا فقيل: يختن، وقيل: لا داعي للختان، ما هو توجيهكم؟","title":"حكم ختان المولود إذا مات ولم يختن","answer":"الجواب: إذا مات الطفل، ولم يختن؛ فلا حاجة إلى ختانه، ولا يجب ختانه، ولا يشرع بعد موته، والحمد لله، نعم، سنة فات محلها. نعم.  المقدم: الله المستعان، محلها الحياة؟ الشيخ: محلها الحياة، وقد أوجبه جمع من أهل العلم، وبكل حال لما توفي ما في حاجة إلى تختينه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14971/حكم-ختان-المولود-اذا-مات-ولم-يختن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75209.mp3","categories":["سنن الفطرة"]},{"id":16308,"question":"تقول: لقد سمعت أن رمي بقايا شعر الرأس والأظافر غير جائز، وأنه يجب دفنها، وضحوا لي هذا الأمر جزاكم الله خيرًا.","title":"حكم دفن بقايا الشعر والأظافر","answer":"الجواب: لا يجب دفن ما يقلم من الأظفار، أو يقطع من الشعر، لا يجب دفنه، إذا ألقي في القمامة لا بأس، ولا حرج، إن دفنه؛ فلا حرج، وإن ألقاه في القمامة؛ فلا حرج، الأمر واسع، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15007/حكم-دفن-بقايا-الشعر-والاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81008.mp3","categories":["سنن الفطرة"]},{"id":16352,"question":"من الأخ أبو عبدالعزيز رسالة وضمنها جمعًا من الأسئلة في أحدها يقول: أسأل سماحتكم عن حكم صيام من لم يتسحر، سواء كان صيامه تطوعًا، أو فرضًا؟ جزاكم الله خيرًا.","title":"حكم صيام من ترك السحور","answer":"الجواب: لا حرج فيه، صومه صحيح، وإن لم يتسحر، لكنه ترك السنة.. السنة أن يتسحر؛ لقول النبي ﷺ: تسحروا فإن في السحور بركة في الفرض والنفل، السنة أن يتسحر، كان النبي يتسحر -عليه الصلاة والسلام- فالسنة أن يتسحر بما تيسر من تمر، أو أي طعام، أو فاكهة، يتسحر بما تيسر، هذا هو السنة يستعين بذلك على صيامه، فإن صام ولم يتسحر؛ فلا حرج صومه صحيح، واصل النبي ﷺ بجماعة من الصحابة، يومين من غير سحور. نعم. بغير سحور، ولا فطور. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15046/حكم-صيام-من-ترك-السحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71415.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":16367,"question":"سؤاله الأخير يقول: هل يجوز أخذ شيء من اللحى، ولو من باب التهذيب؟","title":"حكم الأخذ من اللحية","answer":"الجواب:  ظاهر الأحاديث الصحيحة المنع من ذلك، وأنه لا يجوز التعرض للحية بشيء، لما ثبت في الصحيحين عن ابن عمر -رضي الله عنهما- عن النبي ﷺ أنه قال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين وإعفاؤها تركها على حالها وإرخاؤها. وفي اللفظ الآخر يقول ﷺ: قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين خرجه البخاري في صحيحه، وفي رواية مسلم يقول ﷺ: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس.  وهذه الألفاظ كلها واضحة في وجوب توفير اللحية، وإعفائها، وإرخائها، وعدم التعرض لها بشيء؛ ولأن التعرض لها يفضي إلى التساهل بهذا الأمر، فالواجب توفيرها، وإرخاؤها، وإعفاؤها؛ عملًا بهذه الأحاديث الصحيحة عن رسول الله، عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15082/حكم-الاخذ-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81103.mp3","categories":["سنن الفطرة"]},{"id":16420,"question":"بالنسبة لشعر الإبط، كم هي المدة التي يجب على المرء أن يقضيها، ثم يعاود تنظيف الإبط من الشعر؟","title":"المدة التي يجب فيها نتف الإبط","answer":"الجواب: يقول أنس  فيما رواه مسلم في الصحيح: \"وقت لنا في قص الشارب، وحلق العانة، ونتف الإبط، وقلم الأظفار ألا نترك ذلك أكثر من أربعين ليلة\" ورواه أحمد، وجماعة بلفظ: \"وقت لنا رسول الله ﷺ في ذلك أربعين ليلة\". فالحد النهائي أربعون ليلة فقط، فإذا قارب الوقت؛ يأخذ شاربه، يأخذ أظفاره، ينتف إبطه، أو يزيله بغير النتف بالأدوية، يقص شاربه، هذه السنة، وإذا تعاهده الشارب قبل الأربعين؛ لأنه يطول، بعض الناس يطول شاربه بسرعة، إذا تعاهده ولو قبل الأربعين، تعاهده وهو لعشرين يومًا، أو خمسة وعشرين يومًا يكون أفضل، لقوله ﷺ: قصوا الشوارب وقوله ﷺ: من لم يأخذ من شاربه؛ فليس منا فإذا تعاهدها قبل الأربعين الشارب والإبط والعانة والأظفار فهو طيب، لكن لا يؤخر أكثر من أربعين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15159/المدة-التي-يجب-فيها-نتف-الابط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81207.mp3","categories":["سنن الفطرة"]},{"id":16595,"question":"ما حكم حلق اللحية، هل هو محرم، وما حكم القص أيضًا؟","title":"حكم حلق اللحية أو تخفيفها","answer":"الجواب: اللحية يجب توفيرها، وإرخاؤها، وإعفاؤها، ولا يجوز حلقها، ولا قصها لقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى؛ خالفوا المشركين وقوله ﷺ: جزوا الشوارب، وأرخوا اللحى؛ خالفوا المجوس وقوله ﷺ: قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين. فالواجب على المسلم أن يوفرها، وألا يحلقها، ولا يقصها؛ طاعة لله ولرسوله -عليه الصلاة والسلام- وحذرًا من مشابهة أعداء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15331/حكم-حلق-اللحية-او-تخفيفها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81712.mp3","categories":["سنن الفطرة"]},{"id":16826,"question":"السؤال الأخير الذي يسأله أخونا همام، يقول: هل يجوز الأخذ من اللحية، وتهذيبها بحيث تصبح نصف قبضة؟","title":"حكم الأخذ من اللحية وتهذيبها","answer":"الجواب:  لا يجوز ذلك، بل يجب تركها، وإعفاؤها على حالها، يقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى؛ خالفوا المشركين ولقوله ﷺ: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وفي اللفظ الآخر أرجو اللحى فهذا كله يدل على أنها لا يتعرض لها بشيء، لا بقص، ولا بتهذيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15581/حكم-الاخذ-من-اللحية-وتهذيبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76315.mp3","categories":["سنن الفطرة"]},{"id":17317,"question":"حدثونا لو تكرمتم عن حكم الإسلام في اللحية، هل هي فرض كما يقول بعض الناس؟","title":"ما حكم إعفاء اللحية؟","answer":"الجواب: نعم، إعفاء اللحية، وتوفيرها، وإرخاؤها فرض، هذا الذي دلت عليه سنة رسولنا -عليه الصلاة والسلام- يقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين ويقول -عليه الصلاة والسلام-: قصوا الشوارب ووفروا اللحى، خالفوا المشركين ويقول أيضًا -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس وكلها أحاديث صحيحة عن رسول الله، عليه الصلاة والسلام. وقد حكى أبو محمد بن حزم الإمام المشهور الظاهري، حكى إجماع أهل العلم على أن إعفاء اللحية، وقص الشارب فرض، قال: اتفق العلماء بأن قص الشارب، وإعفاء اللحية فرض. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16161/ما-حكم-اعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83305.mp3","categories":["سنن الفطرة"]},{"id":17433,"question":"يسأل عن حلق الشعر الذي في الحلق، هل هو من اللحية، أو لا؟","title":"جواز حلق الشعر النابت على الحلق","answer":"الجواب: شعر الحلق ليس من اللحية، اللحية ما نبت على الذقن، والخدين، هذه اللحية، اللحية: ما نبت على الخدين، والذقن كما في القاموس، ولسان العرب، وغيرهما، أما ما ينبت على الحلق؛ فليس من اللحية، ولا بأس بأخذه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16301/جواز-حلق-الشعر-النابت-على-الحلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83604.mp3","categories":["سنن الفطرة"]},{"id":17434,"question":"يسأل عن حلق الشعر الذي في الحلق، هل هو من اللحية، أو لا؟","title":"جواز حلق الشعر النابت على الحلق","answer":"الجواب: شعر الحلق ليس من اللحية، اللحية ما نبت على الذقن، والخدين، هذه اللحية، اللحية: ما نبت على الخدين، والذقن كما في القاموس، ولسان العرب، وغيرهما، أما ما ينبت على الحلق؛ فليس من اللحية، ولا بأس بأخذه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16301/جواز-حلق-الشعر-النابت-على-الحلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83604.mp3","categories":["سنن الفطرة"]},{"id":17899,"question":"أسألكم عن فضيلة السواك هل هي قبل الوضوء؟ أم بعد الوضوء؟","title":"مواطن يشرع فيها السواك","answer":"الجواب: السواك يشرع استعماله عند الوضوء في أول الوضوء وفي أول الصلاة هذا السنة، عند المضمضة وعند الإحرام. نعم.","link":"https://binbaz.org.sa/fatwas/16931/مواطن-يشرع-فيها-السواك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84608.mp3","categories":["سنن الفطرة"]},{"id":18348,"question":"سمعت بأن السواك حرام بالنسبة للنساء! هل هذا صحيح؟","title":"بطلان القول بتحريم السواك على النساء","answer":"الجواب: ليس بصحيح، السواك مشروع للجميع للرجال والنساء، عند الصلاة، وعند الوضوء، عند الدخول في الصلاة، عند الوضوء، عند دخول المنزل، عند تغير الفم، عند القيام من النوم مشروع..، يقول عليه الصلاة والسلام في الحديث الصحيح: السواك مطهرة للفم مرضاة للرب، ويقول عليه الصلاة والسلام: لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة، وفي اللفظ الآخر: مع كل وضوء، ولم يخص الرجال بل عم الأمة، فهو مشروع للرجال والنساء جميعاً، ولكن كثيرًا من الناس يقول على الله بغير علم ويكذب ولا يبالي، نسأل الله العافية. والواجب على المؤمن والمؤمنة الحذر مما حرم الله من الكذب، فلا يقول إنسان: هذا حرام وهذا حلال إلا عن دليل وعن بينة، ولا يجوز للمرأة أو الرجل أن يقول على الله بغير علم لا في السواك ولا في غير السواك، يقول سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33]، فجعل القول عليه بغير علم فوق الشرك، فوق المرتبة التي هي أعظم خطر وهو الشرك بالله . فالمقصود: أن القول على الله بغير علم له خطر عظيم حتى ذكره الله في هذه الآية فوق مرتبة الشرك؛ لأن الشرك قول على الله بغير علم، وأخبر في سورة البقرة أن الشيطان يأمر بذلك فقال سبحانه في الشيطان: إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169]، هكذا أخبر ، قبلها قوله تعالى: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:168-169]، فهذا هو أمر عدو الله يأمر الناس بأن يقولوا على الله بغير علم لما يترتب على ذلك من الضلال والإضلال والفساد الكبير، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17412/بطلان-القول-بتحريم-السواك-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86104.mp3","categories":["سنن الفطرة"]},{"id":18353,"question":"المضمضة والاستنشاق، هل تكون في آن واحد، أم كل على حدة؟","title":"كيفية المضمضة والاستنشاق","answer":"الجواب: السنة جميعًا، يتمضمض ويستنشق غرفة واحدة، هذا هو السنة في غرفة واحدة \"كان النبي ﷺ يتمضمض ويستنشق بغرفة واحدة ثلاث مرات\"، وإن أخذ لكل غرفة للمضمضة غرفة، وللاستنشاق غرفة فلا حرج.","link":"https://binbaz.org.sa/fatwas/17402/كيفية-المضمضة-والاستنشاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78317.mp3","categories":["سنن الفطرة"]},{"id":18703,"question":"هذا السائل (أ. أ) يقول في سؤاله: عملية تطهير الطفل الذي تجرى للأطفال هل صحيح بأن الذي لا يجري هذه العملية وهي التطهير لا تصح صلاته ولا يكتمل إسلامه؟","title":"حكم صلاة غير المختون","answer":"الجواب: ليس بصحيح، لكنه واجب تطهير الصبي وهو الختان، الرسول ﷺ قال: الفطرة خمس: الختان، والاستحداد، وقص الشارب، وقلم الظفر، ونتف الآباط وذهب جمع من أهل العلم إلى وجوب الختان؛ وذلك بقطع القلفة التي في طرف الذكر؛ لأنه قد يكون بعدها البول يتحجر فيها البول والوسخ. فالواجب قطعها قبل البلوغ في حال الصغر هذا الختان، وهو سنة بلا ريب، وذهب جمع من أهل العلم إلى وجوب ذلك، وأن الواجب قطع هذه القلفة حتى يبرز طرف الذكر، وحتى يسلم من وجود أشياء في هذه القلفة من الأوساخ والنجاسات، لكن صلاته صحيحة، لو بلغ ولم يختن صلاته صحيحة، وصومه صحيح، وقصاراها أنه أخطأ، وأنه غلط، وأنه عصى، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17824/حكم-صلاة-غير-المختون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78814.mp3","categories":["مسائل متفرقة في الصلاة","سنن الفطرة"]},{"id":18982,"question":"رسالة وصلت إلى البرنامج من الباكستان، وباعثها أحد الإخوة من هناك، وقع في نهاية رسالته، ولم يذكر اسمه صريحًا، أخونا له مجموعة من الأسئلة من بينها سؤال يقول: ما حد إعفاء اللحية، قال بعض علماء باكستان: إن اللحية يكفي منها ما يبدو على الوجه، بشرط ألا يظن به أنه إنما هو نتيجة عدم حلقها بضعة أيام، فهل هذا القول صحيح أم لا؟","title":"وجوب إعفاء اللحية وحدها","answer":"الجواب: ليس بصحيح، بل الواجب إعفاؤها وإرخاؤها وتوفيرها، كما أمر بهذا النبي -عليه الصلاة والسلام-، ففي الصحيحين عن عبد الله بن عمر -رضي الله تعالى عنهما- عن النبي ﷺ أنه قال: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وفي رواية البخاري: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وعند مسلم من حديث أبي هريرة  عن النبي -عليه الصلاة والسلام- أنه قال: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس فأمر بإرخاء اللحية، وأمر بإعفائها، وأمر بتوفيرها. فالواجب على المسلم أن يوفرها ويعفيها ويرخيها، ولا يأخذ منها شيئًا ولو طالت، هكذا أمره نبيه -عليه الصلاة والسلام-. وأما من تساهل فيها فلا ينبغي أن يقتدى به، ولا ينبغي أن يحتج به؛ لأنه عاصٍ والعاصي لا يقتدى به في المعصية، وأما ما ثبت عن ابن عمر -رضي الله تعالى عنهما- «أنه كان في الحج والعمرة يأخذ ما زاد على القبضة» يقبض عليها بيده فما زاد وخرج من تحت يده أخذه؛ فهذا وقع منه اجتهادًا منه ، والاجتهاد إذا خالف النص لا يقبل ولو من الصحابة، إذا خالف الاجتهاد النص، فالنص هو المعتبر. فالواجب على المسلم أن يعتمد على النص على قول النبي ﷺ وأن يعفي لحيته ويوفرها، ولا يأخذ منها شيئًا، لا في حج ولا في عمرة ولا في غيرهما؟ واللحية هي ما نبت من الشعر على الذقن والخدين، هذه اللحية الشعر النابت على الخدين والذقن يسمى لحية، هكذا قال أئمة اللغة كما في القاموس وفي لسان العرب. فعليك -يا أخي- أن تلزم إعفاءها وتوفيرها، وألا تخدع بقول من يتساهل في ذلك، رزق الله الجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، سدد الله خطاكم، ووفقكم إلى ما فيه مصلحة المسلمين، إنه على كل شيء قدير.","link":"https://binbaz.org.sa/fatwas/18139/وجوب-اعفاء-اللحية-وحدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92507.mp3","categories":["سنن الفطرة"]},{"id":19158,"question":"يسأل فيقول: هل أخذ الشعر من الوجه مثل أخذ شعر الخد وأعلى الحاجب للرجل فيه إثم؟ وجهونا جزاكم الله خيرًا.","title":"حكم أخذ الرجل من شعر الخدين والحاجب","answer":"الجواب: الخدين من اللحية لا يأخذهما، والحاجب لا يجوز أخذه لا من الرجال ولا من النساء، الرسول ﷺ لعن النامصة والمتنمصة، والنمص: أخذ شعر الحاجبين، فلا يجوز أخذ شعر الحاجبين لا من الرجل ولا من المرأة، وهكذا شعر الخدين، شعر الخدين تبع اللحية؛ لأن اللحية الشعر النابت على الخدين والذقن، والمرأة لا تأخذ الشعر الذي في وجهها إذا كان عاديًا ليس فيه تشويه، أما إذا كان فيه تشويه كاللحية لها أو الشارب أو شعر يشوه؛ لا مانع من إزالته. نعم. ليس من النمص. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18345/حكم-اخذ-الرجل-من-شعر-الخدين-والحاجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73713.mp3","categories":["سنن الفطرة"]},{"id":19391,"question":"هل إطالة الأظافر محرمة، وما حكم صلاة المرأة وأظافرها طويلة؟","title":"حكم إطالة الأظافر أكثر من أربعين يومًا","answer":"الجواب: الأظفار يجوز بقاؤها مدة أربعين يومًا، وهكذا الشارب، وهكذا الإبط، وهكذا العانة؛ لما ثبت من حديث أنس رضي الله عنه قال: وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة أن لا ندعها أكثر من أربعين ليلة وفي لفظ: وقت لنا النبي ﷺ. فإذا بلغ أربعين وجب عليه قص الشارب، قلم الظفر، نتف الإبط، حلق العانة، أما بقاء الظفر في أقل من ذلك فلا حرج إن شاء الله هكذا الشارب.. هكذا الإبط.. هكذا العانة. المقدم: جزاكم الله خيرًا، سماحة الشيخ بعض النساء يطلن أظافرهن لأشهر حتى يدهنها بأصبغة ملونة، ويعتبرن أن هذا من التجمل؟ الشيخ: لا يجوز هذا لا يجوز، إذا تمت أربعين وجب قلمها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18612/حكم-اطالة-الاظافر-اكثر-من-اربعين-يوما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74006.mp3","categories":["سنن الفطرة"]},{"id":19704,"question":"في شهر رمضان نُحضر السحور قبل الأذان بثلث أو بنصف ساعة، ويؤذن ونحن لم نتم السحور فنأكل وهو يؤذن، بعض الناس قال: الإمساك حين سماع الأذان، والبعض قال: إن أفضل وقت للسحور هو عند الأذان حتى يكون متأخراً، مع أننا لا نعلم هل الأذان يكون قبل طلوع الفجر بقليل أو مع طلوع الفجر، ما حكم ما فعلناه؟","title":"السنة تأخير السحور وتعجيل الفطور","answer":"الجواب: السنة تأخير السحور، إلى آخر الليل، لكن ينبغي أن يقدم قبل الأذان، حتى يفرغ المتسحر قبل الأذان والنبي ﷺ ثبت عنه أنه تسحر في آخر الليل، ثم قاموا إلى الصلاة بعد السحور، قاموا وسئل أنس عن ذلك، كم كان بين الأذان والسحور؟ قال: قدر خمسين آية، فالمقصود أن التأخير أفضل، لكن ينتهي قبل الأذان، فإن أكل وهو يؤذن فلا حرج، إذا لم يعلموا أن الصبح طلع، أما إذا علموا أن الصبح قد طلع، كالذي في الصحراء يرى الصبح، فإنه لا يأكل إذا طلع الصبح، ولو ما أذن، لأن العمدة على الصبح لأن الله قال جل وعلا: وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود من الفجر، يعني من الصبح، فإذا كان لا يعلم هل أذن الصبح أم لا، فله أن يشرب أو يأكل مع الأذان لكن ترك هذا أحوط وأولى، وإن تقدم أن يكون السحور قبل الأذان هذا هو الأفضل والأولى، احتياطاً للصوم وبعداً عن الشك، والرسول ﷺ يقول: دع ما يريبك إلى ما لا يريبك.","link":"https://binbaz.org.sa/fatwas/25321/السنة-تاخير-السحور-وتعجيل-الفطور","audio":"https://files.zadapps.info/binbaz.org.sa/069016.mp3","categories":["سنن الفطرة","مستحبات الصيام"]},{"id":19708,"question":"هذه رسالة وردتنا من خميس مشيط من حسين سليمان... المالكي، يقول في رسالته: يوجد أحدى الممرضات بمستوصف أحد البوادي تقوم بعلمية الختان للأولاد، ولاسيما شباب أعمارهم تزيد على السابعة عشرة، فهل يجوز ذلك منها أم لا؟","title":"هل يجوز للممرضة التي تقوم بالختانة أن تختن لمن كان كبيرا","answer":"الجواب:\nهذا عمل غريب ، لا شك أن هذا لا يجوز، وأن الواجب أن يتولاه الرجال ، يتولى هذا العمل وهو ختان الصبيان البالغين، ولاسيما من بلغ هذا السن فإن هذا منكر، وليس هذا من الأمور التي يعجز عنها، بل هذا ميسر الرجال، فإذا بلغ الطفل سبع سنين باشره الرجال ، وليس لها أن تباشر الصبيان إلا ما دون السبع السنين ، أما ما فوق السبع السنين أن يوكل إلى الرجال ولا يجوز أن يوكل إلى النساء إلا في حالة الضرورة، بأن لا يوجد من لا يتولى الختان من الرجال، وهذا بعيد؛ لأن هذا متيسر. ، المقصود أنه متيسر للرجال، فلا ينبغي أن تولى المرأة هذا الشيء، بل لا يجوز.","link":"https://binbaz.org.sa/fatwas/26544/هل-يجوز-للممرضة-التي-تقوم-بالختانة-ان-تختن-لمن-كان-كبيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D9%87%D9%84%20%D9%8A%D8%AC%D9%88%D8%B2%20%D9%84%D9%84%D9%85%D9%85%D8%B1%D8%B6%D8%A9%20%D8%A7%D9%84%D8%AA%D9%8A%20%D8%AA%D9%82%D9%88%D9%85%20%D8%A8%D8%A7%D9%84%D8%AE%D8%AA%D8%A7%D9%86%D8%A9%20%D8%A3%D9%86%20%D8%AA%D8%AE%D8%AA%D9%86%20%D9%84%D9%85%D9%86%20%D9%83%D8%A7%D9%86%20%D9%83%D8%A8%D9%8A%D8%B1%D8%A7.MP3","categories":["سنن الفطرة"]}]
